CREATE FUNCTION public.backfill_gateway_request_normalized_usage(p_since timestamp with time zone DEFAULT (now() - '90 days'::interval), p_until timestamp with time zone DEFAULT now()) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_count bigint;
begin
  update public.gateway_requests
  set usage = usage
  where created_at >= p_since
    and created_at < p_until;

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


