--
-- Name: claim_data_contributions(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_data_contributions(p_limit integer DEFAULT 25, p_lease_seconds integer DEFAULT 300) RETURNS SETOF public.data_contributions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return query
  with candidates as (
    select contribution.id
    from public.data_contributions contribution
    where contribution.status in ('pending', 'failed', 'processing')
      and case
        when contribution.status = 'processing' then contribution.lease_expires_at
        else contribution.available_at
      end <= now()
      and contribution.retention_until > now()
    order by
      case
        when contribution.status = 'processing' then contribution.lease_expires_at
        else contribution.available_at
      end,
      contribution.occurred_at,
      contribution.id
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 25), 250))
  )
  update public.data_contributions contribution
  set status = 'processing',
      attempt_count = contribution.attempt_count + 1,
      lease_expires_at = now() + make_interval(secs => greatest(30, least(coalesce(p_lease_seconds, 300), 3600))),
      updated_at = now()
  from candidates
  where contribution.id = candidates.id
  returning contribution.*;
end;
$$;


--
-- Name: claim_gateway_async_operations_for_reconciliation(text, integer, text[], text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_gateway_async_operations_for_reconciliation(p_kind text, p_limit integer DEFAULT 100, p_statuses text[] DEFAULT NULL::text[], p_worker_id text DEFAULT 'gateway-reconciler'::text, p_lease_seconds integer DEFAULT 120, p_shard_count integer DEFAULT 1, p_shard_index integer DEFAULT 0) RETURNS TABLE(workspace_id uuid, kind text, internal_id text, request_id text, session_id text, app_id uuid, provider text, native_id text, model text, status text, meta jsonb, billed_at timestamp with time zone, next_reconcile_at timestamp with time zone, reconcile_attempts integer, reconcile_locked_at timestamp with time zone, reconcile_locked_by text, last_reconcile_error text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 100), 2000));
  v_lease_seconds integer := greatest(30, least(coalesce(p_lease_seconds, 120), 3600));
  v_shard_count integer := greatest(1, least(coalesce(p_shard_count, 1), 256));
  v_shard_index integer := greatest(0, least(coalesce(p_shard_index, 0), greatest(1, least(coalesce(p_shard_count, 1), 256)) - 1));
  v_worker_id text := left(coalesce(nullif(trim(p_worker_id), ''), 'gateway-reconciler'), 200);
begin
  return query
  with candidates as (
    select op.id
    from public.gateway_async_operations op
    where op.kind = p_kind
      and op.billed_at is null
      and (op.next_reconcile_at is null or op.next_reconcile_at <= now())
      and (
        op.reconcile_locked_at is null
        or op.reconcile_locked_at < now() - make_interval(secs => v_lease_seconds)
      )
      and (
        p_statuses is null
        or coalesce(op.status, '') = any(p_statuses)
      )
      and not (op.kind = 'batch' and op.meta->>'resource' = 'file')
      and (
        v_shard_count = 1
        or mod(
          mod(hashtextextended(op.workspace_id::text || ':' || op.internal_id, 0), v_shard_count::bigint)
            + v_shard_count::bigint,
          v_shard_count::bigint
        ) = v_shard_index::bigint
      )
    order by op.next_reconcile_at asc nulls first, op.updated_at asc
    limit v_limit
    for update skip locked
  ),
  claimed as (
    update public.gateway_async_operations op
    set
      reconcile_locked_at = now(),
      reconcile_locked_by = v_worker_id,
      reconcile_attempts = op.reconcile_attempts + 1,
      updated_at = now()
    from candidates
    where op.id = candidates.id
    returning op.*
  )
  select
    claimed.workspace_id,
    claimed.kind,
    claimed.internal_id,
    claimed.request_id,
    claimed.session_id,
    claimed.app_id,
    claimed.provider,
    claimed.native_id,
    claimed.model,
    claimed.status,
    claimed.meta,
    claimed.billed_at,
    claimed.next_reconcile_at,
    claimed.reconcile_attempts,
    claimed.reconcile_locked_at,
    claimed.reconcile_locked_by,
    claimed.last_reconcile_error,
    claimed.created_at,
    claimed.updated_at
  from claimed
  order by claimed.next_reconcile_at asc nulls first, claimed.updated_at asc;
end;
$$;


--
-- Name: FUNCTION claim_gateway_async_operations_for_reconciliation(p_kind text, p_limit integer, p_statuses text[], p_worker_id text, p_lease_seconds integer, p_shard_count integer, p_shard_index integer); Type: COMMENT; Schema: public; Owner: -
--

