-- Name: claim_gateway_async_webhook_delivery(uuid, text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_gateway_async_webhook_delivery(p_workspace_id uuid, p_kind text, p_internal_id text, p_delivery_key text, p_claim_token text, p_stale_after_seconds integer DEFAULT 300) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row public.gateway_async_webhook_deliveries%rowtype;
begin
  if p_workspace_id is null or coalesce(trim(p_kind), '') = ''
     or coalesce(trim(p_internal_id), '') = '' or coalesce(trim(p_delivery_key), '') = ''
     or coalesce(trim(p_claim_token), '') = '' then
    raise exception 'invalid_webhook_delivery_claim';
  end if;

  insert into public.gateway_async_webhook_deliveries (
    workspace_id, kind, internal_id, delivery_key, status, claim_token, claimed_at, updated_at
  ) values (
    p_workspace_id, p_kind, p_internal_id, p_delivery_key, 'claimed', p_claim_token, now(), now()
  ) on conflict do nothing;

  select * into v_row
  from public.gateway_async_webhook_deliveries
  where workspace_id = p_workspace_id and kind = p_kind
    and internal_id = p_internal_id and delivery_key = p_delivery_key
  for update;

  if v_row.status = 'delivered' then return false; end if;
  if v_row.status = 'claimed' and v_row.claim_token <> p_claim_token
     and v_row.claimed_at > now() - make_interval(secs => greatest(30, p_stale_after_seconds)) then
    return false;
  end if;

  update public.gateway_async_webhook_deliveries
  set status = 'claimed', claim_token = p_claim_token, claimed_at = now(), updated_at = now()
  where workspace_id = p_workspace_id and kind = p_kind
    and internal_id = p_internal_id and delivery_key = p_delivery_key;
  return true;
end;
$$;


--
-- Name: otel_export_outbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.otel_export_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    destination_id uuid NOT NULL,
    event_id text NOT NULL,
    payload jsonb NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    lease_expires_at timestamp with time zone,
    delivered_at timestamp with time zone,
    last_http_status integer,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT otel_export_outbox_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'delivered'::text, 'failed'::text])))
);


--
-- Name: claim_otel_export_outbox(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_otel_export_outbox(p_limit integer DEFAULT 100) RETURNS SETOF public.otel_export_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  with candidates as (
    select id
    from public.otel_export_outbox
    where (
      status = 'pending'
      or (status = 'processing' and lease_expires_at < now())
    )
      and next_attempt_at <= now()
    order by next_attempt_at, created_at
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 100), 500))
  ),
  claimed as (
    update public.otel_export_outbox outbox
    set status = 'processing',
        attempts = attempts + 1,
        lease_expires_at = now() + interval '15 minutes',
        updated_at = now()
    from candidates
    where outbox.id = candidates.id
    returning outbox.*
  )
  select * from claimed;
end;
$$;


--
-- Name: cleanup_dormant_enterprise_workspaces(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_dormant_enterprise_workspaces() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return jsonb_build_object(
    'total_teams_checked', 0,
    'teams_downgraded', 0,
    'downgraded_teams', '[]'::jsonb,
    'processed_at', now()
  );
end;
$$;


--
-- Name: cleanup_expired_oauth_artifacts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_expired_oauth_artifacts() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  delete from public.oauth_authorization_codes where expires_at < now() - interval '1 hour';
  delete from public.oauth_device_codes where expires_at < now() - interval '1 hour';
  delete from public.oauth_refresh_tokens token
  where token.expires_at < now() - interval '1 day'
    and not exists (
      select 1 from public.oauth_refresh_tokens child
      where child.rotated_from = token.id
    );
end;
$$;


--
-- Name: commit_model_discovery_snapshot(uuid, text[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commit_model_discovery_snapshot(p_run_id uuid, p_provider_ids text[], p_current_models jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  deleted_count integer := 0;
begin
  if exists (
    select 1
    from jsonb_to_recordset(coalesce(p_current_models, '[]'::jsonb)) as model(provider_id text)
    where not (model.provider_id = any(coalesce(p_provider_ids, array[]::text[])))
  ) then
    raise exception 'Snapshot contains a provider outside p_provider_ids';
  end if;

  with current_models as (
    select model.provider_id, model.model_id
    from jsonb_to_recordset(coalesce(p_current_models, '[]'::jsonb)) as model(
      provider_id text,
      model_id text
    )
  ), deleted as (
    delete from public.model_discovery_seen_models seen
    where seen.provider_id = any(coalesce(p_provider_ids, array[]::text[]))
      and not exists (
        select 1 from current_models current
        where current.provider_id = seen.provider_id and current.model_id = seen.model_id
      )
    returning 1
  )
  select count(*) into deleted_count from deleted;

  insert into public.model_discovery_seen_models (
    provider_id,
    provider_name,
    model_id,
    model_details,
    pricing_details,
    last_seen_at,
    last_run_id
  )
  select
    model.provider_id,
    model.provider_name,
    model.model_id,
    coalesce(model.model_details, '{}'::jsonb),
    model.pricing_details,
    coalesce(model.last_seen_at, now()),
    p_run_id
  from jsonb_to_recordset(coalesce(p_current_models, '[]'::jsonb)) as model(
    provider_id text,
    provider_name text,
    model_id text,
    model_details jsonb,
    pricing_details jsonb,
    last_seen_at timestamptz
  )
  on conflict (provider_id, model_id) do update set
    provider_name = excluded.provider_name,
    model_details = excluded.model_details,
    pricing_details = excluded.pricing_details,
    last_seen_at = excluded.last_seen_at,
    last_run_id = excluded.last_run_id;

  return deleted_count;
end;
$$;


--
-- Name: compare_model_discovery_snapshot(text[], text[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compare_model_discovery_snapshot(p_provider_ids text[], p_snapshot_provider_ids text[], p_current_models jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with current_models as (
    select
      model.provider_id,
      model.model_id,
      coalesce(model.model_details, '{}'::jsonb) as model_details,
      model.pricing_details
    from jsonb_to_recordset(coalesce(p_current_models, '[]'::jsonb)) as model(
      provider_id text,
      model_id text,
      model_details jsonb,
      pricing_details jsonb
    )
    where model.provider_id = any(coalesce(p_provider_ids, array[]::text[]))
  ),
  providers as (
    select distinct provider_id
    from unnest(coalesce(p_provider_ids, array[]::text[])) as provider_id
  ),
  existing_models as (
    select seen.provider_id, seen.model_id, seen.model_details, seen.pricing_details
    from public.model_discovery_seen_models as seen
    join providers using (provider_id)
  ),
  provider_diffs as (
    select
      provider.provider_id,
      (select count(*) from existing_models old where old.provider_id = provider.provider_id) as previous_count,
      (select count(*) from current_models current where current.provider_id = provider.provider_id) as current_count,
      coalesce((
        select jsonb_agg(current.model_id order by current.model_id)
        from current_models current
        where current.provider_id = provider.provider_id
          and not exists (
            select 1 from existing_models old
            where old.provider_id = current.provider_id and old.model_id = current.model_id
          )
      ), '[]'::jsonb) as added,
      coalesce((
        select jsonb_agg(old.model_id order by old.model_id)
        from existing_models old
        where old.provider_id = provider.provider_id
          and not exists (
            select 1 from current_models current
            where current.provider_id = old.provider_id and current.model_id = old.model_id
          )
      ), '[]'::jsonb) as removed
    from providers provider
  ),
  changed_snapshots as (
    select old.provider_id, old.model_id, old.model_details, old.pricing_details
    from existing_models old
    join current_models current using (provider_id, model_id)
    where old.provider_id = any(coalesce(p_snapshot_provider_ids, array[]::text[]))
      and (
        old.model_details is distinct from current.model_details
        or old.pricing_details is distinct from current.pricing_details
      )
  ),
  snapshot_baselines as (
    select distinct old.provider_id
    from existing_models old
    where old.provider_id = any(coalesce(p_snapshot_provider_ids, array[]::text[]))
      and (old.pricing_details is not null or old.model_details <> '{}'::jsonb)
  )
  select jsonb_build_object(
    'providers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'provider_id', provider_id,
        'previous_count', previous_count,
        'current_count', current_count,
        'added', added,
        'removed', removed
      ) order by provider_id)
      from provider_diffs
    ), '[]'::jsonb),
    'changed_snapshots', coalesce((
      select jsonb_agg(jsonb_build_object(
        'provider_id', provider_id,
        'model_id', model_id,
        'model_details', model_details,
        'pricing_details', pricing_details
      ) order by provider_id, model_id)
      from changed_snapshots
    ), '[]'::jsonb),
    'snapshot_baseline_provider_ids', coalesce((
      select jsonb_agg(provider_id order by provider_id) from snapshot_baselines
    ), '[]'::jsonb)
  );
$$;


--
-- Name: complete_gateway_async_webhook_delivery(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_gateway_async_webhook_delivery(p_workspace_id uuid, p_kind text, p_internal_id text, p_delivery_key text, p_claim_token text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with changed as (
    update public.gateway_async_webhook_deliveries
    set status = 'delivered', claim_token = null, delivered_at = now(), updated_at = now()
    where workspace_id = p_workspace_id and kind = p_kind
      and internal_id = p_internal_id and delivery_key = p_delivery_key
      and status = 'claimed' and claim_token = p_claim_token
    returning 1
  ) select exists(select 1 from changed);
$$;


--
-- Name: confirm_model_discovery_issue_signals(uuid, text[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_model_discovery_issue_signals(p_run_id uuid, p_successful_provider_ids text[], p_entries jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  confirmed jsonb := '[]'::jsonb;
begin
  -- A returning model cancels its pending deletion signal.
  delete from public.model_discovery_issue_signals signal
  where signal.action = 'delete'
    and signal.provider_id = any(coalesce(p_successful_provider_ids, array[]::text[]))
    and exists (
      select 1
      from public.model_discovery_seen_models seen
      where seen.provider_id = signal.provider_id
        and seen.model_id = signal.model_id
    );

  -- Existing absent candidates have now survived another successful sweep.
  update public.model_discovery_issue_signals signal
  set
    consecutive_sweeps = signal.consecutive_sweeps + 1,
    last_observed_at = now(),
    last_observed_run_id = p_run_id
  where signal.action = 'delete'
    and signal.emitted_at is null
    and signal.provider_id = any(coalesce(p_successful_provider_ids, array[]::text[]))
    and signal.last_observed_run_id is distinct from p_run_id
    and not exists (
      select 1
      from public.model_discovery_seen_models seen
      where seen.provider_id = signal.provider_id
        and seen.model_id = signal.model_id
    );

  -- New deletion candidates begin at one observed sweep. Other actions are
  -- returned immediately and do not require confirmation.
  insert into public.model_discovery_issue_signals (
    source,
    provider_id,
    action,
    model_id,
    entry,
    consecutive_sweeps,
    first_observed_at,
    last_observed_at,
    last_observed_run_id
  )
  select
    raw.value ->> 'source',
    raw.value ->> 'providerId',
    raw.value ->> 'action',
    raw.value ->> 'modelId',
    raw.value,
    1,
    now(),
    now(),
    p_run_id
  from jsonb_array_elements(coalesce(p_entries, '[]'::jsonb)) raw(value)
  where raw.value ->> 'action' = 'delete'
    and raw.value ->> 'providerId' = any(coalesce(p_successful_provider_ids, array[]::text[]))
  on conflict (source, provider_id, action, model_id) do update set
    entry = excluded.entry,
    last_observed_at = excluded.last_observed_at,
    last_observed_run_id = excluded.last_observed_run_id;

  with immediate_entries as (
    select value as entry
    from jsonb_array_elements(coalesce(p_entries, '[]'::jsonb))
    where value ->> 'action' <> 'delete'
  ), confirmed_deletions as (
    select signal.entry
    from public.model_discovery_issue_signals signal
    where signal.action = 'delete'
      and signal.emitted_at is null
      and signal.consecutive_sweeps >= 2
      and signal.provider_id = any(coalesce(p_successful_provider_ids, array[]::text[]))
  ), all_confirmed as (
    select entry from immediate_entries
    union all
    select entry from confirmed_deletions
  )
  select coalesce(jsonb_agg(entry), '[]'::jsonb)
  into confirmed
  from all_confirmed;

  return confirmed;
end;
$$;


--
-- Name: consume_oauth_code_and_issue_managed_key(uuid, text, text, text, text, uuid, uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_oauth_code_and_issue_managed_key(p_code_id uuid, p_key_hash text, p_key_kid text, p_key_prefix text, p_key_name text, p_user_id uuid, p_workspace_id uuid, p_client_id text, p_scopes text[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  granted_scopes text[];
begin
  if not (coalesce(p_scopes, array[]::text[]) @> array['gateway:access']::text[]) then
    return 'invalid';
  end if;

  -- Match the workspace-member deletion trigger's lock order.
  perform 1
  from public.workspace_members member
  where member.user_id = p_user_id
    and member.workspace_id = p_workspace_id
  for key share;

  if not found then
    return 'invalid';
  end if;

  perform 1
  from public.oauth_authorizations authorization_row
  where authorization_row.user_id = p_user_id
    and authorization_row.workspace_id = p_workspace_id
    and authorization_row.client_id = p_client_id
    and authorization_row.revoked_at is null
    and coalesce(authorization_row.scopes, array[]::text[]) @> array['gateway:access']::text[]
  for update;

  if not found then
    return 'invalid';
  end if;

  update public.oauth_authorization_codes authorization_code
  set used_at = now()
  where authorization_code.id = p_code_id
    and authorization_code.used_at is null
    and authorization_code.expires_at > now()
    and authorization_code.user_id = p_user_id
    and authorization_code.workspace_id = p_workspace_id
    and authorization_code.client_id = p_client_id
    and coalesce(authorization_code.scopes, array[]::text[]) @> array['gateway:access']::text[]
    and coalesce(authorization_code.scopes, array[]::text[]) <@ coalesce(p_scopes, array[]::text[])
    and coalesce(p_scopes, array[]::text[]) <@ coalesce(authorization_code.scopes, array[]::text[])
  returning authorization_code.scopes into granted_scopes;

  if not found then
    return 'invalid';
  end if;

  update public.keys
  set status = 'revoked'
  where key_kind = 'oauth_delegated'
    and oauth_user_id = p_user_id
    and workspace_id = p_workspace_id
    and oauth_client_id = p_client_id
    and status = 'active';

  insert into public.keys (
    workspace_id, name, hash, prefix, status, scopes, created_by, kid,
    key_kind, oauth_client_id, oauth_user_id, oauth_scopes, issued_via
  ) values (
    p_workspace_id, p_key_name, p_key_hash, p_key_prefix, 'active', '[]', p_user_id, p_key_kid,
    'oauth_delegated', p_client_id, p_user_id, granted_scopes, 'oauth_pkce'
  );

  return 'issued';
end;
$$;


--
-- Name: consume_oauth_code_and_issue_managed_key(uuid, text, text, text, text, uuid, uuid, text, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_oauth_code_and_issue_managed_key(p_code_id uuid, p_key_hash text, p_key_kid text, p_key_prefix text, p_key_name text, p_user_id uuid, p_workspace_id uuid, p_client_id text, p_scopes text[], p_resource text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  granted_scopes text[];
  granted_resource text;
  resource_is_gateway boolean;
begin
  resource_is_gateway := coalesce(
    btrim(p_resource) ~* '^https://api\.phaseo\.app(?::443)?/v1/*$',
    false
  );

  -- Unbound and Gateway-bound credentials both authorize billable API use.
  if (nullif(btrim(p_resource), '') is null or resource_is_gateway)
    and not (coalesce(p_scopes, array[]::text[]) @> array['gateway:access']::text[])
  then
    return 'invalid';
  end if;

  perform 1
  from public.workspace_members member
  where member.user_id = p_user_id
    and member.workspace_id = p_workspace_id
  for key share;

  if not found then
    return 'invalid';
  end if;

  perform 1
  from public.oauth_authorizations authorization_row
  where authorization_row.user_id = p_user_id
    and authorization_row.workspace_id = p_workspace_id
    and authorization_row.client_id = p_client_id
    and authorization_row.revoked_at is null
    and coalesce(authorization_row.scopes, array[]::text[]) @> coalesce(p_scopes, array[]::text[])
    and (
      (nullif(btrim(p_resource), '') is not null and not resource_is_gateway)
      or coalesce(authorization_row.scopes, array[]::text[]) @> array['gateway:access']::text[]
    )
  for update;

  if not found then
    return 'invalid';
  end if;

  update public.oauth_authorization_codes authorization_code
  set used_at = now()
  where authorization_code.id = p_code_id
    and authorization_code.used_at is null
    and authorization_code.expires_at > now()
    and authorization_code.user_id = p_user_id
    and authorization_code.workspace_id = p_workspace_id
    and authorization_code.client_id = p_client_id
    and authorization_code.resource is not distinct from nullif(btrim(p_resource), '')
    and (
      (authorization_code.resource is not null and not resource_is_gateway)
      or coalesce(authorization_code.scopes, array[]::text[]) @> array['gateway:access']::text[]
    )
    and coalesce(authorization_code.scopes, array[]::text[]) <@ coalesce(p_scopes, array[]::text[])
    and coalesce(p_scopes, array[]::text[]) <@ coalesce(authorization_code.scopes, array[]::text[])
  returning authorization_code.scopes, authorization_code.resource
    into granted_scopes, granted_resource;

  if not found then
    return 'invalid';
  end if;

  update public.keys
  set status = 'revoked'
  where key_kind = 'oauth_delegated'
    and oauth_user_id = p_user_id
    and workspace_id = p_workspace_id
    and oauth_client_id = p_client_id
    and oauth_resource is not distinct from granted_resource
    and status = 'active';

  insert into public.keys (
    workspace_id, name, hash, prefix, status, scopes, created_by, kid,
    key_kind, oauth_client_id, oauth_user_id, oauth_scopes, oauth_resource, issued_via, expires_at
  ) values (
    p_workspace_id, p_key_name, p_key_hash, p_key_prefix, 'active', '[]', p_user_id, p_key_kid,
    'oauth_delegated', p_client_id, p_user_id, granted_scopes, granted_resource, 'oauth_pkce', now() + interval '7 days'
  );

  return 'issued';
end;
$_$;


--
-- Name: consume_oauth_grant_and_issue_refresh_token(text, uuid, text, uuid, uuid, text, text[], timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_oauth_grant_and_issue_refresh_token(p_grant_type text, p_grant_id uuid, p_token_hash text, p_user_id uuid, p_workspace_id uuid, p_client_id text, p_scopes text[], p_expires_at timestamp with time zone, p_family_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- Lock membership before authorization to match the member-delete trigger.
  perform 1
  from public.workspace_members member
  where member.user_id = p_user_id
    and member.workspace_id = p_workspace_id
  for key share;

  if not found then
    return 'invalid';
  end if;

  perform 1
  from public.oauth_authorizations authorization_row
  where authorization_row.user_id = p_user_id
    and authorization_row.workspace_id = p_workspace_id
    and authorization_row.client_id = p_client_id
    and authorization_row.revoked_at is null
  for update;

  if not found then
    return 'invalid';
  end if;

  if p_grant_type = 'device_code' then
    update public.oauth_device_codes device_code
    set consumed_at = now()
    where device_code.id = p_grant_id
      and device_code.consumed_at is null
      and device_code.status = 'approved'
      and device_code.expires_at > now()
      and device_code.user_id = p_user_id
      and device_code.workspace_id = p_workspace_id
      and device_code.client_id = p_client_id;
  elsif p_grant_type = 'authorization_code' then
    update public.oauth_authorization_codes authorization_code
    set used_at = now()
    where authorization_code.id = p_grant_id
      and authorization_code.used_at is null
      and authorization_code.expires_at > now()
      and authorization_code.user_id = p_user_id
      and authorization_code.workspace_id = p_workspace_id
      and authorization_code.client_id = p_client_id;
  else
    return 'invalid';
  end if;

  if not found then
    return 'invalid';
  end if;

  insert into public.oauth_refresh_tokens (
    token_hash, user_id, workspace_id, client_id, scopes, expires_at, family_id
  ) values (
    p_token_hash, p_user_id, p_workspace_id, p_client_id, p_scopes, p_expires_at, p_family_id
  );

  return 'issued';
end;
$$;


--
-- Name: copy_v2_performance_metrics_from_metadata(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.copy_v2_performance_metrics_from_metadata() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  performance jsonb := coalesce(new.safe_metadata->'performance', '{}'::jsonb);
begin
  if performance ? 'provider_ttft_ms' then
    new.provider_ttft_ms := nullif(greatest(0, round(nullif(performance->>'provider_ttft_ms', '')::numeric)), 0)::integer;
  end if;
  if performance ? 'gateway_ttft_ms' then
    new.gateway_ttft_ms := nullif(greatest(0, round(nullif(performance->>'gateway_ttft_ms', '')::numeric)), 0)::integer;
  end if;
  if performance ? 'output_speed_tps' then
    new.output_speed_tps := nullif(greatest(0, nullif(performance->>'output_speed_tps', '')::numeric), 0);
  end if;
  if performance ? 'tpot_ms' then
    new.tpot_ms := nullif(greatest(0, nullif(performance->>'tpot_ms', '')::numeric), 0);
  end if;
  if performance ? 'itl_ms' then
    new.itl_ms := nullif(greatest(0, nullif(performance->>'itl_ms', '')::numeric), 0);
  end if;
  if performance ? 'phaseo_overhead_ms' then
    new.phaseo_overhead_ms := greatest(0, round(nullif(performance->>'phaseo_overhead_ms', '')::numeric))::integer;
  end if;
  return new;
end;
$$;


--
-- Name: deduct_and_check_top_up(uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deduct_and_check_top_up(p_workspace_id uuid, p_cost_nanos bigint) RETURNS json
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_new_balance bigint;
  v_low_threshold bigint;
  v_auto_top_up_amount bigint;
  v_auto_top_up_enabled boolean;
  v_auto_top_up_account_id text;
  v_stripe_customer_id text;
begin
  if p_cost_nanos is null or p_cost_nanos <= 0 then
    raise exception 'invalid_cost_nanos';
  end if;
  update public.wallets
  set balance_nanos = balance_nanos - p_cost_nanos
  where workspace_id = p_workspace_id
    and balance_nanos - p_cost_nanos >= coalesce(reserved_nanos, 0)
  returning balance_nanos, low_balance_threshold, auto_top_up_amount,
    auto_top_up_enabled, auto_top_up_account_id, stripe_customer_id
  into v_new_balance, v_low_threshold, v_auto_top_up_amount,
    v_auto_top_up_enabled, v_auto_top_up_account_id, v_stripe_customer_id;

  if v_new_balance is null then
    if exists (select 1 from public.wallets where workspace_id = p_workspace_id) then
      raise exception 'insufficient_unreserved_balance';
    end if;
    return json_build_object('status', 'wallet_not_found');
  end if;
  if v_auto_top_up_enabled and v_new_balance < v_low_threshold then
    return json_build_object(
      'status', 'top_up_required',
      'auto_top_up_amount_nanos', v_auto_top_up_amount,
      'auto_top_up_account_id', v_auto_top_up_account_id,
      'stripe_customer_id', v_stripe_customer_id,
      'new_balance_nanos', v_new_balance
    );
  end if;
  return json_build_object('status', 'top_up_not_required', 'new_balance_nanos', v_new_balance);
end;
$$;


--
-- Name: default_workspace_publisher_handle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.default_workspace_publisher_handle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
begin
  if nullif(new.publisher_handle, '') is null then
    new.publisher_handle := lower(regexp_replace(regexp_replace(coalesce(nullif(new.slug, ''), new.name), '[^a-zA-Z0-9_-]+', '-', 'g'), '^-+|-+$', '', 'g'));
    if length(new.publisher_handle) < 3 then
      new.publisher_handle := 'workspace-' || left(new.id::text, 8);
    end if;
  end if;
  return new;
end
$_$;


--
-- Name: enforce_byok_key_provider_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_byok_key_provider_limit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  existing_key_count integer;
  excluded_key_id uuid;
begin
  if tg_op = 'UPDATE'
    and new.workspace_id is not distinct from old.workspace_id
    and new.provider_id is not distinct from old.provider_id then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    excluded_key_id := old.id;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(new.workspace_id::text || ':' || new.provider_id, 0)
  );

  select count(*)
  into existing_key_count
  from public.byok_keys
  where workspace_id = new.workspace_id
    and provider_id = new.provider_id
    and (excluded_key_id is null or id <> excluded_key_id);

  if existing_key_count >= 32 then
    raise exception 'BYOK key limit reached for workspace provider'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


--
-- Name: FUNCTION enforce_byok_key_provider_limit(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_byok_key_provider_limit() IS 'Caps stored BYOK credentials at 32 per workspace/provider using a transaction-scoped advisory lock.';


--
-- Name: enforce_oauth_device_poll_interval(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_oauth_device_poll_interval(p_device_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  device public.oauth_device_codes%rowtype;
begin
  select * into device
  from public.oauth_device_codes
  where id = p_device_id
  for update;

  if not found then return 'invalid'; end if;

  if device.last_polled_at is not null
     and device.last_polled_at + make_interval(secs => device.interval_seconds) > now() then
    update public.oauth_device_codes
    set last_polled_at = now(), interval_seconds = interval_seconds + 5
    where id = p_device_id;
    return 'slow_down';
  end if;

  update public.oauth_device_codes set last_polled_at = now() where id = p_device_id;
  return 'ok';
end;
$$;


--
-- Name: enforce_workspace_invite_role_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_workspace_invite_role_policy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if lower(coalesce(new.role::text, '')) not in ('admin', 'member') then
    raise exception using
      errcode = '23514',
      message = 'invalid_workspace_invite_role',
      detail = 'Invite roles are restricted to admin and member.';
  end if;

  return new;
end;
$$;


--
-- Name: enforce_workspace_join_request_write_rules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_workspace_join_request_write_rules() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.invite_id is not null then
    if not exists (
      select 1
      from public.team_invites ti
      where ti.id = new.invite_id
        and ti.team_id = new.team_id
    ) then
      raise exception using
        errcode = '23514',
        message = 'invite_team_mismatch',
        detail = 'Join request invite must belong to the same team.';
    end if;
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'pending'::join_request_status
       or new.decided_by is not null
       or new.decided_at is not null then
      raise exception using
        errcode = '23514',
        message = 'invalid_join_request_insert_state',
        detail = 'New join requests must be pending and undecided.';
    end if;
    return new;
  end if;

  -- UPDATE path
  if old.status <> 'pending'::join_request_status then
    raise exception using
      errcode = '23514',
      message = 'join_request_already_decided',
      detail = 'Only pending join requests can be updated.';
  end if;

  if new.status not in ('approved'::join_request_status, 'denied'::join_request_status) then
    raise exception using
      errcode = '23514',
      message = 'invalid_join_request_status_transition',
      detail = 'Join request updates must transition to approved or denied.';
  end if;

  if new.decided_by is null or new.decided_at is null then
    raise exception using
      errcode = '23514',
      message = 'join_request_decision_metadata_required',
      detail = 'Decided join requests must include decided_by and decided_at.';
  end if;

  if new.team_id <> old.team_id or new.requester_user_id <> old.requester_user_id then
    raise exception using
      errcode = '23514',
      message = 'join_request_immutable_fields_modified',
      detail = 'team_id and requester_user_id are immutable.';
  end if;

  if new.invite_id is distinct from old.invite_id then
    raise exception using
      errcode = '23514',
      message = 'join_request_invite_immutable',
      detail = 'invite_id is immutable after request creation.';
  end if;

  return new;
end;
$$;


--
-- Name: enforce_workspace_member_role_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_workspace_member_role_policy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_owner_user_id uuid;
begin
  select w.owner_user_id
    into v_owner_user_id
  from public.workspaces w
  where w.id = new.workspace_id;

  if v_owner_user_id is null then
    raise exception using
      errcode = '23514',
      message = 'workspace_not_found_for_membership';
  end if;

  if new.user_id = v_owner_user_id then
    new.role := 'owner'::public.workspace_role;
    return new;
  end if;

  if lower(coalesce(new.role::text, '')) = 'owner' then
    raise exception using
      errcode = '23514',
      message = 'owner_role_reserved_for_workspace_owner',
      detail = 'Only workspaces.owner_user_id may have role=owner.';
  end if;

  if lower(coalesce(new.role::text, '')) not in ('admin', 'member') then
    raise exception using
      errcode = '23514',
      message = 'invalid_workspace_member_role',
      detail = 'Assignable roles are admin and member.';
  end if;

  return new;
end;
$$;


--
-- Name: enqueue_gateway_async_webhook_delivery(uuid, text, text, text, text, text, double precision, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_gateway_async_webhook_delivery(p_workspace_id uuid, p_kind text, p_internal_id text, p_delivery_key text, p_event_type text, p_phase text, p_progress double precision DEFAULT NULL::double precision, p_previous_status text DEFAULT NULL::text, p_current_status text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  insert into public.gateway_async_webhook_deliveries (
    workspace_id, kind, internal_id, delivery_key, status,
    event_type, phase, progress, previous_status, current_status,
    next_attempt_at, updated_at
  ) values (
    p_workspace_id, p_kind, p_internal_id, p_delivery_key, 'pending',
    p_event_type, p_phase, p_progress, p_previous_status, p_current_status,
    now(), now()
  ) on conflict (workspace_id, kind, internal_id, delivery_key) do nothing;
$$;


--
-- Name: enqueue_welcome_email(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_welcome_email() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_webhook_url text;
  v_request_id bigint;
  v_created_at text;
  v_stage text := 'start';
  v_error_message text;
  v_error_sqlstate text;
  v_error_detail text;
begin
  raise log '[signup-trigger] stage=start status=ok user_id=% email=%',
    new.id,
    coalesce(new.email, '');

  -- Mandatory: if this fails, abort signup.
  v_stage := 'public_users_upsert';
  begin
    insert into public.users (user_id)
    values (new.id)
    on conflict (user_id) do nothing;

    raise log '[signup-trigger] stage=% status=ok user_id=%', v_stage, new.id;
  exception when others then
    get stacked diagnostics
      v_error_message = message_text,
      v_error_sqlstate = returned_sqlstate,
      v_error_detail = pg_exception_detail;

    raise warning '[signup-trigger] stage=% status=error severity=mandatory user_id=% sqlstate=% message=% detail=%',
      v_stage,
      new.id,
      coalesce(v_error_sqlstate, ''),
      coalesce(v_error_message, sqlerrm),
      coalesce(v_error_detail, '');

    raise;
  end;

  -- Optional: direct Discord notify for each new auth user.
  v_stage := 'discord_webhook_url_resolve';
  v_webhook_url := nullif(trim(current_setting('app.settings.discord_signup_webhook_url', true)), '');
  if v_webhook_url is null then
    raise log '[signup-trigger] stage=% status=skip reason=discord_signup_webhook_url_not_configured user_id=%',
      v_stage,
      new.id;
    return new;
  end if;

  v_created_at := coalesce(new.created_at::text, (now() at time zone 'utc')::text);

  v_stage := 'discord_webhook_request';
  begin
    select net.http_post(
      url := v_webhook_url,
      headers := jsonb_build_object('Content-Type', 'application/json'),
      body := jsonb_build_object(
        'content',
        'New AI Stats signup' || E'\n' ||
        '- user_id: `' || new.id::text || '`' || E'\n' ||
        '- email: `' || coalesce(new.email, 'unknown') || '`' || E'\n' ||
        '- created_at: `' || v_created_at || '`',
        'allowed_mentions',
        jsonb_build_object('parse', jsonb_build_array())
      )
    )
    into v_request_id;

    raise log '[signup-trigger] stage=% status=ok user_id=% request_id=%', v_stage, new.id, v_request_id;
  exception when others then
    get stacked diagnostics
      v_error_message = message_text,
      v_error_sqlstate = returned_sqlstate,
      v_error_detail = pg_exception_detail;

    raise warning '[signup-trigger] stage=% status=error severity=optional user_id=% sqlstate=% message=% detail=%',
      v_stage,
      new.id,
      coalesce(v_error_sqlstate, ''),
      coalesce(v_error_message, sqlerrm),
      coalesce(v_error_detail, '');
  end;

  return new;
exception when others then
  get stacked diagnostics
    v_error_message = message_text,
    v_error_sqlstate = returned_sqlstate,
    v_error_detail = pg_exception_detail;

  raise warning '[signup-trigger] stage=% status=fatal user_id=% sqlstate=% message=% detail=%',
    coalesce(v_stage, 'unknown'),
    new.id,
    coalesce(v_error_sqlstate, ''),
    coalesce(v_error_message, sqlerrm),
    coalesce(v_error_detail, '');

  raise;
end;
$$;


--
-- Name: ensure_gateway_requests_partitions(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_gateway_requests_partitions(months_ahead integer DEFAULT 1) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_cur_month timestamptz;
  v_last_month timestamptz;
  v_gateway_partition_name text;
  v_upstream_partition_name text;
begin
  if months_ahead is null or months_ahead < 0 then
    raise exception 'months_ahead must be >= 0';
  end if;

  v_cur_month := date_trunc('month', now());
  v_last_month := v_cur_month + make_interval(months => months_ahead);
  while v_cur_month <= v_last_month loop
    v_gateway_partition_name := format('gateway_requests_%s', to_char(v_cur_month, 'YYYY_MM'));
    execute format(
      'create table if not exists public.%I partition of public.gateway_requests for values from (%L) to (%L)',
      v_gateway_partition_name,
      v_cur_month,
      v_cur_month + interval '1 month'
    );
    v_upstream_partition_name := format('gateway_upstream_requests_%s', to_char(v_cur_month, 'YYYY_MM'));
    execute format(
      'create table if not exists public.%I partition of public.gateway_upstream_requests for values from (%L) to (%L)',
      v_upstream_partition_name,
      v_cur_month,
      v_cur_month + interval '1 month'
    );
    v_cur_month := v_cur_month + interval '1 month';
  end loop;
end;
$$;


--
-- Name: FUNCTION ensure_gateway_requests_partitions(months_ahead integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ensure_gateway_requests_partitions(months_ahead integer) IS 'Maintains physical legacy operational partitions while V2 dual-write remains enabled; not an analytical read path.';


--
-- Name: finish_preset_creation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_preset_creation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare initial_version_id uuid;
begin
  insert into public.preset_lineage values (new.id, new.id, 0) on conflict do nothing;
  if new.source_preset_id is not null then
    insert into public.preset_lineage (ancestor_preset_id, descendant_preset_id, depth)
    select ancestor_preset_id, new.id, depth + 1 from public.preset_lineage
    where descendant_preset_id = new.source_preset_id on conflict do nothing;
  end if;
  insert into public.preset_versions (preset_id, version_number, version_label, versioning_method, name, slug, description, config, visibility, created_by)
  values (new.id, 1, case new.versioning_method when 'semver' then '1.0.0' when 'date' then to_char(current_date, 'YYYY.MM.DD') else 'v1' end, new.versioning_method, new.name, new.slug, new.description, new.config, new.visibility, new.created_by)
  returning id into initial_version_id;
  update public.presets set
    draft_name = new.name, draft_slug = new.slug, draft_description = new.description,
    draft_config = new.config, draft_visibility = new.visibility, active_version_id = initial_version_id
  where id = new.id;
  return new;
end $$;


--
-- Name: gateway_async_operation_video_webhook_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_async_operation_video_webhook_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_previous text;
  v_current text := lower(coalesce(new.status, ''));
  v_terminal_phase text;
begin
  if new.kind <> 'video'
     or new.meta->'webhook' is null
     or new.meta->'webhook' = 'null'::jsonb then
    return new;
  end if;

  if tg_op = 'INSERT' then
    perform public.enqueue_gateway_async_webhook_delivery(
      new.workspace_id, new.kind, new.internal_id,
      'video.created', 'video.created', 'created', null, null, v_current
    );
    return new;
  end if;

  v_previous := lower(coalesce(old.status, ''));
  if v_previous = v_current then return new; end if;

  perform public.enqueue_gateway_async_webhook_delivery(
    new.workspace_id, new.kind, new.internal_id,
    'video.status_changed:' || coalesce(nullif(v_previous, ''), 'unknown') || ':' || coalesce(nullif(v_current, ''), 'unknown'),
    'video.status_changed', 'status_changed', null,
    nullif(v_previous, ''), nullif(v_current, '')
  );

  v_terminal_phase := case v_current
    when 'completed' then 'completed'
    when 'failed' then 'failed'
    when 'cancelled' then 'cancelled'
    when 'canceled' then 'cancelled'
    when 'expired' then 'expired'
    else null
  end;
  if v_terminal_phase is not null then
    perform public.enqueue_gateway_async_webhook_delivery(
      new.workspace_id, new.kind, new.internal_id,
      'video.' || v_terminal_phase,
      'video.' || v_terminal_phase,
      v_terminal_phase,
      null,
      nullif(v_previous, ''),
      nullif(v_current, '')
    );
  end if;
  return new;
end;
$$;


--
-- Name: gateway_claim_batch_file_upload(uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_claim_batch_file_upload(p_workspace_id uuid, p_upload_id text, p_bytes bigint) RETURNS TABLE(ok boolean, reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_hour_count bigint;
  v_day_bytes bigint;
begin
  if p_workspace_id is null or coalesce(trim(p_upload_id), '') = '' or p_bytes is null or p_bytes <= 0 then
    raise exception 'invalid_batch_file_upload_claim';
  end if;
  if p_bytes > 20971520 then
    return query select false, 'batch_file_too_large'::text;
    return;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('batch-file:' || p_workspace_id::text, 0));
  if not exists (
    select 1 from public.wallets
    where workspace_id = p_workspace_id
      and coalesce(balance_nanos, 0) - coalesce(reserved_nanos, 0) > 0
  ) then
    return query select false, 'insufficient_funds'::text;
    return;
  end if;
  select count(*) into v_hour_count
  from public.gateway_batch_file_uploads
  where workspace_id = p_workspace_id and created_at >= now() - interval '1 hour';
  if v_hour_count >= 20 then
    return query select false, 'batch_file_hourly_quota_exceeded'::text;
    return;
  end if;
  select coalesce(sum(bytes), 0) into v_day_bytes
  from public.gateway_batch_file_uploads
  where workspace_id = p_workspace_id and created_at >= now() - interval '24 hours';
  if v_day_bytes + p_bytes > 104857600 then
    return query select false, 'batch_file_daily_bytes_exceeded'::text;
    return;
  end if;
  insert into public.gateway_batch_file_uploads (workspace_id, upload_id, bytes, status)
  values (p_workspace_id, p_upload_id, p_bytes, 'claimed')
  on conflict (workspace_id, upload_id) do nothing;
  if not found then
    return query select false, 'batch_file_upload_already_claimed'::text;
    return;
  end if;
  return query select true, null::text;
end;
$$;


--
-- Name: gateway_claim_provider_event(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_claim_provider_event(p_provider text, p_provider_event_id text, p_worker_id text DEFAULT 'batch-provider-webhook'::text, p_lease_seconds integer DEFAULT 120) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_claimed integer;
begin
  update public.gateway_provider_events event
  set replay_locked_at = now(),
      replay_locked_by = left(coalesce(nullif(trim(p_worker_id), ''), 'batch-provider-webhook'), 200),
      updated_at = now()
  where event.provider = nullif(trim(p_provider), '')
    and event.provider_event_id = nullif(trim(p_provider_event_id), '')
    and event.processed_at is null
    and event.dead_lettered_at is null
    and (event.next_attempt_at is null or event.next_attempt_at <= now())
    and (
      event.replay_locked_at is null
      or event.replay_locked_at < now() - make_interval(
        secs => greatest(30, least(coalesce(p_lease_seconds, 120), 3600))
      )
    );

  get diagnostics v_claimed = row_count;
  return v_claimed = 1;
end;
$$;


--
-- Name: gateway_provider_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.gateway_provider_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider text NOT NULL,
    provider_event_id text NOT NULL,
    kind text,
    workspace_id uuid,
    internal_id text,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    headers jsonb DEFAULT '{}'::jsonb NOT NULL,
    processed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone,
    last_error text,
    dead_lettered_at timestamp with time zone,
    replay_locked_at timestamp with time zone,
    replay_locked_by text
);


--
-- Name: TABLE gateway_provider_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.gateway_provider_events IS 'Webhook/provider event dedupe + processing audit trail for long-running operations.';


--
-- Name: gateway_claim_provider_events(text[], integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_claim_provider_events(p_providers text[], p_limit integer DEFAULT 100, p_worker_id text DEFAULT 'batch-provider-event-replay'::text, p_lease_seconds integer DEFAULT 120) RETURNS SETOF public.gateway_provider_events
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return query
  with candidates as (
    select event.id
    from public.gateway_provider_events event
    where event.provider = any(p_providers)
      and event.processed_at is null
      and event.dead_lettered_at is null
      and (event.next_attempt_at is null or event.next_attempt_at <= now())
      and (
        event.replay_locked_at is null
        or event.replay_locked_at < now() - make_interval(secs => greatest(30, least(coalesce(p_lease_seconds, 120), 3600)))
      )
    order by event.created_at asc
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 100), 500))
  )
  update public.gateway_provider_events event
  set replay_locked_at = now(),
      replay_locked_by = left(coalesce(nullif(trim(p_worker_id), ''), 'batch-provider-event-replay'), 200),
      updated_at = now()
  from candidates
  where event.id = candidates.id
  returning event.*;
end;
$$;


--
-- Name: gateway_cleanup_batch_hold_key_usage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_cleanup_batch_hold_key_usage() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status = 'released' and old.status is distinct from new.status and new.key_id is not null then
    delete from public.gateway_requests
    where workspace_id = new.workspace_id
      and key_id = new.key_id
      and request_id like 'batch_hold_usage:' || new.reservation_id || ':%';
  end if;
  return new;
end;
$$;


--
-- Name: gateway_deduct_and_check_top_up_once(uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_deduct_and_check_top_up_once(p_workspace_id uuid, p_request_id text, p_cost_nanos bigint) RETURNS TABLE(applied boolean, already_applied boolean, status text, auto_top_up_amount_nanos bigint, auto_top_up_account_id text, stripe_customer_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_charge public.gateway_request_charges%rowtype;
  v_result record;
  v_result_json jsonb;
  v_status text;
  v_auto_top_up_amount_nanos bigint;
  v_auto_top_up_account_id text;
  v_stripe_customer_id text;
begin
  if p_workspace_id is null then
    raise exception 'missing_workspace_id';
  end if;

  if coalesce(trim(p_request_id), '') = '' then
    raise exception 'missing_request_id';
  end if;

  if p_cost_nanos is null or p_cost_nanos <= 0 then
    raise exception 'invalid_cost_nanos';
  end if;

  insert into public.gateway_request_charges (
    workspace_id,
    request_id,
    cost_nanos,
    status,
    created_at,
    updated_at
  ) values (
    p_workspace_id,
    p_request_id,
    p_cost_nanos,
    'applying',
    now(),
    now()
  )
  on conflict (workspace_id, request_id) do nothing;

  select *
  into v_charge
  from public.gateway_request_charges
  where workspace_id = p_workspace_id
    and request_id = p_request_id
  for update;

  if not found then
    raise exception 'gateway_request_charge_row_missing';
  end if;

  if v_charge.cost_nanos <> p_cost_nanos then
    raise exception 'request_charge_amount_mismatch';
  end if;

  if v_charge.status = 'applied' then
    return query
    select
      false,
      true,
      coalesce(v_charge.deducted_status, 'already_applied')::text,
      0::bigint,
      null::text,
      null::text;
    return;
  end if;

  update public.gateway_request_charges
  set status = 'applying',
      error_message = null,
      updated_at = now()
  where workspace_id = p_workspace_id
    and request_id = p_request_id;

  begin
    select *
    into v_result
    from public.deduct_and_check_top_up(
      p_workspace_id := p_workspace_id,
      p_cost_nanos := p_cost_nanos
    );

    v_result_json := to_jsonb(v_result);
  exception when others then
    update public.gateway_request_charges
    set status = 'failed',
        error_message = sqlerrm,
        updated_at = now()
    where workspace_id = p_workspace_id
      and request_id = p_request_id;
    raise;
  end;

  v_status := coalesce(
    nullif(trim(v_result_json ->> 'status'), ''),
    nullif(trim(v_result_json ->> 'result'), ''),
    nullif(trim(v_result_json ->> 'deduct_and_check_top_up'), ''),
    'unknown'
  );

  v_auto_top_up_amount_nanos := case
    when coalesce(v_result_json ->> 'auto_top_up_amount_nanos', '') ~ '^-?[0-9]+$'
      then (v_result_json ->> 'auto_top_up_amount_nanos')::bigint
    when coalesce(v_result_json ->> 'auto_top_up_amount', '') ~ '^-?[0-9]+$'
      then (v_result_json ->> 'auto_top_up_amount')::bigint
    else 0::bigint
  end;

  v_auto_top_up_account_id := nullif(
    coalesce(
      v_result_json ->> 'auto_top_up_account_id',
      v_result_json ->> 'auto_top_up_payment_method_id',
      ''
    ),
    ''
  );

  v_stripe_customer_id := nullif(v_result_json ->> 'stripe_customer_id', '');

  update public.gateway_request_charges
  set status = 'applied',
      deducted_status = v_status,
      auto_top_up_required = v_status = 'top_up_required',
      updated_at = now()
  where workspace_id = p_workspace_id
    and request_id = p_request_id;

  return query
  select
    true,
    false,
    v_status,
    v_auto_top_up_amount_nanos,
    v_auto_top_up_account_id,
    v_stripe_customer_id;
end;
$_$;


--
-- Name: gateway_defer_provider_event(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_defer_provider_event(p_provider text, p_provider_event_id text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_next_attempt integer;
begin
  select attempt_count + 1 into v_next_attempt
  from public.gateway_provider_events
  where provider = p_provider and provider_event_id = p_provider_event_id
  for update;
  if not found then return; end if;

  update public.gateway_provider_events
  set attempt_count = v_next_attempt,
      last_error = left(coalesce(p_reason, 'provider_event_deferred'), 500),
      next_attempt_at = case
        when v_next_attempt >= 20 then null
        else now() + make_interval(secs => least(1800, 5 * (2 ^ least(v_next_attempt, 8))::integer))
      end,
      dead_lettered_at = case when v_next_attempt >= 20 then now() else dead_lettered_at end,
      processed_at = case when v_next_attempt >= 20 then now() else processed_at end,
      replay_locked_at = null,
      replay_locked_by = null,
      updated_at = now()
  where provider = p_provider and provider_event_id = p_provider_event_id;
end;
$$;


--
-- Name: gateway_feedback_summary(uuid, uuid[], text, text, text, text, uuid, uuid, timestamp with time zone, timestamp with time zone, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_feedback_summary(p_workspace_id uuid, p_visible_preset_ids uuid[], p_group_by text DEFAULT 'preset_id'::text, p_metadata_key text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_session_id text DEFAULT NULL::text, p_preset_id uuid DEFAULT NULL::uuid, p_test_run_id uuid DEFAULT NULL::uuid, p_created_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_created_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_metadata_filters jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 5000) RETURNS TABLE(group_value text, count bigint, positive bigint, negative bigint, partial bigint, average_score numeric, ratings jsonb, last_feedback_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if p_group_by not in ('preset_id', 'test_run_id', 'metadata') then
    raise exception 'invalid feedback summary grouping' using errcode = '22023';
  end if;
  if p_group_by = 'metadata'
     and (p_metadata_key is null or p_metadata_key !~ '^[a-zA-Z0-9_.:-]{1,64}$') then
    raise exception 'valid metadata key required for metadata grouping' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_metadata_filters, '{}'::jsonb)) <> 'object' then
    raise exception 'metadata filters must be a JSON object' using errcode = '22023';
  end if;

  return query
  with filtered as (
    select
      case p_group_by
        when 'preset_id' then feedback.preset_id::text
        when 'test_run_id' then feedback.test_run_id::text
        when 'metadata' then feedback.metadata_dimensions ->> p_metadata_key
      end as summary_group,
      feedback.rating,
      feedback.score,
      feedback.created_at
    from public.gateway_feedback as feedback
    where feedback.workspace_id = p_workspace_id
      and (feedback.preset_id is null or feedback.preset_id = any(coalesce(p_visible_preset_ids, '{}'::uuid[])))
      and (p_request_id is null or feedback.request_id = p_request_id)
      and (p_session_id is null or feedback.session_id = p_session_id)
      and (p_preset_id is null or feedback.preset_id = p_preset_id)
      and (p_test_run_id is null or feedback.test_run_id = p_test_run_id)
      and (p_created_since is null or feedback.created_at >= p_created_since)
      and (p_created_until is null or feedback.created_at <= p_created_until)
      and feedback.metadata_dimensions @> coalesce(p_metadata_filters, '{}'::jsonb)
  ),
  grouped as (
    select summary_group,
      count(*) as feedback_count,
      count(*) filter (where rating in ('thumbs_up', 'correct')) as positive_count,
      count(*) filter (where rating in ('thumbs_down', 'incorrect', 'unsafe')) as negative_count,
      count(*) filter (where rating = 'partly_correct') as partial_count,
      avg(score) filter (where score is not null) as mean_score,
      max(created_at) as latest_feedback_at
    from filtered
    where summary_group is not null and summary_group <> ''
    group by summary_group
  ),
  rating_counts as (
    select summary_group, coalesce(rating, 'unrated') as rating_key, count(*) as rating_count
    from filtered
    where summary_group is not null and summary_group <> ''
    group by summary_group, coalesce(rating, 'unrated')
  ),
  rating_totals as (
    select summary_group, jsonb_object_agg(rating_key, rating_count) as rating_map
    from rating_counts group by summary_group
  )
  select grouped.summary_group, grouped.feedback_count, grouped.positive_count,
    grouped.negative_count, grouped.partial_count, grouped.mean_score,
    coalesce(rating_totals.rating_map, '{}'::jsonb), grouped.latest_feedback_at
  from grouped left join rating_totals using (summary_group)
  order by grouped.latest_feedback_at desc, grouped.summary_group asc
  limit greatest(1, least(coalesce(p_limit, 5000), 10000));
end;
$_$;


--
-- Name: FUNCTION gateway_feedback_summary(p_workspace_id uuid, p_visible_preset_ids uuid[], p_group_by text, p_metadata_key text, p_request_id text, p_session_id text, p_preset_id uuid, p_test_run_id uuid, p_created_since timestamp with time zone, p_created_until timestamp with time zone, p_metadata_filters jsonb, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gateway_feedback_summary(p_workspace_id uuid, p_visible_preset_ids uuid[], p_group_by text, p_metadata_key text, p_request_id text, p_session_id text, p_preset_id uuid, p_test_run_id uuid, p_created_since timestamp with time zone, p_created_until timestamp with time zone, p_metadata_filters jsonb, p_limit integer) IS 'Service-role-only feedback aggregation constrained to caller-visible presets.';


--
-- Name: gateway_fetch_request_context(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_fetch_request_context(workspace_id uuid, model text, endpoint text, api_key_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  credit_status       jsonb;
  key_status          jsonb;
  key_limit_status    jsonb;
  min_balance_nanos   bigint := 1000000000; -- 1.00 USD

  providers           jsonb;
  pricing             jsonb;
  preset_data         jsonb := null;

  -- key row fields
  v_key_active        boolean;
  v_key_team_ok       boolean;
  v_soft_blocked      boolean;

  v_day_req_limit     bigint;
  v_wk_req_limit      bigint;
  v_mo_req_limit      bigint;
  v_day_cost_limit    bigint;
  v_wk_cost_limit     bigint;
  v_mo_cost_limit     bigint;

  now_utc             timestamptz := (now() at time zone 'utc');
  day_start           timestamptz := date_trunc('day',  now_utc);
  week_start          timestamptz := date_trunc('week', now_utc);   -- Monday 00:00 UTC
  month_start         timestamptz := date_trunc('month', now_utc);

  used_day_reqs       bigint;
  used_wk_reqs        bigint;
  used_mo_reqs        bigint;
  used_day_cost       bigint;
  used_wk_cost        bigint;
  used_mo_cost        bigint;

  within_limits       boolean := true;
  limit_reason        text := null;
  limit_window        text := null;
  limit_metric        text := null;
  current_value       bigint := null;
  limit_value         bigint := null;
  limit_reset_at      timestamptz := null;

  -- Preset handling
  is_preset           boolean := false;
  preset_name         text := null;
  preset_publisher    text := null;

  -- Resolve model from alias if exists
  resolved_model      text := gateway_fetch_request_context.model;
  base_model          text;

  team_enrichment     jsonb;
  key_enrichment      jsonb;

  -- Team aggregates
  team_total_requests bigint;
  team_total_spend_nanos bigint;
  team_spend_24h_nanos bigint;
  team_spend_7d_nanos bigint;
  team_spend_30d_nanos bigint;
  team_requests_1h bigint;
  team_requests_24h bigint;
  team_created_at timestamptz;
  team_tier text;
  team_balance_nanos bigint;
  team_reserved_nanos bigint;

  -- Key aggregates
  key_name text;
  key_created_at timestamptz;
  key_total_requests bigint;
  key_total_spend_nanos bigint;
begin
  base_model := gateway_fetch_request_context.model;
  -- hard requirement: key must be provided
  if gateway_fetch_request_context.api_key_id is null then
    raise exception using errcode = '22023', message = 'missing_api_key', detail = 'api_key_id is required';
  end if;

  -- Check if model is a preset (starts with @)
  if base_model like '@%' then
    is_preset := true;
    preset_name := substring(base_model from 2); -- Remove @ prefix

    -- Fetch preset configuration. Qualified references resolve a
    -- public publisher globally; unqualified references remain workspace-local.
    if position('/' in preset_name) > 0 then
      preset_publisher := split_part(preset_name, '/', 1);
      preset_name := substring(preset_name from position('/' in preset_name) + 1);
      select jsonb_build_object(
        'id', p.id, 'name', p.name, 'slug', p.slug, 'description', p.description,
        'config', p.config, 'visibility', p.visibility, 'publisher', w.publisher_handle
      ) into preset_data
      from public.presets p
      join public.workspaces w on w.id = p.workspace_id
      where p.archived_at is null and lower(p.slug) = lower(preset_name)
        and p.visibility = 'public'
        and true
        and (lower(w.publisher_handle) = lower(preset_publisher) or exists (select 1 from public.workspace_publisher_handle_aliases alias where alias.workspace_id = w.id and alias.handle = lower(preset_publisher)))
      limit 1;
    else
      select jsonb_build_object(
        'id', p.id, 'name', p.name,
        'slug', coalesce(nullif(p.slug, ''), regexp_replace(p.name, '^@', '')),
        'description', p.description, 'config', p.config, 'visibility', p.visibility
      ) into preset_data
      from public.presets p
      where p.archived_at is null and lower(coalesce(nullif(p.slug, ''), regexp_replace(p.name, '^@', ''))) = lower(preset_name)
        and p.workspace_id = gateway_fetch_request_context.workspace_id
        and (
          p.visibility in ('public', 'team')
          or p.created_by = (
            select ak.created_by from public.keys ak
            where ak.id = gateway_fetch_request_context.api_key_id
              and ak.workspace_id = gateway_fetch_request_context.workspace_id
              and ak.status = 'active'
          )
        )
      limit 1;
    end if;

    if preset_data is null then
      raise exception using
        errcode = '22023',
        message = 'preset_not_found',
        detail = format('Preset "%s" not found or not accessible', preset_name);
    end if;

    -- Extract model from preset config (fallback to default/default_model/model/first models entry)
    base_model := coalesce(
      preset_data->'config'->>'defaultModel',
      preset_data->'config'->>'default_model',
      preset_data->'config'->>'model',
      preset_data->'config'->'models'->>0,
      preset_data->'config'->'allowedModels'->>0,
      preset_data->'config'->'allowed_models'->>0
    );

    if base_model is null then
      raise exception using
        errcode = '22023',
        message = 'preset_no_model',
        detail = format('Preset "%s" has no model configured', preset_name);
    end if;
  end if;

  -- Resolve alias/model indirection:
  -- 1) explicit alias table (`v2_model_aliases`)
  -- 2) provider-scoped slug form (`provider/provider_model_slug`)
  resolved_model := coalesce(
    (
      select a.api_model_id
      from (select alias_slug, model_slug as api_model_id, enabled as is_enabled from public.v2_model_aliases) a
      where a.alias_slug = base_model
        and a.is_enabled = true
        and a.api_model_id is not null
      limit 1
    ),
    (
      select m.api_model_id
      from (select provider_model_id as provider_api_model_id, provider_slug as provider_id, model_slug as api_model_id, model_slug as model_id, provider_model_slug, routing_enabled as is_active_gateway, status as routing_status, input_modalities, output_modalities, context_length, max_output_tokens, effective_from, effective_to, created_at, updated_at from public.v2_model_provider_routes) m
      where position('/' in base_model) > 0
        and m.provider_id = split_part(base_model, '/', 1)
        and m.provider_model_slug = regexp_replace(base_model, '^[^/]+/', '')
        and m.is_active_gateway
        and (m.effective_from is null or m.effective_from <= now() at time zone 'utc')
        and (m.effective_to   is null or (now() at time zone 'utc') < m.effective_to)
      order by coalesce(m.effective_from, to_timestamp(0)) desc, m.provider_api_model_id
      limit 1
    ),
    base_model
  );

  -- validate key row, status, and team
  select
    (k.status = 'active'),
    (k.workspace_id = gateway_fetch_request_context.workspace_id),
    k.soft_blocked,
    k.daily_limit_requests,   k.weekly_limit_requests,   k.monthly_limit_requests,
    k.daily_limit_cost_nanos, k.weekly_limit_cost_nanos, k.monthly_limit_cost_nanos
  into
    v_key_active,
    v_key_team_ok,
    v_soft_blocked,
    v_day_req_limit, v_wk_req_limit, v_mo_req_limit,
    v_day_cost_limit, v_wk_cost_limit, v_mo_cost_limit
  from public.keys k
  where k.id = gateway_fetch_request_context.api_key_id
  limit 1;

  if v_key_active is null then
    raise exception using errcode = '22023', message = 'api_key_not_found', detail = 'key id does not exist';
  end if;
  if not v_key_team_ok then
    raise exception using errcode = '22023', message = 'api_key_wrong_team', detail = 'key does not belong to provided workspace_id';
  end if;
  if not v_key_active then
    raise exception using errcode = '22023', message = 'api_key_inactive', detail = 'key status is not active';
  end if;

  key_status := jsonb_build_object('ok', true, 'mode', 'first_party');

  -- credit check
  credit_status :=
    coalesce((
      select case
        when greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0) >= min_balance_nanos then
          jsonb_build_object(
            'ok', true,
            'balance_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
            'raw_balance_nanos', coalesce(w.balance_nanos, 0)::bigint,
            'reserved_nanos', coalesce(w.reserved_nanos, 0)::bigint,
            'available_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0)
          )
        else
          jsonb_build_object(
            'ok', false,
            'reason', 'insufficient_funds',
            'balance_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
            'raw_balance_nanos', coalesce(w.balance_nanos, 0)::bigint,
            'reserved_nanos', coalesce(w.reserved_nanos, 0)::bigint,
            'available_nanos', greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0)
          )
      end
      from public.wallets w
      where w.workspace_id = gateway_fetch_request_context.workspace_id
      limit 1
    ), jsonb_build_object('ok', false, 'reason', 'wallet_missing'));

  -- per-key limits (requests + cost)
  select
    count(*) filter (where gr.created_at >= day_start)                                  as used_day_reqs,
    count(*) filter (where gr.created_at >= week_start)                                 as used_wk_reqs,
    count(*) filter (where gr.created_at >= month_start)                                as used_mo_reqs,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= day_start), 0)::bigint   as used_day_cost,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= week_start), 0)::bigint  as used_wk_cost,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= month_start), 0)::bigint as used_mo_cost
  into
    used_day_reqs, used_wk_reqs, used_mo_reqs,
    used_day_cost, used_wk_cost, used_mo_cost
  from public.gateway_requests gr
  where gr.key_id  = gateway_fetch_request_context.api_key_id
    and gr.workspace_id = gateway_fetch_request_context.workspace_id
    and gr.success is true;

  if v_soft_blocked then
    within_limits := false;
    limit_reason := 'key_limit_soft_blocked';
    limit_metric := 'soft_blocked';
  end if;
  if within_limits and v_day_req_limit > 0 and used_day_reqs >= v_day_req_limit then
    within_limits := false;
    limit_reason := 'daily_request_limit_reached';
    limit_window := 'daily';
    limit_metric := 'requests';
    current_value := used_day_reqs;
    limit_value := v_day_req_limit;
    limit_reset_at := day_start + interval '1 day';
  end if;
  if within_limits and v_wk_req_limit > 0 and used_wk_reqs >= v_wk_req_limit then
    within_limits := false;
    limit_reason := 'weekly_request_limit_reached';
    limit_window := 'weekly';
    limit_metric := 'requests';
    current_value := used_wk_reqs;
    limit_value := v_wk_req_limit;
    limit_reset_at := week_start + interval '1 week';
  end if;
  if within_limits and v_mo_req_limit > 0 and used_mo_reqs >= v_mo_req_limit then
    within_limits := false;
    limit_reason := 'monthly_request_limit_reached';
    limit_window := 'monthly';
    limit_metric := 'requests';
    current_value := used_mo_reqs;
    limit_value := v_mo_req_limit;
    limit_reset_at := month_start + interval '1 month';
  end if;
  if within_limits and v_day_cost_limit > 0 and used_day_cost >= v_day_cost_limit then
    within_limits := false;
    limit_reason := 'daily_cost_limit_reached';
    limit_window := 'daily';
    limit_metric := 'cost';
    current_value := used_day_cost;
    limit_value := v_day_cost_limit;
    limit_reset_at := day_start + interval '1 day';
  end if;
  if within_limits and v_wk_cost_limit > 0 and used_wk_cost >= v_wk_cost_limit then
    within_limits := false;
    limit_reason := 'weekly_cost_limit_reached';
    limit_window := 'weekly';
    limit_metric := 'cost';
    current_value := used_wk_cost;
    limit_value := v_wk_cost_limit;
    limit_reset_at := week_start + interval '1 week';
  end if;
  if within_limits and v_mo_cost_limit > 0 and used_mo_cost >= v_mo_cost_limit then
    within_limits := false;
    limit_reason := 'monthly_cost_limit_reached';
    limit_window := 'monthly';
    limit_metric := 'cost';
    current_value := used_mo_cost;
    limit_value := v_mo_cost_limit;
    limit_reset_at := month_start + interval '1 month';
  end if;

  key_limit_status :=
    jsonb_build_object(
      'ok', within_limits,
      'reason', limit_reason,
      'limit_window', limit_window,
      'limit_metric', limit_metric,
      'current_value', current_value,
      'limit_value', limit_value,
      'reset_at', to_jsonb(limit_reset_at),
      'now', to_jsonb(now_utc),
      'buckets', jsonb_build_object(
        'daily', jsonb_build_object(
          'window_start', to_jsonb(day_start),
          'requests_used', used_day_reqs,
          'requests_limit', v_day_req_limit,
          'cost_used_nanos', used_day_cost,
          'cost_limit_nanos', v_day_cost_limit
        ),
        'weekly', jsonb_build_object(
          'window_start', to_jsonb(week_start),
          'requests_used', used_wk_reqs,
          'requests_limit', v_wk_req_limit,
          'cost_used_nanos', used_wk_cost,
          'cost_limit_nanos', v_wk_cost_limit
        ),
        'monthly', jsonb_build_object(
          'window_start', to_jsonb(month_start),
          'requests_used', used_mo_reqs,
          'requests_limit', v_mo_req_limit,
          'cost_used_nanos', used_mo_cost,
          'cost_limit_nanos', v_mo_cost_limit
        )
      )
    );

  -- ============================================================================
  -- TEAM & KEY ENRICHMENT (Wide Event Context for Observability)
  -- Purpose: Gather user/team context for comprehensive logging (loggingsucks.com pattern)
  -- ============================================================================
  -- Team metadata & wallet
  select
    t.created_at,
    coalesce(t.tier, 'basic'),
    greatest(coalesce(w.balance_nanos, 0)::bigint - coalesce(w.reserved_nanos, 0)::bigint, 0),
    coalesce(w.reserved_nanos, 0)::bigint
  into
    team_created_at,
    team_tier,
    team_balance_nanos,
    team_reserved_nanos
  from public.workspaces t
  left join public.wallets w on w.workspace_id = t.id
  where t.id = gateway_fetch_request_context.workspace_id
  limit 1;

  -- Team spend & request aggregates
  select
    count(*),
    coalesce(sum(gr.cost_nanos), 0)::bigint,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= now_utc - interval '24 hours'), 0)::bigint,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= now_utc - interval '7 days'), 0)::bigint,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= now_utc - interval '30 days'), 0)::bigint,
    count(*) filter (where gr.created_at >= now_utc - interval '1 hour'),
    count(*) filter (where gr.created_at >= now_utc - interval '24 hours')
  into
    team_total_requests,
    team_total_spend_nanos,
    team_spend_24h_nanos,
    team_spend_7d_nanos,
    team_spend_30d_nanos,
    team_requests_1h,
    team_requests_24h
  from public.gateway_requests gr
  where gr.workspace_id = gateway_fetch_request_context.workspace_id
    and gr.success is true;

  -- Calculate tier using calendar-month qualification + lock-window grace.
  -- Function maintains team tier/counters in database when state changes.
  team_tier := calculate_tier_with_grace(gateway_fetch_request_context.workspace_id, team_spend_30d_nanos);

  team_enrichment := jsonb_build_object(
    'tier', team_tier,
    'created_at', to_jsonb(team_created_at),
    'account_age_days', extract(epoch from (now_utc - team_created_at)) / 86400,
    'balance_nanos', team_balance_nanos,
    'available_nanos', team_balance_nanos,
    'reserved_nanos', team_reserved_nanos,
    'balance_usd', round((team_balance_nanos::numeric / 1000000000.0)::numeric, 2),
    'balance_is_low', team_balance_nanos < min_balance_nanos,
    'total_requests', team_total_requests,
    'total_spend_nanos', team_total_spend_nanos,
    'total_spend_usd', round((team_total_spend_nanos::numeric / 1000000000.0)::numeric, 2),
    'spend_24h_nanos', team_spend_24h_nanos,
    'spend_24h_usd', round((team_spend_24h_nanos::numeric / 1000000000.0)::numeric, 4),
    'spend_7d_nanos', team_spend_7d_nanos,
    'spend_7d_usd', round((team_spend_7d_nanos::numeric / 1000000000.0)::numeric, 2),
    'spend_30d_nanos', team_spend_30d_nanos,
    'spend_30d_usd', round((team_spend_30d_nanos::numeric / 1000000000.0)::numeric, 2),
    'requests_1h', team_requests_1h,
    'requests_24h', team_requests_24h
  );

  -- Key metadata & aggregates
  select
    k.name,
    k.created_at
  into
    key_name,
    key_created_at
  from public.keys k
  where k.id = gateway_fetch_request_context.api_key_id
  limit 1;

  select
    count(*),
    coalesce(sum(gr.cost_nanos), 0)::bigint
  into
    key_total_requests,
    key_total_spend_nanos
  from public.gateway_requests gr
  where gr.key_id = gateway_fetch_request_context.api_key_id
    and gr.success is true;

  key_enrichment := jsonb_build_object(
    'name', key_name,
    'created_at', to_jsonb(key_created_at),
    'key_age_days', extract(epoch from (now_utc - key_created_at)) / 86400,
    'total_requests', key_total_requests,
    'total_spend_nanos', key_total_spend_nanos,
    'total_spend_usd', round((key_total_spend_nanos::numeric / 1000000000.0)::numeric, 2),
    'requests_today', used_day_reqs,
    'spend_today_nanos', used_day_cost,
    'spend_today_usd', round((used_day_cost::numeric / 1000000000.0)::numeric, 4),
    'daily_limit_pct', case
      when v_day_req_limit > 0 then round((used_day_reqs::numeric / v_day_req_limit::numeric * 100)::numeric, 1)
      else null
    end
  );

  -- provider candidates (BYOK) + pricing, fully qualifying params
  with provider_rows as (
    select distinct on (m.provider_api_model_id)
      m.provider_api_model_id,
      m.provider_id,
      m.api_model_id,
      m.provider_model_slug, coalesce((select route.metadata -> 'availability' from public.v2_model_provider_routes route where route.provider_model_id = m.provider_api_model_id), p.metadata -> 'availability') as availability,
      m.routing_status as model_status,
      m.input_modalities,
      m.output_modalities,
      p.prompt_training_policy,
      p.data_policy_tier,
      p.data_policy_confidence,
      p.data_policy_contract_mode,
	  p.data_policy_variant,
      c.status as capability_status,
      c.params as capability_params,
      c.max_input_tokens,
      c.max_output_tokens
    from (select provider_model_id as provider_api_model_id, provider_slug as provider_id, model_slug as api_model_id, model_slug as model_id, provider_model_slug, routing_enabled as is_active_gateway, status as routing_status, input_modalities, output_modalities, context_length, max_output_tokens, effective_from, effective_to, created_at, updated_at from public.v2_model_provider_routes) m
    join (select model_slug as model_id, lab_slug as organisation_id, name, description, status, hidden, announced_at as announcement_date, released_at as release_date, deprecated_at as deprecation_date, retired_at as retirement_date, previous_model_slug as previous_model_id, input_modalities as input_types, output_modalities as output_types, metadata, created_at, updated_at from public.v2_models) dm
      on dm.model_id = coalesce(m.model_id, m.api_model_id)
    join public.v2_providers p
      on p.provider_slug = m.provider_id
    join (select provider_model_id as provider_api_model_id, capability_id, status, params, max_input_tokens, max_output_tokens, effective_from, effective_to, created_at, updated_at from public.v2_route_capabilities) c
      on c.provider_api_model_id = m.provider_api_model_id
    where m.api_model_id = resolved_model
      and coalesce(dm.hidden, false) = false
      and (dm.status is null or lower(dm.status) in ('active', 'available', 'deprecated'))
      and (dm.retirement_date is null or dm.retirement_date > now() at time zone 'utc')
      and c.capability_id = gateway_fetch_request_context.endpoint
      and c.status in ('active', 'deranked', 'deranked_lvl1', 'deranked_lvl2', 'deranked_lvl3')
      and m.is_active_gateway
      and (m.effective_from is null or m.effective_from <= now() at time zone 'utc')
      and (m.effective_to   is null or (now() at time zone 'utc') < m.effective_to)
    order by m.provider_api_model_id, coalesce(c.updated_at, c.created_at) desc
  )
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'provider_id', pr.provider_id,
          'api_model_id', pr.api_model_id,
          'pricing_key', pr.provider_id,
          'provider_model_slug', pr.provider_model_slug, 'availability', pr.availability,
          'model_status', pr.model_status,
          'input_modalities', pr.input_modalities,
          'output_modalities', pr.output_modalities,
          'prompt_training_policy', coalesce(pr.prompt_training_policy, 'unknown'),
          'data_policy_tier', coalesce(pr.data_policy_tier, 'unknown'),
          'data_policy_confidence', coalesce(pr.data_policy_confidence, 'unknown'),
          'data_policy_contract_mode', coalesce(pr.data_policy_contract_mode, 'none'),
		  'data_policy_variant', coalesce(pr.data_policy_variant, 'standard'),
          'capability_status', pr.capability_status,
          'capability_params', coalesce(pr.capability_params, '{}'::jsonb),
          'max_input_tokens', pr.max_input_tokens,
          'max_output_tokens', pr.max_output_tokens,
          'supports_endpoint', true,
          'base_weight', 1,
          'byok_meta', coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'provider_id', bk.provider_id,
                'id', bk.id,
                'name', bk.name,
                'fingerprint_sha256', bk.fingerprint_sha256,
                'key_version', bk.key_version,
                'always_use', bk.always_use
              )
            )
            from public.byok_keys bk
            where bk.workspace_id    = gateway_fetch_request_context.workspace_id
              and bk.provider_id = pr.provider_id
              and bk.enabled     = true
          ), '[]'::jsonb)
        )
      ), '[]'::jsonb
    ) as provider_payload,
    coalesce(
      jsonb_object_agg(
        pr.provider_id,
        (
          with rules as (
            select r.*
            from (select meter.sku_meter_id::text as rule_id, route.provider_slug as provider_id, route.model_slug as api_model_id, route.provider_slug || ':' || route.model_slug || ':' || sku.operation as model_key, sku.operation as capability_id, coalesce(sku.service_tier_slug, 'standard') as pricing_plan, meter.meter_key as meter, meter.unit, meter.unit_quantity as unit_size, meter.price_nanos / 1000000000.0 as price_per_unit, coalesce(nullif(meter.metadata->>'included_quantity', '')::numeric, nullif(sku.metadata->>'included_quantity', '')::numeric, 0) as included_quantity, sku.currency, coalesce(nullif(meter.metadata->>'priority', '')::integer, meter.meter_order, 100) as priority, sku.effective_from, sku.effective_to, coalesce(sku.metadata->'match', meter.metadata->'match', '[]'::jsonb) as match, coalesce(sku.metadata->>'billing_timestamp_basis', 'request_start') as billing_timestamp_basis, coalesce(sku.metadata->'time_windows', '[]'::jsonb) as time_windows, greatest(sku.updated_at, meter.updated_at) as updated_at from public.v2_pricing_skus sku join public.v2_model_provider_routes route on route.provider_model_id = sku.provider_model_id join public.v2_pricing_sku_meters meter on meter.sku_id = sku.sku_id where sku.status = 'active' and meter.billable) r
            -- TODO: Redesign pricing selection to key on provider_api_model_id or
            -- explicit variant metadata so provider-only SKUs (for example CrofAI
            -- precision tiers) can share a parent internal model without forcing
            -- distinct api_model_id values just to preserve pricing separation.
            where r.model_key =
              pr.provider_id || ':' || resolved_model || ':' || gateway_fetch_request_context.endpoint
              and r.capability_id = gateway_fetch_request_context.endpoint
              and (r.effective_from is null or r.effective_from <= now() at time zone 'utc')
              and (r.effective_to   is null or (now() at time zone 'utc') < r.effective_to)
          ),
          ordered_rules as (
            select
              jsonb_agg(
                jsonb_build_object(
                  'id', r.rule_id,
                  'pricing_plan', r.pricing_plan,
                  'meter', r.meter,
                  'unit', r.unit,
                  'unit_size', r.unit_size,
                  'price_per_unit', r.price_per_unit,
                  'included_quantity', r.included_quantity,
                  'currency', r.currency,
                  'match', r.match,
                  'priority', r.priority,
                  'billing_timestamp_basis', coalesce(r.billing_timestamp_basis, 'request_start'),
                  'time_windows', coalesce(r.time_windows, '[]'::jsonb)
                )
                order by r.priority desc, coalesce(r.effective_from, now() at time zone 'utc') desc
              ) as items,
              max(r.updated_at) as version_ts,
              min(r.effective_from) as effective_from,
              min(r.effective_to) as effective_to
            from rules r
          )
          select jsonb_build_object(
            'provider', pr.provider_id,
            'model', resolved_model,
            'endpoint', gateway_fetch_request_context.endpoint,
            'effective_from', to_jsonb(o.effective_from),
            'effective_to',   to_jsonb(o.effective_to),
            'currency', 'USD',
            'version', to_jsonb(o.version_ts),
            'rules', coalesce(o.items, '[]'::jsonb)
          )
          from ordered_rules o
        )
      ),
      '{}'::jsonb
    ) as pricing_payload
  into providers, pricing
  from provider_rows pr;

  return jsonb_build_object(
    'workspace_id', gateway_fetch_request_context.workspace_id,
    'resolved_model', resolved_model,
    'preset', preset_data,
    'key_ok', key_status,
    'key_limit_ok', key_limit_status,
    'credit_ok', credit_status,
    'providers', providers,
    'pricing', pricing,
    'team_enrichment', team_enrichment,
    'key_enrichment', key_enrichment
  );
end;

$$;


--
-- Name: FUNCTION gateway_fetch_request_context(workspace_id uuid, model text, endpoint text, api_key_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gateway_fetch_request_context(workspace_id uuid, model text, endpoint text, api_key_id uuid) IS 'V2 gateway request context with current and historical workspace publisher handle resolution.';


--
-- Name: gateway_fetch_request_context_with_reservations(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_fetch_request_context_with_reservations(workspace_id uuid, model text, endpoint text, api_key_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  payload jsonb;
  min_balance_nanos bigint := 1000000000; -- 1.00 USD
  wallet_balance_nanos bigint := 0;
  wallet_reserved_nanos bigint := 0;
  wallet_available_nanos bigint := 0;
  credit_status jsonb;
  enriched_pricing jsonb;
begin
  payload := public.gateway_fetch_request_context(workspace_id, model, endpoint, api_key_id);
  if payload is null then
    return null;
  end if;

  with provider_cards as (
    select provider_key, card
    from jsonb_each(coalesce(payload->'pricing', '{}'::jsonb)) as p(provider_key, card)
  ),
  enriched_cards as (
    select
      provider_key,
      jsonb_set(
        card,
        '{rules}',
        coalesce(rules.enriched_rules, '[]'::jsonb),
        true
      ) as card
    from provider_cards
    cross join lateral (
      select jsonb_agg(
        rule_item.value ||
        jsonb_build_object(
          'billing_timestamp_basis', coalesce(rule_row.billing_timestamp_basis, 'request_start'),
          'time_windows', coalesce(rule_row.time_windows, '[]'::jsonb)
        )
        order by rule_item.ordinality
      ) as enriched_rules
      from jsonb_array_elements(coalesce(card->'rules', '[]'::jsonb)) with ordinality as rule_item(value, ordinality)
      left join private.v2_rpc_pricing_compat rule_row
        on rule_row.rule_id::text = rule_item.value->>'id'
    ) rules
  )
  select coalesce(jsonb_object_agg(provider_key, card), '{}'::jsonb)
  into enriched_pricing
  from enriched_cards;

  payload := jsonb_set(payload, '{pricing}', coalesce(enriched_pricing, '{}'::jsonb), true);

  select
    coalesce(w.balance_nanos, 0)::bigint,
    coalesce(w.reserved_nanos, 0)::bigint
  into
    wallet_balance_nanos,
    wallet_reserved_nanos
  from public.wallets w
  where w.workspace_id = gateway_fetch_request_context_with_reservations.workspace_id
  limit 1;

  if not found then
    credit_status := jsonb_build_object('ok', false, 'reason', 'wallet_missing');
    return jsonb_set(payload, '{credit_ok}', credit_status, true);
  end if;

  wallet_available_nanos := greatest(wallet_balance_nanos - wallet_reserved_nanos, 0);

  if wallet_available_nanos >= min_balance_nanos then
    credit_status := jsonb_build_object(
      'ok', true,
      'balance_nanos', wallet_available_nanos,
      'raw_balance_nanos', wallet_balance_nanos,
      'reserved_nanos', wallet_reserved_nanos,
      'available_nanos', wallet_available_nanos
    );
  else
    credit_status := jsonb_build_object(
      'ok', false,
      'reason', 'insufficient_funds',
      'balance_nanos', wallet_available_nanos,
      'raw_balance_nanos', wallet_balance_nanos,
      'reserved_nanos', wallet_reserved_nanos,
      'available_nanos', wallet_available_nanos
    );
  end if;

  payload := jsonb_set(payload, '{credit_ok}', credit_status, true);

  if jsonb_typeof(payload->'team_enrichment') = 'object' then
    payload := jsonb_set(payload, '{team_enrichment,balance_nanos}', to_jsonb(wallet_available_nanos), true);
    payload := jsonb_set(payload, '{team_enrichment,available_nanos}', to_jsonb(wallet_available_nanos), true);
    payload := jsonb_set(payload, '{team_enrichment,reserved_nanos}', to_jsonb(wallet_reserved_nanos), true);
    payload := jsonb_set(
      payload,
      '{team_enrichment,balance_usd}',
      to_jsonb(round((wallet_available_nanos::numeric / 1000000000.0)::numeric, 2)),
      true
    );
    payload := jsonb_set(payload, '{team_enrichment,balance_is_low}', to_jsonb(wallet_available_nanos < min_balance_nanos), true);
  end if;

  return payload;
end;
$$;


--
-- Name: gateway_finish_batch_file_upload(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_finish_batch_file_upload(p_workspace_id uuid, p_upload_id text, p_status text, p_provider_file_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_status is null or p_status not in ('completed', 'failed') then
    raise exception 'invalid_batch_file_upload_status';
  end if;
  update public.gateway_batch_file_uploads
  set status = p_status,
      provider_file_id = nullif(trim(coalesce(p_provider_file_id, '')), ''),
      updated_at = now()
  where workspace_id = p_workspace_id and upload_id = p_upload_id;
end;
$$;


--
-- Name: gateway_marketing_uptime_tokens(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_marketing_uptime_tokens(hours_window integer DEFAULT 24) RETURNS TABLE(window_start timestamp with time zone, window_end timestamp with time zone, timeframe_hours integer, total_requests bigint, uptime_pct double precision, uptime_events bigint, total_tokens double precision)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
	with params as (
		select greatest(1, hours_window) as hours_window
	),
	bounds as (
		select
			now() at time zone 'utc' as window_end,
			(now() at time zone 'utc') - (p.hours_window || ' hours')::interval as window_start,
			p.hours_window
		from params p
	),
	scoped_requests as (
		select
			gr.success,
			gr.error_code,
			gr.usage,
			gr.created_at
		from gateway_requests gr
		cross join bounds b
		where gr.created_at >= b.window_start
			and gr.created_at < b.window_end
	)
	select
		b.window_start,
		b.window_end,
		b.hours_window as timeframe_hours,
		count(sr.*) as total_requests,
		case
			when count(sr.*) = 0 then null
			else round(
				(
					100.0 * count(*) filter (
						where coalesce(sr.success, false) or (sr.error_code ilike 'user:%')
					)::double precision
					/ greatest(count(sr.*), 1)::double precision
				)::numeric,
				4
			)::double precision
		end as uptime_pct,
		count(*) filter (
			where coalesce(sr.success, false) or (sr.error_code ilike 'user:%')
		) as uptime_events,
		coalesce(
			sum(
				case
					when jsonb_typeof(sr.usage -> 'total_tokens') = 'number' then
						(sr.usage ->> 'total_tokens')::double precision
					else 0::double precision
				end
			),
			0::double precision
		) as total_tokens
	from bounds b
	left join scoped_requests sr on true
	group by b.window_start, b.window_end, b.hours_window;
$$;


--
-- Name: gateway_realtime_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.gateway_realtime_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    session_id text NOT NULL,
    workspace_id uuid NOT NULL,
    key_id uuid,
    user_id text,
    source text DEFAULT 'api'::text NOT NULL,
    provider text NOT NULL,
    model_id text NOT NULL,
    provider_model_id text,
    voice text,
    status text DEFAULT 'created'::text NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    connected_at timestamp with time zone,
    ended_at timestamp with time zone,
    expires_at timestamp with time zone,
    last_event_at timestamp with time zone,
    reservation_prefix text NOT NULL,
    reservation_count integer DEFAULT 0 NOT NULL,
    reserved_nanos bigint DEFAULT 0 NOT NULL,
    captured_nanos bigint DEFAULT 0 NOT NULL,
    released_nanos bigint DEFAULT 0 NOT NULL,
    estimated_cost_nanos bigint DEFAULT 0 NOT NULL,
    final_cost_nanos bigint,
    currency text DEFAULT 'USD'::text NOT NULL,
    usage jsonb DEFAULT '{}'::jsonb NOT NULL,
    pricing_lines jsonb DEFAULT '[]'::jsonb NOT NULL,
    provider_session_id text,
    provider_native_id text,
    provider_client_secret_hash text,
    disconnect_reason text,
    error_code text,
    error_message text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT gateway_realtime_sessions_source_check CHECK ((source = ANY (ARRAY['api'::text, 'chat'::text]))),
    CONSTRAINT gateway_realtime_sessions_status_check CHECK ((status = ANY (ARRAY['created'::text, 'connecting'::text, 'connected'::text, 'ending'::text, 'billing_unresolved'::text, 'completed'::text, 'failed'::text, 'cancelled'::text, 'expired'::text])))
);


--
-- Name: gateway_realtime_claim_connection(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_realtime_claim_connection(p_session_id text, p_client_secret_hash text) RETURNS SETOF public.gateway_realtime_sessions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session public.gateway_realtime_sessions%rowtype;
begin
  select * into v_session
  from public.gateway_realtime_sessions
  where session_id = p_session_id
  for update;

  if not found then raise exception 'realtime_session_not_found'; end if;
  if coalesce(v_session.provider_client_secret_hash, '') <> coalesce(p_client_secret_hash, '') then
    raise exception 'realtime_relay_forbidden';
  end if;
  if v_session.status <> 'created' then
    raise exception 'realtime_relay_already_connected';
  end if;
  if v_session.expires_at is not null and v_session.expires_at <= now() then
    raise exception 'realtime_session_expired';
  end if;

  update public.gateway_realtime_sessions
  set status = 'connecting', last_event_at = now(), updated_at = now()
  where id = v_session.id and status = 'created'
  returning * into v_session;

  if not found then raise exception 'realtime_relay_already_connected'; end if;
  return next v_session;
end;
$$;


--
-- Name: gateway_realtime_create_with_hold(uuid, text, uuid, text, text, text, text, text, text, timestamp with time zone, text, text, bigint, text, jsonb, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_realtime_create_with_hold(p_workspace_id uuid, p_session_id text, p_key_id uuid, p_user_id text, p_source text, p_provider text, p_model_id text, p_provider_model_id text, p_voice text, p_expires_at timestamp with time zone, p_reservation_prefix text, p_reservation_id text, p_hold_nanos bigint, p_client_secret_hash text, p_metadata jsonb DEFAULT '{}'::jsonb, p_max_workspace_sessions integer DEFAULT 8, p_max_key_sessions integer DEFAULT 4, p_max_user_sessions integer DEFAULT 1, p_max_creations_per_minute integer DEFAULT 8) RETURNS SETOF public.gateway_realtime_sessions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_wallet public.wallets%rowtype;
  v_session public.gateway_realtime_sessions%rowtype;
  v_count integer;
begin
  if p_workspace_id is null or coalesce(trim(p_session_id), '') = '' then
    raise exception 'invalid_realtime_session_identity';
  end if;
  if p_key_id is null then
    raise exception 'invalid_realtime_key';
  end if;
  if p_hold_nanos is null or p_hold_nanos <= 0 then
    raise exception 'invalid_realtime_hold';
  end if;
  if p_source not in ('api', 'chat') then
    raise exception 'invalid_realtime_source';
  end if;
  if p_expires_at is null or p_expires_at <= now() then
    raise exception 'invalid_realtime_expiry';
  end if;

  -- The wallet row serializes create/limit checks for the workspace.
  select * into v_wallet
  from public.wallets
  where workspace_id = p_workspace_id
  for update;

  if not found then
    raise exception 'wallet_not_found';
  end if;

  select count(*)::integer into v_count
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id
    and status in ('created', 'connecting', 'connected', 'ending', 'billing_unresolved');
  if v_count >= greatest(1, p_max_workspace_sessions) then
    raise exception 'realtime_workspace_concurrency_limit';
  end if;

  select count(*)::integer into v_count
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id
    and key_id = p_key_id
    and status in ('created', 'connecting', 'connected', 'ending', 'billing_unresolved');
  if v_count >= greatest(1, p_max_key_sessions) then
    raise exception 'realtime_key_concurrency_limit';
  end if;

  if nullif(trim(coalesce(p_user_id, '')), '') is not null then
    select count(*)::integer into v_count
    from public.gateway_realtime_sessions
    where workspace_id = p_workspace_id
      and user_id = p_user_id
      and status in ('created', 'connecting', 'connected', 'ending', 'billing_unresolved');
    if v_count >= greatest(1, p_max_user_sessions) then
      raise exception 'realtime_user_concurrency_limit';
    end if;
  end if;

  select count(*)::integer into v_count
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id
    and created_at >= now() - interval '1 minute';
  if v_count >= greatest(1, p_max_creations_per_minute) then
    raise exception 'realtime_creation_rate_limit';
  end if;

  if coalesce(v_wallet.balance_nanos, 0) - coalesce(v_wallet.reserved_nanos, 0) < p_hold_nanos then
    raise exception 'insufficient_funds';
  end if;

  insert into public.gateway_realtime_sessions (
    session_id, workspace_id, key_id, user_id, source, provider, model_id,
    provider_model_id, voice, status, expires_at, reservation_prefix,
    reservation_count, reserved_nanos, provider_client_secret_hash, metadata
  ) values (
    p_session_id, p_workspace_id, p_key_id, nullif(trim(coalesce(p_user_id, '')), ''),
    p_source, p_provider, p_model_id, p_provider_model_id, p_voice, 'created',
    p_expires_at, p_reservation_prefix, 1, p_hold_nanos,
    p_client_secret_hash, coalesce(p_metadata, '{}'::jsonb)
  ) returning * into v_session;

  insert into public.gateway_wallet_reservations (
    reservation_id, workspace_id, amount_nanos, status, hold_ref_id,
    captured_nanos, released_nanos, created_at, updated_at
  ) values (
    p_reservation_id, p_workspace_id, p_hold_nanos, 'reserved', p_session_id,
    0, 0, now(), now()
  );

  insert into public.gateway_requests (
    workspace_id, request_id, realtime_session_id, endpoint, model_id, provider,
    stream, byok, status_code, success, usage, cost_nanos, currency,
    pricing_lines, key_id, created_at
  ) values (
    p_workspace_id, 'realtime:' || p_session_id, p_session_id, 'audio.realtime',
    p_model_id, p_provider, true, false, 102, false, '{}'::jsonb, 0, 'USD',
    '[]'::jsonb, p_key_id, v_session.started_at
  );

  update public.wallets
  set reserved_nanos = coalesce(reserved_nanos, 0) + p_hold_nanos,
      updated_at = now()
  where workspace_id = p_workspace_id;

  return next v_session;
end;
$$;


--
-- Name: gateway_realtime_enforce_provider_concurrency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_realtime_enforce_provider_concurrency() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_provider text := lower(trim(coalesce(new.provider, '')));
  v_active_count integer;
begin
  if v_provider = '' then
    raise exception 'realtime_provider_required';
  end if;

  -- Serialize creates for one shared provider account across all workspaces.
  perform pg_advisory_xact_lock(
    hashtextextended('gateway_realtime_provider:' || v_provider, 0)
  );

  select count(*)::integer into v_active_count
  from public.gateway_realtime_sessions
  where lower(provider) = v_provider
    and status in ('created', 'connecting', 'connected', 'ending');

  if v_active_count >= 20 then
    raise exception 'realtime_provider_concurrency_limit';
  end if;

  return new;
end;
$$;


--
-- Name: gateway_realtime_extend_hold_once(uuid, text, text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_realtime_extend_hold_once(p_workspace_id uuid, p_session_id text, p_reservation_id text, p_target_reserved_nanos bigint, p_estimated_cost_nanos bigint DEFAULT 0) RETURNS SETOF public.gateway_realtime_sessions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_wallet public.wallets%rowtype;
  v_session public.gateway_realtime_sessions%rowtype;
  v_additional bigint;
begin
  select * into v_wallet
  from public.wallets
  where workspace_id = p_workspace_id
  for update;
  if not found then raise exception 'wallet_not_found'; end if;

  select * into v_session
  from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id and session_id = p_session_id
  for update;
  if not found then raise exception 'realtime_session_not_found'; end if;
  if v_session.status not in ('created', 'connected', 'ending') then
    raise exception 'realtime_session_terminal';
  end if;

  v_additional := greatest(0, coalesce(p_target_reserved_nanos, 0) - coalesce(v_session.reserved_nanos, 0));
  if v_additional > 0 then
    if coalesce(v_wallet.balance_nanos, 0) - coalesce(v_wallet.reserved_nanos, 0) < v_additional then
      update public.gateway_realtime_sessions
      set status = 'ending', disconnect_reason = 'credit_hold_extension_failed',
          error_code = 'insufficient_funds', updated_at = now()
      where id = v_session.id;
      raise exception 'insufficient_funds';
    end if;

    insert into public.gateway_wallet_reservations (
      reservation_id, workspace_id, amount_nanos, status, hold_ref_id,
      captured_nanos, released_nanos, created_at, updated_at
    ) values (
      p_reservation_id, p_workspace_id, v_additional, 'reserved', p_session_id,
      0, 0, now(), now()
    );
    update public.wallets
    set reserved_nanos = coalesce(reserved_nanos, 0) + v_additional,
        updated_at = now()
    where workspace_id = p_workspace_id;
  end if;

  update public.gateway_realtime_sessions
  set reservation_count = reservation_count + case when v_additional > 0 then 1 else 0 end,
      reserved_nanos = reserved_nanos + v_additional,
      estimated_cost_nanos = greatest(estimated_cost_nanos, coalesce(p_estimated_cost_nanos, 0)),
      last_event_at = now(), updated_at = now()
  where id = v_session.id
  returning * into v_session;

  return next v_session;
end;
$$;


--
-- Name: gateway_realtime_mark_billing_unresolved(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_realtime_mark_billing_unresolved(p_workspace_id uuid, p_session_id text, p_usage jsonb, p_reason text) RETURNS SETOF public.gateway_realtime_sessions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_session public.gateway_realtime_sessions%rowtype;
begin
  update public.gateway_realtime_sessions
  set status = 'billing_unresolved',
      usage = coalesce(p_usage, '{}'::jsonb),
      disconnect_reason = left(coalesce(nullif(trim(p_reason), ''), 'authoritative_usage_missing'), 240),
      error_code = 'realtime_authoritative_usage_missing',
      last_event_at = now(),
      updated_at = now()
  where workspace_id = p_workspace_id
    and session_id = p_session_id
    and status in ('created', 'connecting', 'connected', 'ending', 'billing_unresolved')
  returning * into v_session;

  if not found then
    select * into v_session
    from public.gateway_realtime_sessions
    where workspace_id = p_workspace_id and session_id = p_session_id;
  end if;
  if not found then raise exception 'realtime_session_not_found'; end if;
  if v_session.status in ('completed', 'failed', 'cancelled', 'expired') then
    return next v_session;
    return;
  end if;

  update public.gateway_requests
  set status_code = 202,
      success = false,
      error_code = 'realtime_authoritative_usage_missing',
      error_message = 'Realtime billing requires reconciliation.',
      usage = coalesce(p_usage, '{}'::jsonb)
  where realtime_session_id = p_session_id
    and created_at = v_session.started_at;

  return next v_session;
end;
$$;


--
-- Name: gateway_realtime_settle_once(uuid, text, bigint, jsonb, jsonb, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_realtime_settle_once(p_workspace_id uuid, p_session_id text, p_final_cost_nanos bigint, p_usage jsonb DEFAULT '{}'::jsonb, p_pricing_lines jsonb DEFAULT '[]'::jsonb, p_status text DEFAULT 'completed'::text, p_disconnect_reason text DEFAULT NULL::text, p_error_code text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text) RETURNS TABLE(applied boolean, already_applied boolean, status text, final_cost_nanos bigint, reserved_nanos bigint, captured_nanos bigint, released_nanos bigint, before_balance_nanos bigint, after_balance_nanos bigint, before_reserved_nanos bigint, after_reserved_nanos bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_session public.gateway_realtime_sessions%rowtype;
  v_wallet public.wallets%rowtype;
  v_reservation public.gateway_wallet_reservations%rowtype;
  v_cost bigint := greatest(0, coalesce(p_final_cost_nanos, 0));
  v_held bigint := 0;
  v_capture_remaining bigint;
  v_row_capture bigint;
  v_before_balance bigint;
  v_before_reserved bigint;
  v_request_count integer;
  v_next_status text := lower(coalesce(nullif(trim(p_status), ''), 'completed'));
begin
  if v_next_status not in ('completed', 'failed', 'cancelled', 'expired') then
    raise exception 'invalid_realtime_terminal_status';
  end if;

  select * into v_session from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id and session_id = p_session_id;
  if not found then
    return query select false, false, 'not_found'::text, 0::bigint, 0::bigint,
      0::bigint, 0::bigint, null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;
  if v_session.status in ('completed', 'failed', 'cancelled', 'expired') then
    return query select false, true, v_session.status, coalesce(v_session.final_cost_nanos, 0),
      v_session.reserved_nanos, v_session.captured_nanos, v_session.released_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  perform 1 from public.gateway_wallet_reservations gwr
  where gwr.workspace_id = p_workspace_id and gwr.status in ('held', 'reserved')
    and (gwr.hold_ref_id = p_session_id or gwr.reservation_id like v_session.reservation_prefix || '%')
  order by gwr.created_at, gwr.reservation_id
  for update;

  select * into v_wallet from public.wallets
  where workspace_id = p_workspace_id for update;
  if not found then raise exception 'wallet_not_found'; end if;

  select * into v_session from public.gateway_realtime_sessions
  where workspace_id = p_workspace_id and session_id = p_session_id for update;
  if v_session.status in ('completed', 'failed', 'cancelled', 'expired') then
    return query select false, true, v_session.status, coalesce(v_session.final_cost_nanos, 0),
      v_session.reserved_nanos, v_session.captured_nanos, v_session.released_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  select coalesce(sum(gwr.amount_nanos), 0)::bigint into v_held
  from public.gateway_wallet_reservations gwr
  where gwr.workspace_id = p_workspace_id and gwr.status in ('held', 'reserved')
    and (gwr.hold_ref_id = p_session_id or gwr.reservation_id like v_session.reservation_prefix || '%');

  v_before_balance := coalesce(v_wallet.balance_nanos, 0);
  v_before_reserved := coalesce(v_wallet.reserved_nanos, 0);
  if v_before_reserved < v_held then
    return query select false, false, 'reserved_balance_mismatch'::text, v_cost, v_held,
      0::bigint, v_held, v_before_balance, v_before_balance, v_before_reserved, v_before_reserved;
    return;
  end if;
  if v_cost > v_held + greatest(0, v_before_balance - v_before_reserved) then
    return query select false, false, 'insufficient_unreserved_balance'::text, v_cost, v_held,
      0::bigint, v_held, v_before_balance, v_before_balance, v_before_reserved, v_before_reserved;
    return;
  end if;

  update public.wallets w
  set balance_nanos = w.balance_nanos - v_cost,
      reserved_nanos = w.reserved_nanos - v_held,
      updated_at = now()
  where workspace_id = p_workspace_id;

  v_capture_remaining := least(v_cost, v_held);
  for v_reservation in
    select gwr.* from public.gateway_wallet_reservations gwr
    where gwr.workspace_id = p_workspace_id and gwr.status in ('held', 'reserved')
      and (gwr.hold_ref_id = p_session_id or gwr.reservation_id like v_session.reservation_prefix || '%')
    order by gwr.created_at, gwr.reservation_id
    for update
  loop
    v_row_capture := least(v_reservation.amount_nanos, v_capture_remaining);
    update public.gateway_wallet_reservations
    set status = case when v_row_capture > 0 then 'captured' else 'released' end,
        captured_nanos = v_row_capture,
        released_nanos = v_reservation.amount_nanos - v_row_capture,
        capture_ref_id = case when v_row_capture > 0 then p_session_id else null end,
        release_ref_id = case when v_row_capture < v_reservation.amount_nanos then p_session_id else null end,
        captured_at = case when v_row_capture > 0 then now() else null end,
        released_at = case when v_row_capture < v_reservation.amount_nanos then now() else null end,
        updated_at = now()
    where workspace_id = p_workspace_id and reservation_id = v_reservation.reservation_id;
    v_capture_remaining := greatest(0, v_capture_remaining - v_row_capture);
  end loop;

  if v_cost > 0 then
    insert into public.credit_ledger (
      workspace_id, event_time, kind, amount_nanos, before_balance_nanos,
      after_balance_nanos, before_reserved_nanos, after_reserved_nanos,
      ref_type, ref_id, created_at, status
    ) values (
      p_workspace_id, now(), 'charge', -v_cost, v_before_balance,
      v_before_balance - v_cost, v_before_reserved, v_before_reserved - v_held,
      'realtime_session', p_session_id, now(), 'captured'
    ) on conflict (ref_type, ref_id) do nothing;
  end if;

  update public.gateway_realtime_sessions
  set status = v_next_status,
      ended_at = coalesce(ended_at, now()),
      final_cost_nanos = v_cost,
      captured_nanos = v_cost,
      released_nanos = greatest(0, v_held - least(v_cost, v_held)),
      reserved_nanos = v_held,
      usage = coalesce(p_usage, '{}'::jsonb),
      pricing_lines = case when jsonb_typeof(coalesce(p_pricing_lines, '[]'::jsonb)) = 'array'
        then p_pricing_lines else '[]'::jsonb end,
      disconnect_reason = nullif(trim(coalesce(p_disconnect_reason, '')), ''),
      error_code = nullif(trim(coalesce(p_error_code, '')), ''),
      error_message = nullif(trim(coalesce(p_error_message, '')), ''),
      updated_at = now()
  where id = v_session.id
  returning * into v_session;

  update public.gateway_requests
  set native_response_id = coalesce(v_session.provider_session_id, v_session.provider_native_id),
      status_code = case when v_next_status = 'completed' then 200 else 499 end,
      success = v_next_status = 'completed',
      error_code = nullif(trim(coalesce(p_error_code, '')), ''),
      error_message = nullif(trim(coalesce(p_error_message, '')), ''),
      generation_ms = greatest(0, floor(extract(epoch from (v_session.ended_at - v_session.started_at)) * 1000))::integer,
      usage = coalesce(p_usage, '{}'::jsonb),
      cost_nanos = v_cost,
      currency = 'USD',
      pricing_lines = case when jsonb_typeof(coalesce(p_pricing_lines, '[]'::jsonb)) = 'array'
        then p_pricing_lines else '[]'::jsonb end
  where realtime_session_id = p_session_id
    and created_at = v_session.started_at;
  get diagnostics v_request_count = row_count;
  if v_request_count <> 1 then
    raise exception 'realtime_request_summary_missing';
  end if;

  return query select true, false, v_session.status, v_cost, v_held, v_cost,
    greatest(0, v_held - least(v_cost, v_held)), v_before_balance,
    v_before_balance - v_cost, v_before_reserved, v_before_reserved - v_held;
end;
$$;


--
-- Name: gateway_record_batch_key_usage(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_record_batch_key_usage(p_workspace_id uuid, p_key_id uuid, p_batch_id text, p_provider text, p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_inserted integer := 0;
begin
  if p_workspace_id is null or p_key_id is null or coalesce(trim(p_batch_id), '') = '' then
    raise exception 'invalid_batch_key_usage_identity';
  end if;
  if not exists (
    select 1 from public.keys
    where id = p_key_id and workspace_id = p_workspace_id
  ) then
    raise exception 'batch_key_not_owned_by_workspace';
  end if;
  if jsonb_typeof(p_rows) <> 'array' then
    raise exception 'invalid_batch_key_usage_rows';
  end if;

  delete from public.gateway_requests gr
  where gr.workspace_id = p_workspace_id
    and gr.key_id = p_key_id
    and gr.request_id like 'batch_hold_usage:%'
    and exists (
      select 1
      from public.gateway_wallet_reservations reservation
      where reservation.workspace_id = p_workspace_id
        and reservation.key_id = p_key_id
        and reservation.capture_ref_id = p_batch_id
        and reservation.status = 'captured'
        and gr.request_id like 'batch_hold_usage:' || reservation.reservation_id || ':%'
    );

  with source_rows as (
    select
      coalesce(nullif(trim(row ->> 'custom_id'), ''), ordinality::text) as custom_id,
      coalesce(nullif(trim(row ->> 'endpoint'), ''), 'batch') as endpoint,
      coalesce(nullif(trim(row ->> 'model'), ''), 'batch/unknown') as model,
      greatest(0, coalesce((row ->> 'cost_nanos')::bigint, 0)) as cost_nanos,
      case when jsonb_typeof(row -> 'usage') = 'object' then row -> 'usage' else '{}'::jsonb end as usage
    from jsonb_array_elements(p_rows) with ordinality as entries(row, ordinality)
  ), claimed_rows as (
    insert into public.gateway_batch_key_usage_records (
      workspace_id, batch_id, custom_id, key_id, provider, endpoint, model, cost_nanos, usage
    )
    select
      p_workspace_id, p_batch_id, source.custom_id, p_key_id,
      nullif(trim(coalesce(p_provider, '')), ''), source.endpoint,
      source.model, source.cost_nanos, source.usage
    from source_rows source
    on conflict (workspace_id, batch_id, custom_id) do nothing
    returning custom_id, provider, endpoint, model, cost_nanos, usage
  )
  insert into public.gateway_requests (
    workspace_id, request_id, endpoint, model_id, provider,
    status_code, success, usage, cost_nanos, currency, key_id
  )
  select
    p_workspace_id,
    'batch_usage:' || p_batch_id || ':' || claimed.custom_id,
    claimed.endpoint,
    claimed.model,
    claimed.provider,
    200,
    true,
    claimed.usage,
    claimed.cost_nanos,
    'USD',
    p_key_id
  from claimed_rows claimed;
  get diagnostics v_inserted = row_count;

  update public.gateway_wallet_reservations
  set key_usage_recorded_at = coalesce(key_usage_recorded_at, now()), updated_at = now()
  where workspace_id = p_workspace_id
    and key_id = p_key_id
    and capture_ref_id = p_batch_id
    and status = 'captured';

  return v_inserted;
end;
$$;


--
-- Name: gateway_request_usage_rollup_rows(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_request_usage_rollup_rows(p_since timestamp with time zone, p_until timestamp with time zone DEFAULT now()) RETURNS TABLE(day_bucket date, model_id text, provider_id text, endpoint text, requests bigint, success_requests bigint, failed_requests bigint, neutral_requests bigint, rate_limited_requests bigint, total_tokens bigint, input_tokens bigint, output_tokens bigint, reasoning_tokens bigint, input_text_tokens bigint, output_text_tokens bigint, input_image_tokens bigint, output_image_tokens bigint, input_audio_tokens bigint, output_audio_tokens bigint, input_video_tokens bigint, output_video_tokens bigint, image_inputs bigint, image_outputs bigint, audio_inputs bigint, audio_outputs bigint, video_inputs bigint, video_outputs bigint, cached_read_tokens bigint, cached_write_tokens bigint, cached_read_text_tokens bigint, cached_write_text_tokens bigint, cached_write_text_tokens_5m bigint, cached_write_text_tokens_1h bigint, cached_read_image_tokens bigint, cached_write_image_tokens bigint, cached_read_audio_tokens bigint, cached_write_audio_tokens bigint, cached_read_video_tokens bigint, cached_write_video_tokens bigint, input_quad_tokens bigint, output_quad_tokens bigint, total_quad_tokens bigint, text_quad_tokens bigint, rerank_quad_tokens bigint, embedding_quad_tokens bigint, moderation_quad_tokens bigint, ocr_quad_tokens bigint, image_megapixels numeric, audio_seconds numeric, video_pixel_seconds numeric, input_characters bigint, output_characters bigint, total_characters bigint, total_cost_nanos bigint, latency_sum_ms bigint, latency_samples bigint, generation_sum_ms bigint, generation_samples bigint, throughput_sum numeric, throughput_samples bigint, last_request_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with base as (
    select
      date_trunc('day', gr.created_at at time zone 'utc')::date as day_bucket,
      coalesce(
        nullif(gr.canonical_model_id, ''),
        public.resolve_public_model_id(gr.model_id, gr.provider),
        nullif(gr.routed_model_id, ''),
        nullif(gr.requested_model_id, ''),
        nullif(gr.model_id, ''),
        'unknown'
      ) as model_id,
      coalesce(nullif(gr.provider, ''), 'unknown') as provider_id,
      coalesce(nullif(gr.endpoint, ''), 'unknown') as endpoint,
      gr.created_at,
      gr.success,
      gr.status_code,
      lower(coalesce(gr.error_code, '')) as error_code,
      gr.cost_nanos,
      gr.latency_ms,
      gr.generation_ms,
      gr.throughput,
      gr.usage_total_tokens,
      gr.usage_input_tokens,
      gr.usage_output_tokens,
      gr.usage_reasoning_tokens,
      gr.usage_input_text_tokens,
      gr.usage_output_text_tokens,
      gr.usage_input_image_tokens,
      gr.usage_output_image_tokens,
      gr.usage_input_audio_tokens,
      gr.usage_output_audio_tokens,
      gr.usage_input_video_tokens,
      gr.usage_output_video_tokens,
      gr.usage_image_inputs,
      gr.usage_image_outputs,
      gr.usage_audio_inputs,
      gr.usage_audio_outputs,
      gr.usage_video_inputs,
      gr.usage_video_outputs,
      gr.usage_cached_read_tokens,
      gr.usage_cached_write_tokens,
      gr.usage_cached_read_text_tokens,
      gr.usage_cached_write_text_tokens,
      gr.usage_cached_write_text_tokens_5m,
      gr.usage_cached_write_text_tokens_1h,
      gr.usage_cached_read_image_tokens,
      gr.usage_cached_write_image_tokens,
      gr.usage_cached_read_audio_tokens,
      gr.usage_cached_write_audio_tokens,
      gr.usage_cached_read_video_tokens,
      gr.usage_cached_write_video_tokens,
      gr.usage_input_quad_tokens,
      gr.usage_output_quad_tokens,
      gr.usage_total_quad_tokens,
      gr.usage_text_quad_tokens,
      gr.usage_rerank_quad_tokens,
      gr.usage_embedding_quad_tokens,
      gr.usage_moderation_quad_tokens,
      gr.usage_ocr_quad_tokens,
      gr.usage_image_megapixels,
      gr.usage_audio_seconds,
      gr.usage_video_pixel_seconds,
      gr.usage_input_characters,
      gr.usage_output_characters,
      gr.usage_total_characters
    from private.v2_rpc_gateway_requests_compat gr
    where gr.created_at >= p_since
      and gr.created_at < p_until
  ),
  classified as (
    select
      b.*,
      case
        when b.success is true then 'success'
        when b.status_code = 429
          or b.error_code like '%rate limit%'
          or b.error_code like '%rate_limit%'
          or b.error_code like '%ratelimit%'
          or b.error_code like '%too many requests%'
          or b.error_code like '%quota exceeded%'
          or b.error_code like '%abort%'
          or b.error_code like '%cancel%'
          or b.error_code like '%client_closed%'
        then 'neutral'
        else 'failure'
      end as health_outcome,
      case
        when b.status_code = 429
          or b.error_code like '%rate limit%'
          or b.error_code like '%rate_limit%'
          or b.error_code like '%ratelimit%'
          or b.error_code like '%too many requests%'
          or b.error_code like '%quota exceeded%'
        then true
        else false
      end as is_rate_limited
    from base b
  )
  select
    c.day_bucket,
    c.model_id,
    c.provider_id,
    c.endpoint,
    count(*)::bigint as requests,
    count(*) filter (where c.success is true)::bigint as success_requests,
    count(*) filter (where c.health_outcome = 'failure')::bigint as failed_requests,
    count(*) filter (where c.health_outcome = 'neutral')::bigint as neutral_requests,
    count(*) filter (where c.is_rate_limited)::bigint as rate_limited_requests,
    sum(c.usage_total_tokens)::bigint as total_tokens,
    sum(c.usage_input_tokens)::bigint as input_tokens,
    sum(c.usage_output_tokens)::bigint as output_tokens,
    sum(c.usage_reasoning_tokens)::bigint as reasoning_tokens,
    sum(c.usage_input_text_tokens)::bigint as input_text_tokens,
    sum(c.usage_output_text_tokens)::bigint as output_text_tokens,
    sum(c.usage_input_image_tokens)::bigint as input_image_tokens,
    sum(c.usage_output_image_tokens)::bigint as output_image_tokens,
    sum(c.usage_input_audio_tokens)::bigint as input_audio_tokens,
    sum(c.usage_output_audio_tokens)::bigint as output_audio_tokens,
    sum(c.usage_input_video_tokens)::bigint as input_video_tokens,
    sum(c.usage_output_video_tokens)::bigint as output_video_tokens,
    sum(c.usage_image_inputs)::bigint as image_inputs,
    sum(c.usage_image_outputs)::bigint as image_outputs,
    sum(c.usage_audio_inputs)::bigint as audio_inputs,
    sum(c.usage_audio_outputs)::bigint as audio_outputs,
    sum(c.usage_video_inputs)::bigint as video_inputs,
    sum(c.usage_video_outputs)::bigint as video_outputs,
    sum(c.usage_cached_read_tokens)::bigint as cached_read_tokens,
    sum(c.usage_cached_write_tokens)::bigint as cached_write_tokens,
    sum(c.usage_cached_read_text_tokens)::bigint as cached_read_text_tokens,
    sum(c.usage_cached_write_text_tokens)::bigint as cached_write_text_tokens,
    sum(c.usage_cached_write_text_tokens_5m)::bigint as cached_write_text_tokens_5m,
    sum(c.usage_cached_write_text_tokens_1h)::bigint as cached_write_text_tokens_1h,
    sum(c.usage_cached_read_image_tokens)::bigint as cached_read_image_tokens,
    sum(c.usage_cached_write_image_tokens)::bigint as cached_write_image_tokens,
    sum(c.usage_cached_read_audio_tokens)::bigint as cached_read_audio_tokens,
    sum(c.usage_cached_write_audio_tokens)::bigint as cached_write_audio_tokens,
    sum(c.usage_cached_read_video_tokens)::bigint as cached_read_video_tokens,
    sum(c.usage_cached_write_video_tokens)::bigint as cached_write_video_tokens,
    sum(c.usage_input_quad_tokens)::bigint as input_quad_tokens,
    sum(c.usage_output_quad_tokens)::bigint as output_quad_tokens,
    sum(c.usage_total_quad_tokens)::bigint as total_quad_tokens,
    sum(c.usage_text_quad_tokens)::bigint as text_quad_tokens,
    sum(c.usage_rerank_quad_tokens)::bigint as rerank_quad_tokens,
    sum(c.usage_embedding_quad_tokens)::bigint as embedding_quad_tokens,
    sum(c.usage_moderation_quad_tokens)::bigint as moderation_quad_tokens,
    sum(c.usage_ocr_quad_tokens)::bigint as ocr_quad_tokens,
    sum(c.usage_image_megapixels)::numeric as image_megapixels,
    sum(c.usage_audio_seconds)::numeric as audio_seconds,
    sum(c.usage_video_pixel_seconds)::numeric as video_pixel_seconds,
    sum(c.usage_input_characters)::bigint as input_characters,
    sum(c.usage_output_characters)::bigint as output_characters,
    sum(c.usage_total_characters)::bigint as total_characters,
    sum(coalesce(c.cost_nanos, 0))::bigint as total_cost_nanos,
    sum(coalesce(c.latency_ms, 0)) filter (where c.latency_ms is not null)::bigint as latency_sum_ms,
    count(c.latency_ms)::bigint as latency_samples,
    sum(coalesce(c.generation_ms, 0)) filter (where c.generation_ms is not null)::bigint as generation_sum_ms,
    count(c.generation_ms)::bigint as generation_samples,
    sum(coalesce(c.throughput, 0)) filter (where c.throughput is not null)::numeric as throughput_sum,
    count(c.throughput)::bigint as throughput_samples,
    max(c.created_at) as last_request_at
  from classified c
  where c.model_id is not null
    and c.model_id <> ''
  group by c.day_bucket, c.model_id, c.provider_id, c.endpoint;
$$;


--
-- Name: gateway_requests_attach_chat_app_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_requests_attach_chat_app_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_key_name text;
  v_chat_app_key constant text := 'https://ai-stats.phaseo.app/chat';
  v_app_id uuid;
begin
  if new.app_id is not null then
    return new;
  end if;

  if new.workspace_id is null or new.key_id is null then
    return new;
  end if;

  select k.name into v_key_name
  from public.keys k
  where k.id = new.key_id
  limit 1;

  if coalesce(v_key_name, '') <> '__chat_route_managed_key__' then
    return new;
  end if;

  insert into public.api_apps (
    workspace_id,
    app_key,
    title,
    url,
    is_active,
    last_seen,
    updated_at,
    meta
  )
  values (
    new.workspace_id,
    v_chat_app_key,
    'AI Stats Chat',
    v_chat_app_key,
    true,
    coalesce(new.created_at, now()),
    now(),
    jsonb_build_object(
      'identityUrl', v_chat_app_key,
      'managed', true
    )
  )
  on conflict (workspace_id, app_key) do update
    set title = excluded.title,
        url = excluded.url,
        is_active = true,
        last_seen = greatest(public.api_apps.last_seen, excluded.last_seen),
        updated_at = now(),
        meta = coalesce(public.api_apps.meta, '{}'::jsonb) || excluded.meta
  returning id into v_app_id;

  new.app_id := v_app_id;
  return new;
end;
$$;


--
-- Name: gateway_set_async_operation_status(uuid, text, text, text, jsonb, boolean, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_set_async_operation_status(p_workspace_id uuid, p_kind text, p_internal_id text, p_status text DEFAULT NULL::text, p_meta_patch jsonb DEFAULT '{}'::jsonb, p_update_next_reconcile boolean DEFAULT false, p_next_reconcile_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_kind not in ('video', 'batch') then
    raise exception 'invalid async operation kind';
  end if;

  update public.gateway_async_operations
  set
    status = case
      when p_status is null then status
      when lower(coalesce(status, '')) in ('completed', 'failed', 'cancelled', 'canceled', 'expired') then status
      when (
        case lower(p_status)
          when 'queued' then 1 when 'pending' then 1
          when 'in_progress' then 2 when 'processing' then 2 when 'running' then 2
          when 'completed' then 3 when 'failed' then 3 when 'cancelled' then 3 when 'canceled' then 3 when 'expired' then 3
          else 0
        end
      ) < (
        case lower(coalesce(status, ''))
          when 'queued' then 1 when 'pending' then 1
          when 'in_progress' then 2 when 'processing' then 2 when 'running' then 2
          when 'completed' then 3 when 'failed' then 3 when 'cancelled' then 3 when 'canceled' then 3 when 'expired' then 3
          else 0
        end
      ) then status
      else p_status
    end,
    meta = coalesce(meta, '{}'::jsonb) || coalesce(p_meta_patch, '{}'::jsonb),
    next_reconcile_at = case
      when p_update_next_reconcile then p_next_reconcile_at
      else next_reconcile_at
    end,
    updated_at = now()
  where workspace_id = p_workspace_id
    and kind = p_kind
    and internal_id = p_internal_id;
end;
$$;


--
-- Name: FUNCTION gateway_set_async_operation_status(p_workspace_id uuid, p_kind text, p_internal_id text, p_status text, p_meta_patch jsonb, p_update_next_reconcile boolean, p_next_reconcile_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gateway_set_async_operation_status(p_workspace_id uuid, p_kind text, p_internal_id text, p_status text, p_meta_patch jsonb, p_update_next_reconcile boolean, p_next_reconcile_at timestamp with time zone) IS 'Service-role-only atomic metadata merge with monotonic async lifecycle transitions.';


--
-- Name: gateway_usage_nonnegative_bigint(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_usage_nonnegative_bigint(p_value numeric) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select greatest(coalesce(floor(p_value), 0), 0)::bigint;
$$;


--
-- Name: gateway_usage_numeric_field(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_usage_numeric_field(p_usage jsonb, VARIADIC p_keys text[]) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_key text;
  v_part text;
  v_cursor jsonb;
  v_value text;
begin
  if p_usage is null then
    return null;
  end if;

  foreach v_key in array p_keys loop
    v_cursor := p_usage;

    foreach v_part in array string_to_array(v_key, '.') loop
      if v_cursor is null or jsonb_typeof(v_cursor) <> 'object' or not (v_cursor ? v_part) then
        v_cursor := null;
        exit;
      end if;
      v_cursor := v_cursor -> v_part;
    end loop;

    if v_cursor is null then
      continue;
    end if;

    v_value := trim(both '"' from v_cursor::text);
    if v_value ~ '^-?[0-9]+(\.[0-9]+)?$' then
      return v_value::numeric;
    end if;
  end loop;

  return null;
end;
$_$;


--
-- Name: FUNCTION gateway_usage_numeric_field(p_usage jsonb, VARIADIC p_keys text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gateway_usage_numeric_field(p_usage jsonb, VARIADIC p_keys text[]) IS 'Safely reads the first numeric usage value matching the supplied top-level or dotted JSON key priority list.';


--
-- Name: gateway_usage_total_tokens(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_usage_total_tokens(p_usage jsonb) RETURNS bigint
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  select coalesce(
    case
      when coalesce(p_usage->>'total_tokens', '') ~ '^\d+$'
        then (p_usage->>'total_tokens')::bigint
      else null
    end,
    greatest(
      coalesce(case when coalesce(p_usage->>'input_text_tokens', '') ~ '^\d+$' then (p_usage->>'input_text_tokens')::bigint end, 0),
      coalesce(case when coalesce(p_usage->>'input_tokens', '') ~ '^\d+$' then (p_usage->>'input_tokens')::bigint end, 0),
      coalesce(case when coalesce(p_usage->>'prompt_tokens', '') ~ '^\d+$' then (p_usage->>'prompt_tokens')::bigint end, 0)
    )
    + greatest(
      coalesce(case when coalesce(p_usage->>'output_text_tokens', '') ~ '^\d+$' then (p_usage->>'output_text_tokens')::bigint end, 0),
      coalesce(case when coalesce(p_usage->>'output_tokens', '') ~ '^\d+$' then (p_usage->>'output_tokens')::bigint end, 0),
      coalesce(case when coalesce(p_usage->>'completion_tokens', '') ~ '^\d+$' then (p_usage->>'completion_tokens')::bigint end, 0)
    )
    + coalesce(case when coalesce(p_usage->>'reasoning_tokens', '') ~ '^\d+$' then (p_usage->>'reasoning_tokens')::bigint end, 0)
    + coalesce(case when coalesce(p_usage->>'cached_read_text_tokens', '') ~ '^\d+$' then (p_usage->>'cached_read_text_tokens')::bigint end, 0),
    0
  );
$_$;


--
-- Name: gateway_validate_pricing_time_windows(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_validate_pricing_time_windows(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  select
    jsonb_typeof(value) = 'array'
    and not exists (
      select 1
      from jsonb_array_elements(value) as item(window_value)
      where
        jsonb_typeof(item.window_value) is distinct from 'object'
        or jsonb_typeof(item.window_value->'label') is distinct from 'string'
        or btrim(item.window_value->>'label') = ''
        or item.window_value->>'timezone' is distinct from 'UTC'
        or coalesce(item.window_value->>'start_time', '') !~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9]$'
        or coalesce(item.window_value->>'end_time', '') !~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9]$'
        or item.window_value->>'start_time' = item.window_value->>'end_time'
        or (
          item.window_value ? 'price_per_unit'
          and case jsonb_typeof(item.window_value->'price_per_unit')
            when 'null' then false
            when 'number' then (item.window_value->>'price_per_unit')::numeric < 0
            when 'string' then
              case
                when btrim(item.window_value->>'price_per_unit') !~ '^[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?$' then true
                else (btrim(item.window_value->>'price_per_unit'))::numeric < 0
              end
            else true
          end
        )
        or (
          item.window_value ? 'priority'
          and case jsonb_typeof(item.window_value->'priority')
            when 'null' then false
            when 'number' then ((item.window_value->>'priority')::numeric % 1) <> 0
            else true
          end
        )
    );
$_$;


--
-- Name: gateway_wallet_capture_once(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_wallet_capture_once(p_workspace_id uuid, p_reservation_id text, p_capture_ref_id text DEFAULT NULL::text) RETURNS TABLE(ok boolean, applied boolean, reason text, amount_nanos bigint, before_balance_nanos bigint, after_balance_nanos bigint, before_reserved_nanos bigint, after_reserved_nanos bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_wallet public.wallets%rowtype;
  v_existing public.gateway_wallet_reservations%rowtype;
  v_amount bigint;
begin
  if p_workspace_id is null then
    raise exception 'workspace_id_required' using errcode = 'P0001';
  end if;
  if coalesce(trim(p_reservation_id), '') = '' then
    raise exception 'reservation_id_required' using errcode = 'P0001';
  end if;

  select * into v_existing
  from public.gateway_wallet_reservations
  where reservation_id = p_reservation_id
    and workspace_id = p_workspace_id
  for update;

  if not found then
    return query select false, false, 'reservation_not_found'::text, null::bigint,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  select * into v_wallet
  from public.wallets
  where workspace_id = p_workspace_id
  for update;

  if not found then
    return query select false, false, 'wallet_not_found'::text, v_existing.amount_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  if v_existing.status = 'captured' then
    return query select true, false, 'already_captured'::text, v_existing.amount_nanos,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  if v_existing.status <> 'reserved' then
    return query select false, false, 'reservation_not_active'::text, v_existing.amount_nanos,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  v_amount := v_existing.amount_nanos;

  if coalesce(v_wallet.reserved_nanos, 0) < v_amount then
    return query select false, false, 'reserved_balance_mismatch'::text, v_amount,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  update public.wallets
  set balance_nanos = coalesce(balance_nanos, 0) - v_amount,
      reserved_nanos = coalesce(reserved_nanos, 0) - v_amount,
      updated_at = now()
  where workspace_id = p_workspace_id
  returning *
  into v_wallet;

  update public.gateway_wallet_reservations
  set status = 'captured',
      capture_ref_id = nullif(trim(coalesce(p_capture_ref_id, '')), ''),
      captured_at = now(),
      updated_at = now()
  where reservation_id = p_reservation_id
    and workspace_id = p_workspace_id;

  return query select true, true, null::text, v_amount,
    coalesce(v_wallet.balance_nanos, 0) + v_amount,
    coalesce(v_wallet.balance_nanos, 0),
    coalesce(v_wallet.reserved_nanos, 0) + v_amount,
    coalesce(v_wallet.reserved_nanos, 0);
end;
$$;


--
-- Name: gateway_wallet_release_once(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_wallet_release_once(p_workspace_id uuid, p_reservation_id text, p_release_ref_id text DEFAULT NULL::text) RETURNS TABLE(ok boolean, applied boolean, reason text, amount_nanos bigint, before_balance_nanos bigint, after_balance_nanos bigint, before_reserved_nanos bigint, after_reserved_nanos bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_wallet public.wallets%rowtype;
  v_existing public.gateway_wallet_reservations%rowtype;
  v_amount bigint;
begin
  if p_workspace_id is null then
    raise exception 'workspace_id_required' using errcode = 'P0001';
  end if;
  if coalesce(trim(p_reservation_id), '') = '' then
    raise exception 'reservation_id_required' using errcode = 'P0001';
  end if;

  select * into v_existing
  from public.gateway_wallet_reservations
  where reservation_id = p_reservation_id
    and workspace_id = p_workspace_id
  for update;

  if not found then
    return query select false, false, 'reservation_not_found'::text, null::bigint,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  select * into v_wallet
  from public.wallets
  where workspace_id = p_workspace_id
  for update;

  if not found then
    return query select false, false, 'wallet_not_found'::text, v_existing.amount_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  if v_existing.status = 'released' then
    return query select true, false, 'already_released'::text, v_existing.amount_nanos,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  if v_existing.status <> 'reserved' then
    return query select false, false, 'reservation_not_active'::text, v_existing.amount_nanos,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  v_amount := v_existing.amount_nanos;

  if coalesce(v_wallet.reserved_nanos, 0) < v_amount then
    return query select false, false, 'reserved_balance_mismatch'::text, v_amount,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.balance_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint,
      coalesce(v_wallet.reserved_nanos, 0)::bigint;
    return;
  end if;

  update public.wallets
  set reserved_nanos = coalesce(reserved_nanos, 0) - v_amount,
      updated_at = now()
  where workspace_id = p_workspace_id
  returning *
  into v_wallet;

  update public.gateway_wallet_reservations
  set status = 'released',
      release_ref_id = nullif(trim(coalesce(p_release_ref_id, '')), ''),
      released_at = now(),
      updated_at = now()
  where reservation_id = p_reservation_id
    and workspace_id = p_workspace_id;

  return query select true, true, null::text, v_amount,
    coalesce(v_wallet.balance_nanos, 0),
    coalesce(v_wallet.balance_nanos, 0),
    coalesce(v_wallet.reserved_nanos, 0) + v_amount,
    coalesce(v_wallet.reserved_nanos, 0);
end;
$$;


--
-- Name: gateway_wallet_release_stale_orphan_batch_reservations(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_wallet_release_stale_orphan_batch_reservations(p_older_than_seconds integer DEFAULT 1800, p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_reservation public.gateway_wallet_reservations%rowtype;
  v_released integer := 0;
begin
  for v_reservation in
    select reservation.*
    from public.gateway_wallet_reservations reservation
    where reservation.reservation_id like 'batch_hold:%'
      and reservation.status in ('held', 'reserved')
      and reservation.created_at < now() - make_interval(secs => greatest(300, p_older_than_seconds))
      and not exists (
        select 1
        from public.gateway_async_operations operation
        where operation.workspace_id = reservation.workspace_id
          and operation.kind = 'batch'
          and (
            operation.request_id = reservation.hold_ref_id
            or operation.meta ->> 'reservationId' = reservation.reservation_id
            or operation.meta ->> 'reservation_id' = reservation.reservation_id
          )
      )
    order by reservation.created_at asc
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 100), 1000))
  loop
    update public.wallets
    set reserved_nanos = greatest(0, coalesce(reserved_nanos, 0) - v_reservation.amount_nanos),
        updated_at = now()
    where workspace_id = v_reservation.workspace_id
      and coalesce(reserved_nanos, 0) >= v_reservation.amount_nanos;

    if found then
      update public.gateway_wallet_reservations
      set status = 'released',
          release_ref_id = 'stale_orphan_batch_reaper',
          released_at = now(),
          updated_at = now()
      where workspace_id = v_reservation.workspace_id
        and reservation_id = v_reservation.reservation_id;
      v_released := v_released + 1;
    end if;
  end loop;
  return v_released;
end;
$$;


--
-- Name: gateway_wallet_reserve_once(uuid, text, bigint, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_wallet_reserve_once(p_workspace_id uuid, p_reservation_id text, p_amount_nanos bigint, p_hold_ref_id text DEFAULT NULL::text, p_key_id uuid DEFAULT NULL::uuid, p_request_count integer DEFAULT NULL::integer) RETURNS TABLE(ok boolean, applied boolean, reason text, amount_nanos bigint, before_balance_nanos bigint, after_balance_nanos bigint, before_reserved_nanos bigint, after_reserved_nanos bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_wallet public.wallets%rowtype;
  v_existing public.gateway_wallet_reservations%rowtype;
  v_key public.keys%rowtype;
  v_available bigint;
  v_before_balance bigint;
  v_before_reserved bigint;
  v_day_start timestamptz := (date_trunc('day', now() at time zone 'utc') at time zone 'utc');
  v_week_start timestamptz := (date_trunc('week', now() at time zone 'utc') at time zone 'utc');
  v_month_start timestamptz := (date_trunc('month', now() at time zone 'utc') at time zone 'utc');
  v_day_requests bigint := 0;
  v_week_requests bigint := 0;
  v_month_requests bigint := 0;
  v_day_cost bigint := 0;
  v_week_cost bigint := 0;
  v_month_cost bigint := 0;
  v_requested_count integer := greatest(0, coalesce(p_request_count, 0));
begin
  if p_workspace_id is null or coalesce(trim(p_reservation_id), '') = '' then
    raise exception 'invalid_reservation_identity';
  end if;
  if p_amount_nanos is null or p_amount_nanos <= 0 then
    raise exception 'invalid_reservation_amount';
  end if;
  if p_key_id is not null and v_requested_count <= 0 then
    raise exception 'batch_request_count_required';
  end if;
  if v_requested_count > 10000 then
    raise exception 'batch_request_limit_exceeded';
  end if;

  select * into v_existing
  from public.gateway_wallet_reservations
  where workspace_id = p_workspace_id and reservation_id = p_reservation_id
  for update;
  if found then
    select * into v_wallet from public.wallets
    where workspace_id = p_workspace_id for update;
    if not found then
      return query select false, false, 'wallet_not_found'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if v_existing.amount_nanos <> p_amount_nanos
      or v_existing.key_id is distinct from p_key_id
      or coalesce(v_existing.request_count, 0) <> v_requested_count then
      raise exception 'reservation_identity_mismatch';
    end if;
    if v_existing.status in ('held', 'reserved') then
      return query select true, false, 'already_reserved'::text, v_existing.amount_nanos,
        coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
        coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
      return;
    end if;
    return query select false, false, 'reservation_not_active'::text, v_existing.amount_nanos,
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;

  if p_key_id is not null then
    select * into v_key from public.keys where id = p_key_id for update;
    if not found then
      return query select false, false, 'key_not_found'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if v_key.workspace_id <> p_workspace_id then
      return query select false, false, 'key_wrong_workspace'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if v_key.status <> 'active' or (v_key.expires_at is not null and v_key.expires_at <= now()) then
      return query select false, false, 'key_not_active'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.soft_blocked, false) then
      return query select false, false, 'key_limit_soft_blocked'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;

    select
      count(*) filter (where created_at >= v_day_start),
      count(*) filter (where created_at >= v_week_start),
      count(*) filter (where created_at >= v_month_start),
      coalesce(sum(cost_nanos) filter (where created_at >= v_day_start), 0),
      coalesce(sum(cost_nanos) filter (where created_at >= v_week_start), 0),
      coalesce(sum(cost_nanos) filter (where created_at >= v_month_start), 0)
    into v_day_requests, v_week_requests, v_month_requests,
      v_day_cost, v_week_cost, v_month_cost
    from public.gateway_requests
    where workspace_id = p_workspace_id and key_id = p_key_id and success is true;

    if coalesce(v_key.daily_limit_requests, 0) > 0
      and v_day_requests + v_requested_count > v_key.daily_limit_requests then
      return query select false, false, 'daily_request_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.weekly_limit_requests, 0) > 0
      and v_week_requests + v_requested_count > v_key.weekly_limit_requests then
      return query select false, false, 'weekly_request_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.monthly_limit_requests, 0) > 0
      and v_month_requests + v_requested_count > v_key.monthly_limit_requests then
      return query select false, false, 'monthly_request_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.daily_limit_cost_nanos, 0) > 0
      and v_day_cost + p_amount_nanos > v_key.daily_limit_cost_nanos then
      return query select false, false, 'daily_cost_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.weekly_limit_cost_nanos, 0) > 0
      and v_week_cost + p_amount_nanos > v_key.weekly_limit_cost_nanos then
      return query select false, false, 'weekly_cost_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
    if coalesce(v_key.monthly_limit_cost_nanos, 0) > 0
      and v_month_cost + p_amount_nanos > v_key.monthly_limit_cost_nanos then
      return query select false, false, 'monthly_cost_limit_reached'::text, p_amount_nanos,
        null::bigint, null::bigint, null::bigint, null::bigint;
      return;
    end if;
  end if;

  select * into v_wallet from public.wallets
  where workspace_id = p_workspace_id for update;
  if not found then
    return query select false, false, 'wallet_not_found'::text, p_amount_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;
  v_available := coalesce(v_wallet.balance_nanos, 0) - coalesce(v_wallet.reserved_nanos, 0);
  if v_available < p_amount_nanos then
    return query select false, false, 'insufficient_balance'::text, p_amount_nanos,
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;

  insert into public.gateway_wallet_reservations (
    reservation_id, workspace_id, amount_nanos, status, hold_ref_id,
    key_id, request_count, created_at, updated_at
  ) values (
    p_reservation_id, p_workspace_id, p_amount_nanos, 'reserved',
    nullif(trim(coalesce(p_hold_ref_id, '')), ''), p_key_id,
    nullif(v_requested_count, 0), now(), now()
  );

  v_before_balance := coalesce(v_wallet.balance_nanos, 0);
  v_before_reserved := coalesce(v_wallet.reserved_nanos, 0);
  update public.wallets
  set reserved_nanos = v_before_reserved + p_amount_nanos, updated_at = now()
  where workspace_id = p_workspace_id
  returning * into v_wallet;

  if p_key_id is not null then
    insert into public.gateway_requests (
      workspace_id, request_id, endpoint, model_id, provider,
      status_code, success, usage, cost_nanos, currency, key_id
    )
    select
      p_workspace_id,
      'batch_hold_usage:' || p_reservation_id || ':' || item::text,
      'batch',
      'batch/reserved',
      null,
      202,
      true,
      jsonb_build_object('batch_reserved', true),
      (p_amount_nanos / v_requested_count)
        + case when item <= (p_amount_nanos % v_requested_count) then 1 else 0 end,
      'USD',
      p_key_id
    from generate_series(1, v_requested_count) as item
    ;
  end if;

  return query select true, true, null::text, p_amount_nanos,
    v_before_balance, coalesce(v_wallet.balance_nanos, 0),
    v_before_reserved, coalesce(v_wallet.reserved_nanos, 0);
end;
$$;


--
-- Name: gateway_wallet_settle_once(uuid, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gateway_wallet_settle_once(p_workspace_id uuid, p_reservation_id text, p_actual_nanos bigint, p_settle_ref_id text DEFAULT NULL::text) RETURNS TABLE(ok boolean, applied boolean, reason text, amount_nanos bigint, before_balance_nanos bigint, after_balance_nanos bigint, before_reserved_nanos bigint, after_reserved_nanos bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_wallet public.wallets%rowtype;
  v_reservation public.gateway_wallet_reservations%rowtype;
  v_before_balance bigint;
  v_before_reserved bigint;
  v_available_for_settlement bigint;
begin
  if p_workspace_id is null or coalesce(trim(p_reservation_id), '') = '' then
    raise exception 'invalid_batch_reservation_identity';
  end if;
  if p_actual_nanos is null or p_actual_nanos < 0 then
    raise exception 'invalid_actual_nanos';
  end if;

  select * into v_reservation
  from public.gateway_wallet_reservations
  where workspace_id = p_workspace_id and reservation_id = p_reservation_id
  for update;
  if not found then
    return query select false, false, 'reservation_not_found'::text, p_actual_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  select * into v_wallet from public.wallets
  where workspace_id = p_workspace_id for update;
  if not found then
    return query select false, false, 'wallet_not_found'::text, p_actual_nanos,
      null::bigint, null::bigint, null::bigint, null::bigint;
    return;
  end if;

  if v_reservation.status = 'captured' then
    if coalesce(v_reservation.settled_amount_nanos, v_reservation.amount_nanos) <> p_actual_nanos then
      raise exception 'reservation_settlement_amount_mismatch';
    end if;
    return query select true, false, 'already_captured'::text, p_actual_nanos,
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;

  if v_reservation.status not in ('held', 'reserved') then
    return query select false, false, 'reservation_not_active'::text, p_actual_nanos,
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;
  if coalesce(v_wallet.reserved_nanos, 0) < v_reservation.amount_nanos then
    return query select false, false, 'reserved_balance_mismatch'::text, p_actual_nanos,
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;

  -- The reservation itself is available to this settlement; all other holds
  -- remain excluded from spendable balance.
  v_available_for_settlement := coalesce(v_wallet.balance_nanos, 0)
    - coalesce(v_wallet.reserved_nanos, 0)
    + v_reservation.amount_nanos;
  if p_actual_nanos > v_available_for_settlement then
    return query select false, false, 'insufficient_balance'::text, p_actual_nanos,
      coalesce(v_wallet.balance_nanos, 0), coalesce(v_wallet.balance_nanos, 0),
      coalesce(v_wallet.reserved_nanos, 0), coalesce(v_wallet.reserved_nanos, 0);
    return;
  end if;

  v_before_balance := coalesce(v_wallet.balance_nanos, 0);
  v_before_reserved := coalesce(v_wallet.reserved_nanos, 0);
  update public.wallets
  set balance_nanos = v_before_balance - p_actual_nanos,
      reserved_nanos = v_before_reserved - v_reservation.amount_nanos,
      updated_at = now()
  where workspace_id = p_workspace_id
  returning * into v_wallet;

  update public.gateway_wallet_reservations
  set status = 'captured',
      settled_amount_nanos = p_actual_nanos,
      capture_ref_id = nullif(trim(coalesce(p_settle_ref_id, '')), ''),
      captured_at = now(),
      updated_at = now()
  where workspace_id = p_workspace_id and reservation_id = p_reservation_id;

  return query select true, true, null::text, p_actual_nanos,
    v_before_balance, coalesce(v_wallet.balance_nanos, 0),
    v_before_reserved, coalesce(v_wallet.reserved_nanos, 0);
end;
$$;


--
-- Name: get_app_rising_model(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_app_rising_model(p_app_id uuid, p_recent_days integer DEFAULT 7, p_previous_days integer DEFAULT 7) RETURNS TABLE(model_id text, provider text, recent_tokens bigint, previous_tokens bigint, delta_tokens bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with recent as (
    select
      coalesce(gr.model_id, 'Unknown model') as model_id,
      gr.provider as provider,
      sum(coalesce((gr.usage->>'total_tokens')::bigint, 0))::bigint as tokens
    from private.v2_rpc_gateway_requests_compat gr
    where gr.app_id = p_app_id
      and gr.success = true
      and gr.created_at >= now() - (p_recent_days::text || ' days')::interval
    group by 1, 2
  ),
  previous as (
    select
      coalesce(gr.model_id, 'Unknown model') as model_id,
      gr.provider as provider,
      sum(coalesce((gr.usage->>'total_tokens')::bigint, 0))::bigint as tokens
    from private.v2_rpc_gateway_requests_compat gr
    where gr.app_id = p_app_id
      and gr.success = true
      and gr.created_at >= now() - ((p_recent_days + p_previous_days)::text || ' days')::interval
      and gr.created_at < now() - (p_recent_days::text || ' days')::interval
    group by 1, 2
  ),
  combined as (
    select
      r.model_id,
      r.provider,
      r.tokens as recent_tokens,
      coalesce(p.tokens, 0)::bigint as previous_tokens,
      (r.tokens - coalesce(p.tokens, 0))::bigint as delta_tokens
    from recent r
    left join previous p
      on p.model_id = r.model_id
      and (
        (p.provider is null and r.provider is null)
        or p.provider = r.provider
      )
  )
  select
    model_id,
    provider,
    recent_tokens,
    previous_tokens,
    delta_tokens
  from combined
  order by delta_tokens desc
  limit 1;
$$;


--
-- Name: get_app_top_model_all_time(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_app_top_model_all_time(p_app_id uuid) RETURNS TABLE(model_id text, provider text, tokens bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    coalesce(gr.model_id, 'Unknown model') as model_id,
    gr.provider as provider,
    sum(coalesce((gr.usage->>'total_tokens')::bigint, 0))::bigint as tokens
  from private.v2_rpc_gateway_requests_compat gr
  where gr.app_id = p_app_id
    and gr.success = true
  group by 1, 2
  order by tokens desc
  limit 1;
$$;


--
-- Name: get_app_top_models(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_app_top_models(p_app_id uuid, p_days integer DEFAULT 28, p_limit integer DEFAULT 6) RETURNS TABLE(model_id text, provider text, tokens bigint, requests bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    coalesce(gr.model_id, 'Unknown model') as model_id,
    gr.provider as provider,
    sum(coalesce((gr.usage->>'total_tokens')::bigint, 0))::bigint as tokens,
    count(*)::bigint as requests
  from private.v2_rpc_gateway_requests_compat gr
  where gr.app_id = p_app_id
    and gr.success = true
    and gr.created_at >= now() - (p_days::text || ' days')::interval
  group by 1, 2
  order by tokens desc, requests desc
  limit p_limit;
$$;


--
-- Name: get_app_totals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_app_totals(p_app_id uuid) RETURNS TABLE(total_tokens bigint, total_requests bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    sum(coalesce((gr.usage->>'total_tokens')::bigint, 0))::bigint as total_tokens,
    count(*)::bigint as total_requests
  from private.v2_rpc_gateway_requests_compat gr
  where gr.app_id = p_app_id
    and gr.success = true;
$$;


--
-- Name: get_app_usage_timeseries(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_app_usage_timeseries(p_app_id uuid, p_days integer DEFAULT 28) RETURNS TABLE(bucket date, model_id text, tokens bigint, requests bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    date_trunc('day', gr.created_at)::date as bucket,
    coalesce(gr.model_id, 'Unknown model') as model_id,
    sum(coalesce((gr.usage->>'total_tokens')::bigint, 0))::bigint as tokens,
    count(*)::bigint as requests
  from private.v2_rpc_gateway_requests_compat gr
  where gr.app_id = p_app_id
    and gr.success = true
    and gr.created_at >= now() - (p_days::text || ' days')::interval
  group by 1, 2
  order by 1, 2;
$$;


--
-- Name: get_benchmark_result_rankings(text[], text, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_benchmark_result_rankings(p_benchmark_ids text[] DEFAULT NULL::text[], p_model_id text DEFAULT NULL::text, p_include_hidden boolean DEFAULT false, p_limit_per_benchmark integer DEFAULT NULL::integer) RETURNS TABLE(result_id uuid, model_id text, benchmark_id text, score text, score_numeric numeric, is_self_reported boolean, other_info text, source_link text, created_at timestamp with time zone, updated_at timestamp with time zone, occur_idx integer, variant text, result_key text, benchmark_rank bigint, total_ranked_models bigint, is_primary_result boolean, model_name text, release_date timestamp with time zone, announcement_date timestamp with time zone, organisation_id text, organisation_name text, organisation_colour text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with target_benchmarks as (
    select
      b.id,
      b.ascending_order,
      b.type
    from private.v2_rpc_benchmarks_compat b
    where
      (p_benchmark_ids is null or b.id = any (p_benchmark_ids))
      and (
        p_model_id is null
        or exists (
          select 1
          from private.v2_rpc_benchmark_results_compat requested_result
          where requested_result.benchmark_id = b.id
            and requested_result.model_id = p_model_id
        )
      )
  ),
  scoped_results as (
    select
      result.*,
      model.name as model_name,
      model.release_date,
      model.announcement_date,
      model.organisation_id,
      organisation.name as organisation_name,
      organisation.colour as organisation_colour,
      target.ascending_order,
      case
        when target.type = 'percentage'
          and abs(result.score_numeric) > 0
          and abs(result.score_numeric) <= 1
          then result.score_numeric * 100
        else result.score_numeric
      end as comparable_score
    from target_benchmarks target
    join private.v2_rpc_benchmark_results_compat result
      on result.benchmark_id = target.id
    join private.v2_rpc_models_compat model
      on model.model_id = result.model_id
    left join private.v2_rpc_labs_compat organisation
      on organisation.organisation_id = model.organisation_id
    where p_include_hidden or not coalesce(model.hidden, false)
  ),
  model_scores as (
    select
      scoped.benchmark_id,
      scoped.model_id,
      bool_or(scoped.ascending_order is false) as lower_is_better,
      case
        when bool_or(scoped.ascending_order is false)
          then min(scoped.comparable_score)
        else max(scoped.comparable_score)
      end as primary_score
    from scoped_results scoped
    where scoped.comparable_score is not null
    group by scoped.benchmark_id, scoped.model_id
  ),
  ranked_models as (
    select
      scores.benchmark_id,
      scores.model_id,
      scores.primary_score,
      rank() over (
        partition by scores.benchmark_id
        order by
          case when scores.lower_is_better then scores.primary_score end asc nulls last,
          case when not scores.lower_is_better then scores.primary_score end desc nulls last
      ) as benchmark_rank,
      count(*) over (
        partition by scores.benchmark_id
      ) as total_ranked_models
    from model_scores scores
  ),
  selected_models as (
    select
      roster.benchmark_id,
      roster.model_id,
      ranked.primary_score,
      ranked.benchmark_rank,
      ranked.total_ranked_models
    from (
      select distinct scoped.benchmark_id, scoped.model_id
      from scoped_results scoped
    ) roster
    left join ranked_models ranked
      on ranked.benchmark_id = roster.benchmark_id
     and ranked.model_id = roster.model_id
    where
      (p_model_id is null or roster.model_id = p_model_id)
      and (
        p_limit_per_benchmark is null
        or ranked.benchmark_rank <= greatest(p_limit_per_benchmark, 1)
      )
  )
  select
    scoped.id as result_id,
    scoped.model_id,
    scoped.benchmark_id,
    scoped.score,
    scoped.score_numeric,
    scoped.is_self_reported,
    scoped.other_info,
    scoped.source_link,
    scoped.created_at,
    scoped.updated_at,
    scoped.occur_idx,
    scoped.variant,
    scoped.result_key,
    ranked.benchmark_rank,
    ranked.total_ranked_models,
    ranked.primary_score is not null
      and scoped.comparable_score is not distinct from ranked.primary_score
      as is_primary_result,
    scoped.model_name,
    scoped.release_date,
    scoped.announcement_date,
    scoped.organisation_id,
    scoped.organisation_name,
    scoped.organisation_colour
  from scoped_results scoped
  join selected_models ranked
    on ranked.benchmark_id = scoped.benchmark_id
   and ranked.model_id = scoped.model_id
  order by
    scoped.benchmark_id,
    ranked.benchmark_rank,
    scoped.model_id,
    scoped.occur_idx,
    scoped.id;
$$;


--
-- Name: FUNCTION get_benchmark_result_rankings(p_benchmark_ids text[], p_model_id text, p_include_hidden boolean, p_limit_per_benchmark integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_benchmark_result_rankings(p_benchmark_ids text[], p_model_id text, p_include_hidden boolean, p_limit_per_benchmark integer) IS 'Returns tie-aware model-level benchmark ranks derived from numeric result scores, while preserving every source-result variant for display.';


--
-- Name: get_data_contribution_totals(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_data_contribution_totals(p_workspace_id uuid, p_since timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'contributions', count(*),
    'discount_nanos', coalesce(sum(contribution.discount_nanos), 0)
  )
  from public.data_contributions contribution
  where contribution.workspace_id = p_workspace_id
    and contribution.created_at >= p_since;
$$;


--
-- Name: get_gateway_jobs_rollup(uuid, integer, integer, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_gateway_jobs_rollup(p_team uuid, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0, p_kind text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_session_id text DEFAULT NULL::text, p_provider text DEFAULT NULL::text) RETURNS TABLE(job_id uuid, kind text, internal_id text, request_id text, session_id text, app_id uuid, provider text, model text, status text, billed_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, request_created_at timestamp with time zone, request_endpoint text, request_model_id text, request_cost_nanos bigint, request_cost_usd numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with filtered_ops as (
    select op.*
    from public.gateway_async_operations op
    where op.workspace_id = p_team
      and (p_kind is null or op.kind = p_kind)
      and (p_status is null or op.status = p_status)
      and (p_session_id is null or op.session_id = p_session_id)
      and (p_provider is null or op.provider = p_provider)
  ),
  request_lookup as (
    select
      gr.workspace_id,
      gr.request_id,
      gr.created_at,
      gr.endpoint,
      gr.model_id,
      gr.cost_nanos,
      row_number() over (
        partition by gr.workspace_id, gr.request_id
        order by gr.created_at desc
      ) as rn
    from private.v2_rpc_gateway_requests_compat gr
    where gr.workspace_id = p_team
  )
  select
    op.id as job_id,
    op.kind,
    op.internal_id,
    op.request_id,
    op.session_id,
    op.app_id,
    op.provider,
    op.model,
    op.status,
    op.billed_at,
    op.created_at,
    op.updated_at,
    req.created_at as request_created_at,
    req.endpoint as request_endpoint,
    req.model_id as request_model_id,
    req.cost_nanos as request_cost_nanos,
    coalesce(req.cost_nanos, 0)::numeric / 1e9 as request_cost_usd
  from filtered_ops op
  left join request_lookup req
    on req.workspace_id = op.workspace_id
   and req.request_id = op.request_id
   and req.rn = 1
  order by op.updated_at desc
  limit greatest(1, least(coalesce(p_limit, 100), 500))
  offset greatest(0, coalesce(p_offset, 0));
$$;


--
-- Name: FUNCTION get_gateway_jobs_rollup(p_team uuid, p_limit integer, p_offset integer, p_kind text, p_status text, p_session_id text, p_provider text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_gateway_jobs_rollup(p_team uuid, p_limit integer, p_offset integer, p_kind text, p_status text, p_session_id text, p_provider text) IS 'Workspace-scoped async jobs rollup from gateway_async_operations with optional linkage to source gateway request.';


--
-- Name: get_gateway_marketing_rollup(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_gateway_marketing_rollup(p_hours integer DEFAULT 24) RETURNS TABLE(bucket_hour timestamp with time zone, requests bigint, success_requests bigint, total_tokens bigint, latency_sum_ms numeric, latency_samples bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    date_trunc('hour', r.bucket_15m) as bucket_hour,
    sum(r.requests)::bigint as requests,
    sum(r.success_requests)::bigint as success_requests,
    sum(r.total_tokens)::bigint as total_tokens,
    sum(r.latency_sum_ms)::numeric as latency_sum_ms,
    sum(r.latency_samples)::bigint as latency_samples
  from public.v2_web_public_usage_hourly r
  where r.bucket_15m >= now() - make_interval(hours => greatest(1, p_hours))
  group by date_trunc('hour', r.bucket_15m)
  order by date_trunc('hour', r.bucket_15m);
$$;


--
-- Name: get_gateway_request_facets(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_gateway_request_facets(p_workspace_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(facet text, value text, value_label text, request_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with scoped as materialized (
    select
      gr.model_id,
      gr.provider,
      gr.app_id::text as app_id,
	  gr.key_id::text as key_id,
      gr.endpoint,
	  case when gr.stream then 'streaming' else 'non_streaming' end as stream_mode,
      gr.finish_reason,
      gr.error_code,
      gr.status_code::text as status_code,
      case when gr.success then 'success' else 'error' end as request_status,
      gr.client_source_id,
      gr.client_source_name
    from public.gateway_requests gr
    where gr.workspace_id = p_workspace_id
      and gr.created_at >= p_from
      and gr.created_at <= p_to
      and gr.endpoint not in ('video.generation', 'batch', 'music.generate')
  )
  select 'model', model_id, null::text, count(*) from scoped where model_id is not null group by model_id
  union all
  select 'provider', provider, null::text, count(*) from scoped where provider is not null group by provider
  union all
  select 'app', app_id, null::text, count(*) from scoped where app_id is not null group by app_id
  union all
	select 'key', key_id, null::text, count(*) from scoped where key_id is not null group by key_id
	union all
  select 'endpoint', endpoint, null::text, count(*) from scoped where endpoint is not null group by endpoint
  union all
	select 'stream', stream_mode, null::text, count(*) from scoped group by stream_mode
	union all
  select 'finish_reason', finish_reason, null::text, count(*) from scoped where finish_reason is not null group by finish_reason
  union all
  select 'error_code', error_code, null::text, count(*) from scoped where error_code is not null group by error_code
  union all
  select 'http_status', status_code, null::text, count(*) from scoped where status_code is not null group by status_code
  union all
  select 'status', request_status, null::text, count(*) from scoped group by request_status
  union all
  select 'source', client_source_id, max(client_source_name), count(*) from scoped where client_source_id is not null group by client_source_id;
$$;


--
-- Name: FUNCTION get_gateway_request_facets(p_workspace_id uuid, p_from timestamp with time zone, p_to timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_gateway_request_facets(p_workspace_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) IS 'Workspace/time-scoped exact request filter counts. Uses caller RLS and returns no raw request payloads.';


--
-- Name: get_gateway_request_facets(uuid, timestamp with time zone, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_gateway_request_facets(p_workspace_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_filters jsonb) RETURNS TABLE(facet text, value text, value_label text, request_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with scoped as materialized (
    select
      gr.model_id,
      gr.provider,
      gr.app_id::text as app_id,
      gr.key_id::text as key_id,
      gr.endpoint,
      case when gr.stream then 'streaming' else 'non_streaming' end as stream_mode,
      gr.finish_reason,
      gr.error_code,
      gr.status_code::text as status_code,
      case when gr.success then 'success' else 'error' end as request_status,
      gr.client_source_id,
      gr.client_source_name
    from public.gateway_requests gr
    where gr.workspace_id = p_workspace_id
      and gr.created_at >= p_from
      and gr.created_at <= p_to
      and gr.endpoint not in ('video.generation', 'batch', 'music.generate')
      and (not (p_filters ? 'model') or case when p_filters->>'model_op' = 'is_not' then gr.model_id is distinct from p_filters->>'model' else gr.model_id = p_filters->>'model' end)
      and (not (p_filters ? 'provider') or case when p_filters->>'provider_op' = 'is_not' then gr.provider is distinct from p_filters->>'provider' else gr.provider = p_filters->>'provider' end)
      and (not (p_filters ? 'app') or case when p_filters->>'app_op' = 'is_not' then gr.app_id::text is distinct from p_filters->>'app' else gr.app_id::text = p_filters->>'app' end)
      and (not (p_filters ? 'key') or case when p_filters->>'key_op' = 'is_not' then gr.key_id::text is distinct from p_filters->>'key' else gr.key_id::text = p_filters->>'key' end)
      and (not (p_filters ? 'endpoint') or case when p_filters->>'endpoint_op' = 'is_not' then gr.endpoint is distinct from p_filters->>'endpoint' else gr.endpoint = p_filters->>'endpoint' end)
      and (not (p_filters ? 'finish_reason') or case when p_filters->>'finish_op' = 'is_not' then gr.finish_reason is distinct from p_filters->>'finish_reason' else gr.finish_reason = p_filters->>'finish_reason' end)
      and (not (p_filters ? 'error_code') or case when p_filters->>'error_op' = 'is_not' then gr.error_code is distinct from p_filters->>'error_code' else gr.error_code = p_filters->>'error_code' end)
      and (not (p_filters ? 'http_status') or case when p_filters->>'http_op' = 'is_not' then gr.status_code is distinct from (p_filters->>'http_status')::integer else gr.status_code = (p_filters->>'http_status')::integer end)
      and (not (p_filters ? 'source') or case when p_filters->>'source_op' = 'is_not' then gr.client_source_id is distinct from p_filters->>'source' else gr.client_source_id = p_filters->>'source' end)
      and (not (p_filters ? 'stream') or case when p_filters->>'stream_op' = 'is_not' then gr.stream is distinct from ((p_filters->>'stream') = 'streaming') else gr.stream = ((p_filters->>'stream') = 'streaming') end)
      and (not (p_filters ? 'status') or case when p_filters->>'status_op' = 'is_not' then gr.success is distinct from ((p_filters->>'status') = 'success') else gr.success = ((p_filters->>'status') = 'success') end)
      and (not (p_filters ? 'input_tokens') or case p_filters->>'input_tokens_op' when 'eq' then gr.usage_input_tokens = (p_filters->>'input_tokens')::bigint when 'lte' then gr.usage_input_tokens <= (p_filters->>'input_tokens')::bigint when 'between' then gr.usage_input_tokens between (p_filters->>'input_tokens')::bigint and (p_filters->>'input_tokens_max')::bigint else gr.usage_input_tokens >= (p_filters->>'input_tokens')::bigint end)
      and (not (p_filters ? 'output_tokens') or case p_filters->>'output_tokens_op' when 'eq' then gr.usage_output_tokens = (p_filters->>'output_tokens')::bigint when 'lte' then gr.usage_output_tokens <= (p_filters->>'output_tokens')::bigint when 'between' then gr.usage_output_tokens between (p_filters->>'output_tokens')::bigint and (p_filters->>'output_tokens_max')::bigint else gr.usage_output_tokens >= (p_filters->>'output_tokens')::bigint end)
      and (not (p_filters ? 'total_tokens') or case p_filters->>'total_tokens_op' when 'eq' then gr.usage_total_tokens = (p_filters->>'total_tokens')::bigint when 'lte' then gr.usage_total_tokens <= (p_filters->>'total_tokens')::bigint when 'between' then gr.usage_total_tokens between (p_filters->>'total_tokens')::bigint and (p_filters->>'total_tokens_max')::bigint else gr.usage_total_tokens >= (p_filters->>'total_tokens')::bigint end)
  )
  select 'model', model_id, null::text, count(*) from scoped where model_id is not null group by model_id
  union all select 'provider', provider, null::text, count(*) from scoped where provider is not null group by provider
  union all select 'app', app_id, null::text, count(*) from scoped where app_id is not null group by app_id
  union all select 'key', key_id, null::text, count(*) from scoped where key_id is not null group by key_id
  union all select 'endpoint', endpoint, null::text, count(*) from scoped where endpoint is not null group by endpoint
  union all select 'stream', stream_mode, null::text, count(*) from scoped group by stream_mode
  union all select 'finish_reason', finish_reason, null::text, count(*) from scoped where finish_reason is not null group by finish_reason
  union all select 'error_code', error_code, null::text, count(*) from scoped where error_code is not null group by error_code
  union all select 'http_status', status_code, null::text, count(*) from scoped where status_code is not null group by status_code
  union all select 'status', request_status, null::text, count(*) from scoped group by request_status
  union all select 'source', client_source_id, max(client_source_name), count(*) from scoped where client_source_id is not null group by client_source_id;
$$;


--
-- Name: FUNCTION get_gateway_request_facets(p_workspace_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_filters jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_gateway_request_facets(p_workspace_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_filters jsonb) IS 'Exact workspace/time request-log facet counts after applying the current categorical and token filters.';


--
-- Name: get_gateway_request_observability(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_gateway_request_observability(p_workspace_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'request', to_jsonb(gateway_request),
    'fact', case
      when fact.request_event_id is null then null
      else to_jsonb(fact)
    end,
    'attempts', coalesce((
      select jsonb_agg(to_jsonb(attempt) order by attempt.attempt_number)
      from public.v2_request_attempts attempt
      where attempt.request_event_id = fact.request_event_id
    ), '[]'::jsonb),
    'routing_decisions', coalesce((
      select jsonb_agg(to_jsonb(decision) order by decision.decision_order)
      from public.v2_request_routing_decisions decision
      where decision.request_event_id = fact.request_event_id
    ), '[]'::jsonb),
    'usage_meters', coalesce((
      select jsonb_agg(to_jsonb(usage) order by usage.sequence, usage.meter_key)
      from public.v2_request_usage usage
      where usage.request_event_id = fact.request_event_id
    ), '[]'::jsonb),
    'pricing_lines', coalesce((
      select jsonb_agg(to_jsonb(line) order by line.created_at, line.pricing_line_id)
      from public.v2_request_pricing_lines line
      where line.request_event_id = fact.request_event_id
    ), '[]'::jsonb),
    'artifacts', coalesce((
      select jsonb_agg(to_jsonb(artifact) order by artifact.created_at, artifact.artifact_id)
      from public.v2_request_artifacts artifact
      where artifact.request_event_id = fact.request_event_id
    ), '[]'::jsonb),
    'feedback', coalesce((
      select jsonb_agg(to_jsonb(feedback) order by feedback.created_at, feedback.feedback_id)
      from public.v2_request_feedback feedback
      where feedback.request_event_id = fact.request_event_id
    ), '[]'::jsonb)
  )
  from public.gateway_requests gateway_request
  left join public.v2_request_facts fact
    on fact.gateway_request_id = gateway_request.id
   and fact.gateway_request_created_at = gateway_request.created_at
  where gateway_request.workspace_id = p_workspace_id
    and gateway_request.request_id = p_request_id
  order by gateway_request.created_at desc
  limit 1;
$$;


--
-- Name: FUNCTION get_gateway_request_observability(p_workspace_id uuid, p_request_id text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_gateway_request_observability(p_workspace_id uuid, p_request_id text) IS 'Returns one authoritative gateway request enriched with normalized, metadata-only observability extensions.';


--
-- Name: get_gateway_sessions_rollup(uuid, timestamp with time zone, timestamp with time zone, integer, integer, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_gateway_sessions_rollup(p_team uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0, p_app_id uuid DEFAULT NULL::uuid, p_model_id text DEFAULT NULL::text, p_provider text DEFAULT NULL::text) RETURNS TABLE(session_id text, request_count bigint, total_cost_nanos numeric, total_cost_usd numeric, first_request_at timestamp with time zone, last_request_at timestamp with time zone, app_ids uuid[], model_ids text[], provider_ids text[], end_user_ids text[])
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with filtered as (
    select gr.*
    from private.v2_rpc_gateway_requests_compat gr
    where gr.workspace_id = p_team
      and gr.created_at >= p_from
      and gr.created_at <= p_to
      and gr.session_id is not null
      and length(trim(gr.session_id)) > 0
      and (p_app_id is null or gr.app_id = p_app_id)
      and (p_model_id is null or gr.model_id = p_model_id)
      and (p_provider is null or gr.provider = p_provider)
  ),
  grouped as (
    select
      gr.session_id,
      count(*)::bigint as request_count,
      coalesce(sum(gr.cost_nanos::numeric), 0) as total_cost_nanos,
      min(gr.created_at) as first_request_at,
      max(gr.created_at) as last_request_at,
      array_remove(array_agg(distinct gr.app_id), null) as app_ids,
      array_remove(array_agg(distinct gr.model_id), null) as model_ids,
      array_remove(array_agg(distinct gr.provider), null) as provider_ids,
      array_remove(array_agg(distinct gr.end_user_id), null) as end_user_ids
    from filtered gr
    group by gr.session_id
  )
  select
    g.session_id,
    g.request_count,
    g.total_cost_nanos,
    g.total_cost_nanos / 1e9 as total_cost_usd,
    g.first_request_at,
    g.last_request_at,
    g.app_ids,
    g.model_ids,
    g.provider_ids,
    g.end_user_ids
  from grouped g
  order by g.last_request_at desc
  limit greatest(1, least(coalesce(p_limit, 100), 500))
  offset greatest(0, coalesce(p_offset, 0));
$$;


--
-- Name: FUNCTION get_gateway_sessions_rollup(p_team uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer, p_app_id uuid, p_model_id text, p_provider text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_gateway_sessions_rollup(p_team uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_offset integer, p_app_id uuid, p_model_id text, p_provider text) IS 'Workspace-scoped session rollup across gateway_requests with totals and distinct app/model/provider sets.';


--
-- Name: get_model_gateway_overview(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_model_gateway_overview(p_model_id text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
with
-- 1) Build the set of gateway model_id values we consider "this model"
model_ids as (
  select p_model_id as model_id
  union
  select pm.provider_id || '/' || pm.api_model_id
  from private.v2_rpc_routes_compat pm
  where pm.internal_model_id = p_model_id
),

-- 2) Anchor times in UTC as timestamptz (safe to compare with created_at timestamptz)
anchors as (
  select
    (date_trunc('hour', now() at time zone 'utc') at time zone 'utc') as now_hour,
    (select release_date
     from private.v2_rpc_models_compat
     where model_id = p_model_id
     limit 1) as release_date
),
windows as (
  select
    now_hour,
    now_hour - interval '24 hours'  as last24_start,
    now_hour - interval '48 hours'  as prev24_start,
    now_hour - interval '120 hours' as last5d_start
  from anchors
),

-- 3) Requests for the last 5d (used by 5d + 24h calcs)
requests_5d as (
  select
    gr.created_at,
    gr.success as success_bool,
    gr.latency_ms,
    gr.throughput,
    gr.generation_ms,
    gr.provider,
    gr.usage
  from private.v2_rpc_gateway_requests_compat gr
  join model_ids mi on mi.model_id = gr.model_id
  join windows w on gr.created_at >= w.last5d_start
              and gr.created_at <  w.now_hour
),

requests_last24 as (
  select r.*
  from requests_5d r, windows w
  where r.created_at >= w.last24_start
    and r.created_at <  w.now_hour
),
requests_prev24 as (
  select r.*
  from requests_5d r, windows w
  where r.created_at >= w.prev24_start
    and r.created_at <  w.last24_start
),

-- 4) 24h aggregates
last_24h as (
  select jsonb_build_object(
    'avg_throughput',
      case when count(*) filter (where throughput is not null) > 0
        then percentile_cont(0.5) within group (order by throughput) filter (where throughput is not null)
        else null end,
    'avg_latency_ms',
      case when count(*) filter (where latency_ms is not null) > 0
        then percentile_cont(0.5) within group (order by latency_ms) filter (where latency_ms is not null)
        else null end,
    'avg_generation_ms',
      case when count(*) filter (where generation_ms is not null) > 0
        then percentile_cont(0.5) within group (order by generation_ms) filter (where generation_ms is not null)
        else null end,
    'uptime_pct',
      case when count(*) > 0
        then (count(*) filter (where success_bool) * 100.0 / count(*))
        else null end,
    'total_requests', count(*),
    'successful_requests', count(*) filter (where success_bool)
  ) as value
  from requests_last24
),
prev_24h as (
  select jsonb_build_object(
    'avg_throughput',
      case when count(*) filter (where throughput is not null) > 0
        then percentile_cont(0.5) within group (order by throughput) filter (where throughput is not null)
        else null end,
    'avg_latency_ms',
      case when count(*) filter (where latency_ms is not null) > 0
        then percentile_cont(0.5) within group (order by latency_ms) filter (where latency_ms is not null)
        else null end,
    'avg_generation_ms',
      case when count(*) filter (where generation_ms is not null) > 0
        then percentile_cont(0.5) within group (order by generation_ms) filter (where generation_ms is not null)
        else null end,
    'uptime_pct',
      case when count(*) > 0
        then (count(*) filter (where success_bool) * 100.0 / count(*))
        else null end,
    'total_requests', count(*),
    'successful_requests', count(*) filter (where success_bool)
  ) as value
  from requests_prev24
),

hourly_24h as (
  select coalesce(jsonb_agg(bucket_json order by bucket_start), '[]'::jsonb) as value
  from (
    select
      s.bucket_start,
      jsonb_build_object(
        'bucket', s.bucket_start,
        'avg_throughput',
          case when count(r.*) filter (where r.throughput is not null) > 0
            then percentile_cont(0.5) within group (order by r.throughput) filter (where r.throughput is not null)
            else null end,
        'avg_latency_ms',
          case when count(r.*) filter (where r.latency_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.latency_ms) filter (where r.latency_ms is not null)
            else null end,
        'avg_generation_ms',
          case when count(r.*) filter (where r.generation_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.generation_ms) filter (where r.generation_ms is not null)
            else null end,
        'requests', count(r.*),
        'success_pct',
          case when count(r.*) > 0
            then (count(*) filter (where r.success_bool) * 100.0 / count(r.*))
            else null end,
        'worst_provider_success_pct',
          (
            select min(pct)
            from (
              select
                case when count(*) > 0
                  then (count(*) filter (where r2.success_bool) * 100.0 / count(*))
                  else null end as pct
              from requests_last24 r2
              where r2.created_at >= s.bucket_start
                and r2.created_at <  s.bucket_start + interval '1 hour'
              group by r2.provider
            ) provider_stats
          )
      ) as bucket_json
    from (
      select generate_series(
        w.last24_start,
        w.now_hour - interval '1 hour',
        interval '1 hour'
      ) as bucket_start
      from windows w
    ) s
    left join requests_last24 r
      on r.created_at >= s.bucket_start
     and r.created_at <  s.bucket_start + interval '1 hour'
    group by s.bucket_start
  ) buckets
),

provider_uptime_24h as (
  select coalesce(jsonb_agg(provider_json order by requests desc), '[]'::jsonb) as value
  from (
    select
      r.provider,
      count(*) as requests,
      jsonb_build_object(
        'provider', r.provider,
        'provider_name', coalesce(p.api_provider_name, r.provider),
        'avg_throughput',
          case when count(*) filter (where r.throughput is not null) > 0
            then percentile_cont(0.5) within group (order by r.throughput) filter (where r.throughput is not null)
            else null end,
        'avg_latency_ms',
          case when count(*) filter (where r.latency_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.latency_ms) filter (where r.latency_ms is not null)
            else null end,
        'avg_generation_ms',
          case when count(*) filter (where r.generation_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.generation_ms) filter (where r.generation_ms is not null)
            else null end,
        'requests', count(*),
        'uptime_pct',
          case when count(*) > 0
            then (count(*) filter (where r.success_bool) * 100.0 / count(*))
            else null end,
        'uptime_buckets',
          (
            select coalesce(jsonb_agg(bucket_json order by bucket_end asc), '[]'::jsonb)
            from (
              select
                bucket_end,
                jsonb_build_object(
                  'start', bucket_end - interval '6 hours',
                  'end', bucket_end,
                  'success_pct',
                    case when count(pr.*) > 0
                      then (count(*) filter (where pr.success_bool) * 100.0 / count(pr.*))
                      else null end
                ) as bucket_json
              from (
                select generate_series(
                  w.last24_start + interval '6 hours',
                  w.now_hour,
                  interval '6 hours'
                ) as bucket_end
                from windows w
              ) buckets
              left join requests_last24 pr
                on pr.provider = r.provider
               and pr.created_at >  buckets.bucket_end - interval '6 hours'
               and pr.created_at <= buckets.bucket_end
              group by bucket_end
            ) per_bucket
          )
      ) as provider_json
    from requests_last24 r
    left join private.v2_rpc_providers_compat p on p.api_provider_id = r.provider
    group by r.provider, p.api_provider_name
  ) provider_rows
),

-- 5) 5d aggregates
hourly_5d as (
  select coalesce(jsonb_agg(bucket_json order by bucket_start), '[]'::jsonb) as value
  from (
    select
      s.bucket_start,
      jsonb_build_object(
        'bucket', s.bucket_start,
        'avg_throughput',
          case when count(r.*) filter (where r.throughput is not null) > 0
            then percentile_cont(0.5) within group (order by r.throughput) filter (where r.throughput is not null)
            else null end,
        'avg_latency_ms',
          case when count(r.*) filter (where r.latency_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.latency_ms) filter (where r.latency_ms is not null)
            else null end,
        'avg_generation_ms',
          case when count(r.*) filter (where r.generation_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.generation_ms) filter (where r.generation_ms is not null)
            else null end,
        'requests', count(r.*),
        'success_pct',
          case when count(r.*) > 0
            then (count(*) filter (where r.success_bool) * 100.0 / count(r.*))
            else null end
      ) as bucket_json
    from (
      select generate_series(
        w.last5d_start,
        w.now_hour - interval '1 hour',
        interval '1 hour'
      ) as bucket_start
      from windows w
    ) s
    left join requests_5d r
      on r.created_at >= s.bucket_start
     and r.created_at <  s.bucket_start + interval '1 hour'
    group by s.bucket_start
  ) buckets
),
time_of_day_5d as (
  select coalesce(jsonb_agg(hour_json order by hour), '[]'::jsonb) as value
  from (
    select
      hour,
      jsonb_build_object(
        'hour', hour,
        'avg_throughput',
          case when count(*) filter (where throughput is not null) > 0
            then percentile_cont(0.5) within group (order by throughput) filter (where throughput is not null)
            else null end,
        'avg_latency_ms',
          case when count(*) filter (where latency_ms is not null) > 0
            then percentile_cont(0.5) within group (order by latency_ms) filter (where latency_ms is not null)
            else null end,
        'avg_generation_ms',
          case when count(*) filter (where generation_ms is not null) > 0
            then percentile_cont(0.5) within group (order by generation_ms) filter (where generation_ms is not null)
            else null end,
        'sample_count', count(*)
      ) as hour_json
    from (
      select
        extract(hour from (created_at at time zone 'utc'))::int as hour,
        throughput,
        latency_ms,
        generation_ms
      from requests_5d
    ) r
    group by hour
  ) hours
),

-- 6) Cumulative token totals since release date (or from first seen request)
token_totals as (
  select
    coalesce(
      (select (release_date::timestamp at time zone 'utc') from anchors),
      min(gr.created_at)
    ) as release_at,
    coalesce(
      sum(
        coalesce(
          nullif((gr.usage ->> 'total_tokens')::numeric, 0),
          coalesce((gr.usage ->> 'input_tokens')::numeric, 0)
          + coalesce((gr.usage ->> 'output_tokens')::numeric, 0)
        )
      ),
      0
    ) as total_tokens
  from private.v2_rpc_gateway_requests_compat gr
  join model_ids mi on mi.model_id = gr.model_id
  where (select release_date from anchors) is null
     or gr.created_at >= (select (release_date::timestamp at time zone 'utc') from anchors)
)

select jsonb_build_object(
  'last_24h',              (select value from last_24h),
  'prev_24h',              (select value from prev_24h),
  'hourly_24h',            (select value from hourly_24h),
  'provider_uptime_24h',   (select value from provider_uptime_24h),
  'hourly_5d',             (select value from hourly_5d),
  'time_of_day_5d',        (select value from time_of_day_5d),
  'cumulative_tokens',     jsonb_build_object(
                             'release_date', (select release_date from anchors),
                             'total_tokens', (select total_tokens from token_totals)
                           )
);
$$;


--
-- Name: get_model_gateway_overview(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_model_gateway_overview(p_internal_model_id text, p_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
with
-- Clamp hours to something sane
args as (
  select greatest(1, least(coalesce(p_hours, 24), 720))::int as hours
),

-- UTC anchor as timestamptz (safe comparisons vs created_at timestamptz)
anchors as (
  select
    (date_trunc('hour', now() at time zone 'utc') at time zone 'utc') as now_hour
),

windows as (
  select
    a.now_hour,
    a.now_hour - make_interval(hours => (select hours from args)) as window_start
  from anchors a
),

-- Build the set of gateway model_id values we should include
model_ids as (
  select p_internal_model_id as model_id

  union

  select pm.provider_id || '/' || pm.api_model_id
  from private.v2_rpc_routes_compat pm
  where pm.internal_model_id = p_internal_model_id

  -- Optional: honour effective windows if you actually use them
  -- and (pm.effective_from is null or pm.effective_from <= (select now_hour from anchors))
  -- and (pm.effective_to   is null or pm.effective_to   >  (select now_hour from anchors))
),

-- Pull only the rows we need (windowed)
requests as (
  select
    gr.created_at,
    gr.success as success_bool,
    gr.latency_ms,
    gr.throughput,
    gr.generation_ms,
    gr.provider,
    gr.usage,
    gr.model_id
  from private.v2_rpc_gateway_requests_compat gr
  join model_ids mi on mi.model_id = gr.model_id
  join windows w on gr.created_at >= w.window_start
              and gr.created_at <  w.now_hour
),

summary as (
  select jsonb_build_object(
    'hours', (select hours from args),
    'window_start', (select window_start from windows),
    'window_end', (select now_hour from windows),

    'median_throughput',
      case when count(*) filter (where throughput is not null) > 0
        then percentile_cont(0.5) within group (order by throughput) filter (where throughput is not null)
        else null end,

    'median_latency_ms',
      case when count(*) filter (where latency_ms is not null) > 0
        then percentile_cont(0.5) within group (order by latency_ms) filter (where latency_ms is not null)
        else null end,

    'median_generation_ms',
      case when count(*) filter (where generation_ms is not null) > 0
        then percentile_cont(0.5) within group (order by generation_ms) filter (where generation_ms is not null)
        else null end,

    'uptime_pct',
      case when count(*) > 0
        then (count(*) filter (where success_bool) * 100.0 / count(*))
        else null end,

    'total_requests', count(*),
    'successful_requests', count(*) filter (where success_bool)
  ) as value
  from requests
),

hourly as (
  select coalesce(jsonb_agg(bucket_json order by bucket_start), '[]'::jsonb) as value
  from (
    select
      s.bucket_start,
      jsonb_build_object(
        'bucket', s.bucket_start,
        'requests', count(r.*),
        'success_pct',
          case when count(r.*) > 0
            then (count(*) filter (where r.success_bool) * 100.0 / count(r.*))
            else null end,

        'median_throughput',
          case when count(r.*) filter (where r.throughput is not null) > 0
            then percentile_cont(0.5) within group (order by r.throughput) filter (where r.throughput is not null)
            else null end,

        'median_latency_ms',
          case when count(r.*) filter (where r.latency_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.latency_ms) filter (where r.latency_ms is not null)
            else null end,

        'median_generation_ms',
          case when count(r.*) filter (where r.generation_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.generation_ms) filter (where r.generation_ms is not null)
            else null end
      ) as bucket_json
    from (
      select generate_series(
        (select window_start from windows),
        (select now_hour from windows) - interval '1 hour',
        interval '1 hour'
      ) as bucket_start
    ) s
    left join requests r
      on r.created_at >= s.bucket_start
     and r.created_at <  s.bucket_start + interval '1 hour'
    group by s.bucket_start
  ) buckets
),

provider_breakdown as (
  select coalesce(jsonb_agg(provider_json order by requests desc), '[]'::jsonb) as value
  from (
    select
      r.provider,
      count(*) as requests,
      jsonb_build_object(
        'provider', r.provider,
        'requests', count(*),
        'uptime_pct',
          case when count(*) > 0
            then (count(*) filter (where r.success_bool) * 100.0 / count(*))
            else null end,

        'median_throughput',
          case when count(*) filter (where r.throughput is not null) > 0
            then percentile_cont(0.5) within group (order by r.throughput) filter (where r.throughput is not null)
            else null end,

        'median_latency_ms',
          case when count(*) filter (where r.latency_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.latency_ms) filter (where r.latency_ms is not null)
            else null end,

        'median_generation_ms',
          case when count(*) filter (where r.generation_ms is not null) > 0
            then percentile_cont(0.5) within group (order by r.generation_ms) filter (where r.generation_ms is not null)
            else null end
      ) as provider_json
    from requests r
    group by r.provider
  ) rows
),

tokens as (
  select jsonb_build_object(
    'total_tokens',
      coalesce(sum(
        coalesce(
          nullif((usage->>'total_tokens')::numeric, 0),
          coalesce((usage->>'input_tokens')::numeric, 0)
          + coalesce((usage->>'output_tokens')::numeric, 0)
        )
      ), 0)
  ) as value
  from requests
)

select jsonb_build_object(
  'model_ids', (select coalesce(jsonb_agg(model_id), '[]'::jsonb) from model_ids),
  'summary', (select value from summary),
  'hourly', (select value from hourly),
  'providers', (select value from provider_breakdown),
  'tokens', (select value from tokens)
);
$$;


--
-- Name: get_model_performance_overview(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_model_performance_overview(p_model_id text) RETURNS TABLE(last_24h jsonb, prev_24h jsonb, hourly_24h jsonb, provider_uptime_24h jsonb, hourly_5d jsonb, time_of_day_5d jsonb, cumulative_tokens jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$with params as (
    select p_model_id as model_id
),
anchors as (
    select
        date_trunc('hour', now() at time zone 'utc') as now_hour,
        (select release_date from private.v2_rpc_models_compat where model_id = p_model_id limit 1) as release_date
),
windows as (
    select
        now_hour,
        now_hour - interval '24 hours' as last24_start,
        now_hour - interval '48 hours' as prev24_start,
        now_hour - interval '120 hours' as last5d_start
    from anchors
),
requests_all as (
    select
        gr.created_at,
        gr.success::boolean as success_bool,
        gr.latency_ms,
        gr.throughput,
        gr.generation_ms,
        gr.provider
    from private.v2_rpc_gateway_requests_compat gr
    left join private.v2_rpc_routes_compat pm on pm.internal_model_id = (select model_id from params)
    where gr.model_id = (select model_id from params)
       or gr.model_id = pm.api_model_id
),
requests_last24 as (
    select * from requests_all, windows w
    where created_at >= w.last24_start and created_at < w.now_hour
),
requests_prev24 as (
    select * from requests_all, windows w
    where created_at >= w.prev24_start and created_at < w.last24_start
),
requests_5d as (
    select * from requests_all, windows w
    where created_at >= w.last5d_start and created_at < w.now_hour
),
median_or_null as (
    select 1 as dummy
),
last_24h as (
    select jsonb_build_object(
        'avg_throughput', case when count(*) filter (where throughput is not null) > 0
            then percentile_cont(0.5) within group (order by throughput) filter (where throughput is not null)
            else null end,
        'avg_latency_ms', case when count(*) filter (where latency_ms is not null) > 0
            then percentile_cont(0.5) within group (order by latency_ms) filter (where latency_ms is not null)
            else null end,
        'avg_generation_ms', case when count(*) filter (where generation_ms is not null) > 0
            then percentile_cont(0.5) within group (order by generation_ms) filter (where generation_ms is not null)
            else null end,
        'uptime_pct', case when count(*) > 0 then (count(*) filter (where success_bool) * 100.0 / count(*)) else null end,
        'total_requests', count(*),
        'successful_requests', count(*) filter (where success_bool)
    ) as value
    from requests_last24
),
prev_24h as (
    select jsonb_build_object(
        'avg_throughput', case when count(*) filter (where throughput is not null) > 0
            then percentile_cont(0.5) within group (order by throughput) filter (where throughput is not null)
            else null end,
        'avg_latency_ms', case when count(*) filter (where latency_ms is not null) > 0
            then percentile_cont(0.5) within group (order by latency_ms) filter (where latency_ms is not null)
            else null end,
        'avg_generation_ms', case when count(*) filter (where generation_ms is not null) > 0
            then percentile_cont(0.5) within group (order by generation_ms) filter (where generation_ms is not null)
            else null end,
        'uptime_pct', case when count(*) > 0 then (count(*) filter (where success_bool) * 100.0 / count(*)) else null end,
        'total_requests', count(*),
        'successful_requests', count(*) filter (where success_bool)
    ) as value
    from requests_prev24
),
hourly_24h as (
    select coalesce(jsonb_agg(bucket_json order by bucket_start), '[]'::jsonb) as value
    from (
        select
            s.bucket_start,
            jsonb_build_object(
                'bucket', s.bucket_start,
                'avg_throughput', case when count(r.*) filter (where r.throughput is not null) > 0
                    then percentile_cont(0.5) within group (order by r.throughput) filter (where r.throughput is not null)
                    else null end,
                'avg_latency_ms', case when count(r.*) filter (where r.latency_ms is not null) > 0
                    then percentile_cont(0.5) within group (order by r.latency_ms) filter (where r.latency_ms is not null)
                    else null end,
                'avg_generation_ms', case when count(r.*) filter (where r.generation_ms is not null) > 0
                    then percentile_cont(0.5) within group (order by r.generation_ms) filter (where r.generation_ms is not null)
                    else null end,
                'requests', count(r.*),
                'success_pct', case when count(r.*) > 0 then (count(*) filter (where r.success_bool) * 100.0 / count(r.*)) else null end,
                'worst_provider_success_pct',
                    (
                        select min(pct) from (
                            select case when count(*) > 0 then (count(*) filter (where r2.success_bool) * 100.0 / count(*)) else null end as pct
                            from requests_last24 r2
                            where r2.created_at >= s.bucket_start
                              and r2.created_at < s.bucket_start + interval '1 hour'
                            group by r2.provider
                        ) provider_stats
                    )
            ) as bucket_json
        from (
            select generate_series(w.last24_start, w.now_hour, interval '1 hour') as bucket_start
            from windows w
        ) s
        left join requests_last24 r
            on r.created_at >= s.bucket_start
           and r.created_at < s.bucket_start + interval '1 hour'
        group by s.bucket_start
    ) buckets
),
provider_uptime_24h as (
    select coalesce(jsonb_agg(provider_json order by requests desc), '[]'::jsonb) as value
    from (
        select
            r.provider,
            count(*) as requests,
            jsonb_build_object(
                'provider', r.provider,
                'provider_name', coalesce(p.api_provider_name, r.provider),
                'avg_throughput', case when count(*) filter (where r.throughput is not null) > 0
                    then percentile_cont(0.5) within group (order by r.throughput) filter (where r.throughput is not null)
                    else null end,
                'avg_latency_ms', case when count(*) filter (where r.latency_ms is not null) > 0
                    then percentile_cont(0.5) within group (order by r.latency_ms) filter (where r.latency_ms is not null)
                    else null end,
                'avg_generation_ms', case when count(*) filter (where r.generation_ms is not null) > 0
                    then percentile_cont(0.5) within group (order by r.generation_ms) filter (where r.generation_ms is not null)
                    else null end,
                'requests', count(*),
                'uptime_pct', case when count(*) > 0 then (count(*) filter (where r.success_bool) * 100.0 / count(*)) else null end,
                'uptime_buckets',
                    (
                        select jsonb_agg(bucket_json order by bucket_end asc)
                        from (
                            select
                                bucket_end,
                                jsonb_build_object(
                                    'start', bucket_end - interval '6 hours',
                                    'end', bucket_end,
                                    'success_pct', case when count(pr.*) > 0 then (count(*) filter (where pr.success_bool) * 100.0 / count(pr.*)) else null end
                                ) as bucket_json
                            from (
                                select generate_series(
                                    w.last24_start,
                                    w.now_hour,
                                    interval '6 hours'
                                ) as bucket_end
                                from windows w
                            ) buckets
                            left join requests_last24 pr
                                on pr.provider = r.provider
                               and pr.created_at > buckets.bucket_end - interval '6 hours'
                               and pr.created_at <= buckets.bucket_end
                            group by bucket_end
                        ) per_bucket
                    )
            ) as provider_json
        from requests_last24 r
        left join private.v2_rpc_providers_compat p on p.api_provider_id = r.provider
        group by r.provider, p.api_provider_name
    ) provider_rows
),
hourly_5d as (
    select coalesce(jsonb_agg(bucket_json order by bucket_start), '[]'::jsonb) as value
    from (
        select
            s.bucket_start,
            jsonb_build_object(
                'bucket', s.bucket_start,
                'avg_throughput', case when count(r.*) filter (where r.throughput is not null) > 0
                    then percentile_cont(0.5) within group (order by r.throughput) filter (where r.throughput is not null)
                    else null end,
                'avg_latency_ms', case when count(r.*) filter (where r.latency_ms is not null) > 0
                    then percentile_cont(0.5) within group (order by r.latency_ms) filter (where r.latency_ms is not null)
                    else null end,
                'avg_generation_ms', case when count(r.*) filter (where r.generation_ms is not null) > 0
                    then percentile_cont(0.5) within group (order by r.generation_ms) filter (where r.generation_ms is not null)
                    else null end,
                'requests', count(r.*),
                'success_pct', case when count(r.*) > 0 then (count(*) filter (where r.success_bool) * 100.0 / count(r.*)) else null end
            ) as bucket_json
        from (
            select generate_series(w.last5d_start, w.now_hour, interval '1 hour') as bucket_start
            from windows w
        ) s
        left join requests_5d r
            on r.created_at >= s.bucket_start
           and r.created_at < s.bucket_start + interval '1 hour'
        group by s.bucket_start
    ) buckets
),
time_of_day_5d as (
    select coalesce(jsonb_agg(hour_json order by hour), '[]'::jsonb) as value
    from (
        select
            hour,
            jsonb_build_object(
                'hour', hour,
                'avg_throughput', case when count(*) filter (where throughput is not null) > 0
                    then percentile_cont(0.5) within group (order by throughput) filter (where throughput is not null)
                    else null end,
                'avg_latency_ms', case when count(*) filter (where latency_ms is not null) > 0
                    then percentile_cont(0.5) within group (order by latency_ms) filter (where latency_ms is not null)
                    else null end,
                'avg_generation_ms', case when count(*) filter (where generation_ms is not null) > 0
                    then percentile_cont(0.5) within group (order by generation_ms) filter (where generation_ms is not null)
                    else null end,
                'sample_count', count(*)
            ) as hour_json
        from (
            select
                extract(hour from created_at) as hour,
                throughput,
                latency_ms,
                generation_ms
            from requests_5d
        ) r
        group by hour
    ) hours
),
token_totals as (
    select
        coalesce(max(a.release_date), min(r_req.created_at)) as release_date,
        coalesce(
            sum(
                coalesce((r_req.usage ->> 'total_tokens')::numeric, 0)
                + coalesce((r_req.usage ->> 'input_tokens')::numeric, 0)
                + coalesce((r_req.usage ->> 'output_tokens')::numeric, 0)
            ),
            0
        ) as total_tokens
    from anchors a
    cross join params p
    left join private.v2_rpc_gateway_requests_compat r_req on true
    left join private.v2_rpc_routes_compat pm on pm.internal_model_id = p.model_id
    where r_req.model_id = p.model_id
       or r_req.model_id = pm.api_model_id
       and (a.release_date is null or r_req.created_at >= a.release_date)
)
select
    (select value from last_24h) as last_24h,
    (select value from prev_24h) as prev_24h,
    (select value from hourly_24h) as hourly_24h,
    (select value from provider_uptime_24h) as provider_uptime_24h,
    (select value from hourly_5d) as hourly_5d,
    (select value from time_of_day_5d) as time_of_day_5d,
    jsonb_build_object(
        'release_date', (select release_date from anchors),
        'total_tokens', (select total_tokens from token_totals)
    ) as cumulative_tokens;$$;


--
-- Name: FUNCTION get_model_performance_overview(p_model_id text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_model_performance_overview(p_model_id text) IS 'Aggregates performance, uptime (hourly), provider uptime, 5d hourly medians, and cumulative tokens in one call. Medians only.';


--
-- Name: get_model_provider_health_metrics(text[], text[], integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_model_provider_health_metrics(p_model_ids text[], p_provider_ids text[] DEFAULT NULL::text[], p_window_days integer DEFAULT 30, p_bucket_hours integer DEFAULT 24) RETURNS TABLE(provider_id text, provider_name text, requests bigint, requests_30m bigint, success_requests bigint, failed_requests bigint, neutral_requests bigint, rate_limited_requests bigint, health_requests bigint, health_success_requests bigint, uptime_pct numeric, request_success_pct numeric, avg_latency_ms_30m numeric, avg_throughput_30m numeric, avg_latency_ms numeric, p50_latency_ms numeric, p95_latency_ms numeric, avg_generation_ms numeric, avg_throughput numeric, total_tokens bigint, input_tokens_1h bigint, output_tokens_1h bigint, cached_read_tokens_1h bigint, input_tokens bigint, output_tokens bigint, finish_reason_counts jsonb, error_code_counts jsonb, buckets jsonb, last_request_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with params as (
    select
      greatest(1, least(coalesce(p_window_days, 30), 90))::integer as window_days,
      greatest(1, least(coalesce(p_bucket_hours, 24), 24 * 7))::integer as bucket_hours,
      now() as now_ts
  ),
  provider_filter as (
    select distinct nullif(btrim(input.provider_id), '') as provider_id
    from unnest(coalesce(p_provider_ids, array[]::text[])) as input(provider_id)
    where nullif(btrim(input.provider_id), '') is not null
  ),
  model_filter as (
    select distinct nullif(btrim(input.model_id), '') as model_id
    from unnest(coalesce(p_model_ids, array[]::text[])) as input(model_id)
    where nullif(btrim(input.model_id), '') is not null
  ),
  base as (
    select
      coalesce(nullif(gr.provider, ''), 'unknown') as provider_id,
      gr.created_at,
      gr.success,
      gr.status_code,
      lower(coalesce(gr.error_code, '')) as error_code,
      lower(nullif(btrim(coalesce(gr.finish_reason, '')), '')) as finish_reason,
      gr.latency_ms,
      gr.generation_ms,
      gr.throughput,
      public.gateway_usage_total_tokens(gr.usage)::bigint as total_tokens,
      coalesce(
        public.gateway_usage_numeric_field(
          gr.usage,
          'input_tokens',
          'prompt_tokens',
          'inputTokens',
          'promptTokens',
          'total_input_tokens',
          'totalInputTokens'
        ),
        0
      )::bigint as input_tokens,
      coalesce(
        public.gateway_usage_numeric_field(
          gr.usage,
          'output_tokens',
          'completion_tokens',
          'generated_tokens',
          'response_tokens',
          'outputTokens',
          'completionTokens',
          'total_output_tokens',
          'totalOutputTokens'
        ),
        0
      )::bigint as output_tokens
      ,
      coalesce(
        public.gateway_usage_numeric_field(
          gr.usage,
          'cached_read_text_tokens',
          'cached_read_image_tokens',
          'cached_read_audio_tokens',
          'cached_read_video_tokens',
          'cached_read_tokens',
          'cache_read_input_tokens'
        ),
        0
      )::bigint as cached_read_tokens
    from private.v2_rpc_gateway_requests_compat gr
    join params p on true
    where gr.created_at >= p.now_ts - make_interval(days => p.window_days)
      and exists (
        select 1
        from model_filter mf
        where mf.model_id in (
          nullif(gr.model_id, ''),
          nullif(gr.canonical_model_id, ''),
          nullif(gr.requested_model_id, ''),
          nullif(gr.routed_model_id, ''),
          public.resolve_public_model_id(gr.model_id, gr.provider)
        )
      )
      and gr.provider is not null
      and gr.provider <> ''
      and (
        p_provider_ids is null
        or exists (
          select 1
          from provider_filter pf
          where pf.provider_id = gr.provider
        )
      )
  ),
  classified as (
    select
      b.*,
      case
        when b.success is true then 'success'
        when b.status_code = 429
          or b.error_code like '%rate limit%'
          or b.error_code like '%rate_limit%'
          or b.error_code like '%ratelimit%'
          or b.error_code like '%too many requests%'
          or b.error_code like '%quota exceeded%'
        then 'neutral'
        when b.error_code like '%abort%'
          or b.error_code like '%cancel%'
          or b.error_code like '%client_closed%'
        then 'neutral'
        else 'failure'
      end as health_outcome,
      case
        when b.status_code = 429
          or b.error_code like '%rate limit%'
          or b.error_code like '%rate_limit%'
          or b.error_code like '%ratelimit%'
          or b.error_code like '%too many requests%'
          or b.error_code like '%quota exceeded%'
        then true
        else false
      end as is_rate_limited
    from base b
  ),
  aggregates as (
    select
      c.provider_id,
      count(*)::bigint as requests,
      count(*) filter (where c.created_at >= (select now_ts from params) - interval '30 minutes')::bigint as requests_30m,
      count(*) filter (where c.success is true)::bigint as success_requests,
      count(*) filter (where c.health_outcome = 'failure')::bigint as failed_requests,
      count(*) filter (where c.health_outcome = 'neutral')::bigint as neutral_requests,
      count(*) filter (where c.is_rate_limited)::bigint as rate_limited_requests,
      count(*) filter (where c.health_outcome <> 'neutral')::bigint as health_requests,
      count(*) filter (where c.health_outcome = 'success')::bigint as health_success_requests,
      avg(c.latency_ms) filter (
        where c.success is true
          and c.latency_ms is not null
          and c.created_at >= (select now_ts from params) - interval '30 minutes'
      )::numeric as avg_latency_ms_30m,
      avg(c.throughput) filter (
        where c.success is true
          and c.throughput is not null
          and c.created_at >= (select now_ts from params) - interval '30 minutes'
      )::numeric as avg_throughput_30m,
      avg(c.latency_ms) filter (where c.success is true and c.latency_ms is not null)::numeric as avg_latency_ms,
      percentile_cont(0.5) within group (order by c.latency_ms)
        filter (where c.success is true and c.latency_ms is not null)::numeric as p50_latency_ms,
      percentile_cont(0.95) within group (order by c.latency_ms)
        filter (where c.success is true and c.latency_ms is not null)::numeric as p95_latency_ms,
      avg(c.generation_ms) filter (where c.success is true and c.generation_ms is not null)::numeric as avg_generation_ms,
      avg(c.throughput) filter (where c.success is true and c.throughput is not null)::numeric as avg_throughput,
      coalesce(sum(c.total_tokens), 0)::bigint as total_tokens,
      coalesce(sum(c.input_tokens) filter (where c.created_at >= (select now_ts from params) - interval '1 hour'), 0)::bigint as input_tokens_1h,
      coalesce(sum(c.output_tokens) filter (where c.created_at >= (select now_ts from params) - interval '1 hour'), 0)::bigint as output_tokens_1h,
      coalesce(sum(c.cached_read_tokens) filter (where c.created_at >= (select now_ts from params) - interval '1 hour'), 0)::bigint as cached_read_tokens_1h,
      coalesce(sum(c.input_tokens), 0)::bigint as input_tokens,
      coalesce(sum(c.output_tokens), 0)::bigint as output_tokens,
      max(c.created_at) as last_request_at
    from classified c
    group by c.provider_id
  ),
  finish_reasons as (
    select
      x.provider_id,
      jsonb_object_agg(x.finish_reason, x.reason_count order by x.reason_count desc, x.finish_reason) as finish_reason_counts
    from (
      select
        c.provider_id,
        c.finish_reason,
        count(*)::bigint as reason_count
      from classified c
      where c.success is true
        and c.finish_reason is not null
        and c.finish_reason <> ''
        and c.finish_reason <> 'error'
      group by c.provider_id, c.finish_reason
    ) x
    group by x.provider_id
  ),
  error_codes as (
    select
      x.provider_id,
      jsonb_object_agg(x.error_code, x.error_count order by x.error_count desc, x.error_code) as error_code_counts
    from (
      select
        c.provider_id,
        coalesce(nullif(c.error_code, ''), 'unknown') as error_code,
        count(*)::bigint as error_count
      from classified c
      where c.health_outcome = 'failure'
      group by c.provider_id, coalesce(nullif(c.error_code, ''), 'unknown')
    ) x
    group by x.provider_id
  ),
  bucketed as (
    select
      b.provider_id,
      jsonb_agg(
        jsonb_build_object(
          'start', b.bucket_start,
          'end', b.bucket_start + make_interval(hours => (select bucket_hours from params)),
          'requests', b.requests,
          'success_requests', b.success_requests,
          'health_requests', b.health_requests,
          'health_success_requests', b.health_success_requests,
          'uptime_pct',
            case
              when b.health_requests > 0
              then round((b.health_success_requests::numeric / b.health_requests::numeric) * 100, 2)
              else null
            end,
          'request_success_pct',
            case
              when b.requests > 0
              then round((b.success_requests::numeric / b.requests::numeric) * 100, 2)
              else null
            end,
          'avg_latency_ms', b.avg_latency_ms,
          'avg_throughput', b.avg_throughput
        )
        order by b.bucket_start
      ) as buckets
    from (
      select
        c.provider_id,
        date_bin(
          make_interval(hours => p.bucket_hours),
          c.created_at,
          timestamp with time zone '2000-01-01 00:00:00+00'
        ) as bucket_start,
        count(*)::bigint as requests,
        count(*) filter (where c.success is true)::bigint as success_requests,
        count(*) filter (where c.health_outcome <> 'neutral')::bigint as health_requests,
        count(*) filter (where c.health_outcome = 'success')::bigint as health_success_requests,
        avg(c.latency_ms) filter (where c.success is true and c.latency_ms is not null)::numeric as avg_latency_ms,
        avg(c.throughput) filter (where c.success is true and c.throughput is not null)::numeric as avg_throughput
      from classified c
      join params p on true
      group by c.provider_id, bucket_start
    ) b
    group by b.provider_id
  )
  select
    coalesce(pf.provider_id, a.provider_id) as provider_id,
    coalesce(dap.api_provider_name, coalesce(pf.provider_id, a.provider_id)) as provider_name,
    coalesce(a.requests, 0)::bigint as requests,
    coalesce(a.requests_30m, 0)::bigint as requests_30m,
    coalesce(a.success_requests, 0)::bigint as success_requests,
    coalesce(a.failed_requests, 0)::bigint as failed_requests,
    coalesce(a.neutral_requests, 0)::bigint as neutral_requests,
    coalesce(a.rate_limited_requests, 0)::bigint as rate_limited_requests,
    coalesce(a.health_requests, 0)::bigint as health_requests,
    coalesce(a.health_success_requests, 0)::bigint as health_success_requests,
    case
      when coalesce(a.health_requests, 0) > 0
      then round((a.health_success_requests::numeric / a.health_requests::numeric) * 100, 2)
      else null
    end as uptime_pct,
    case
      when coalesce(a.requests, 0) > 0
      then round((a.success_requests::numeric / a.requests::numeric) * 100, 2)
      else null
    end as request_success_pct,
    round(a.avg_latency_ms_30m, 2) as avg_latency_ms_30m,
    round(a.avg_throughput_30m, 2) as avg_throughput_30m,
    round(a.avg_latency_ms, 2) as avg_latency_ms,
    round(a.p50_latency_ms, 2) as p50_latency_ms,
    round(a.p95_latency_ms, 2) as p95_latency_ms,
    round(a.avg_generation_ms, 2) as avg_generation_ms,
    round(a.avg_throughput, 2) as avg_throughput,
    coalesce(a.total_tokens, 0)::bigint as total_tokens,
    coalesce(a.input_tokens_1h, 0)::bigint as input_tokens_1h,
    coalesce(a.output_tokens_1h, 0)::bigint as output_tokens_1h,
    coalesce(a.cached_read_tokens_1h, 0)::bigint as cached_read_tokens_1h,
    coalesce(a.input_tokens, 0)::bigint as input_tokens,
    coalesce(a.output_tokens, 0)::bigint as output_tokens,
    coalesce(fr.finish_reason_counts, '{}'::jsonb) as finish_reason_counts,
    coalesce(ec.error_code_counts, '{}'::jsonb) as error_code_counts,
    coalesce(b.buckets, '[]'::jsonb) as buckets,
    a.last_request_at
  from aggregates a
  full join provider_filter pf on pf.provider_id = a.provider_id
  left join private.v2_rpc_providers_compat dap
    on dap.api_provider_id = coalesce(pf.provider_id, a.provider_id)
  left join finish_reasons fr
    on fr.provider_id = a.provider_id
  left join error_codes ec
    on ec.provider_id = a.provider_id
  left join bucketed b
    on b.provider_id = a.provider_id
  where p_provider_ids is null or pf.provider_id is not null
  order by coalesce(a.requests, 0) desc, coalesce(pf.provider_id, a.provider_id);
$$;


--
-- Name: FUNCTION get_model_provider_health_metrics(p_model_ids text[], p_provider_ids text[], p_window_days integer, p_bucket_hours integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_model_provider_health_metrics(p_model_ids text[], p_provider_ids text[], p_window_days integer, p_bucket_hours integer) IS 'Provider-by-provider public model health metrics including uptime, latency, throughput, tokens, successful finish reasons, and failure codes.';


--
-- Name: get_model_provider_runtime_stats(text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_model_provider_runtime_stats(p_model_ids text[], p_provider_ids text[] DEFAULT NULL::text[]) RETURNS TABLE(provider text, latency_ms_30m numeric, throughput_30m numeric, latency_ms_3d numeric, throughput_3d numeric, requests_30m bigint, requests_3d bigint, successful_3d bigint, day0_requests bigint, day0_successful bigint, day1_requests bigint, day1_successful bigint, day2_requests bigint, day2_successful bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with anchors as (
    select
      now() as now_ts,
      now() - interval '30 minutes' as min_30m,
      now() - interval '72 hours' as min_3d,
      (date_trunc('day', now() at time zone 'utc') at time zone 'utc') as day0_start
  ),
  base as (
    select
      gr.provider,
      gr.created_at,
      gr.latency_ms,
      gr.throughput,
      gr.success,
      gr.status_code,
      lower(coalesce(gr.error_code, '')) as error_code
    from private.v2_rpc_gateway_requests_compat gr
    join anchors a on true
    where gr.created_at >= a.min_3d
      and gr.model_id = any(p_model_ids)
      and gr.provider is not null
      and gr.provider <> ''
      and (p_provider_ids is null or gr.provider = any(p_provider_ids))
  ),
  classified as (
    select
      b.*,
      case
        when b.success is true then 'count_success'
        when b.status_code is not null and b.status_code > 0 and b.status_code < 400 then 'count_success'
        when split_part(b.error_code, ':', 1) = 'user'
          or b.error_code like '%invalid_json%'
          or b.error_code like '%validation%'
          or b.error_code like '%unsupported_param%'
          or b.error_code like '%unsupported_model_or_endpoint%'
          or b.error_code like '%unsupported_modalities%'
          or b.error_code like '%bad_request%'
          or b.error_code like '%missing_required%'
        then 'exclude'
        when split_part(b.error_code, ':', 1) = 'gateway'
          or (
            split_part(b.error_code, ':', 1) = 'system' and (
              b.error_code like '%gateway%'
              or b.error_code like '%routing%'
              or b.error_code like '%breaker%'
              or b.error_code like '%provider_status_not_ready%'
              or b.error_code like '%no_key%'
              or b.error_code like '%missing_api_key%'
              or b.error_code like '%provider_key%'
              or b.error_code like '%pricing_not_configured%'
              or b.error_code like '%no_provider_pricing%'
              or b.error_code like '%all_candidates_failed%'
              or b.error_code like '%executor%'
              or b.error_code like '%internal%'
            )
          )
          or b.error_code like '%gateway%'
          or b.error_code like '%routing%'
          or b.error_code like '%breaker%'
          or b.error_code like '%provider_status_not_ready%'
          or b.error_code like '%no_key%'
          or b.error_code like '%missing_api_key%'
          or b.error_code like '%provider_key%'
          or b.error_code like '%pricing_not_configured%'
          or b.error_code like '%no_provider_pricing%'
          or b.error_code like '%all_candidates_failed%'
          or b.error_code like '%executor%'
          or b.error_code like '%internal%'
        then 'exclude'
        when b.status_code in (408, 429) or b.status_code >= 500 then 'count_failure'
        when b.status_code between 400 and 499 then 'exclude'
        else 'count_failure'
      end as uptime_outcome
    from base b
  ),
  aggregated as (
    select
      c.provider,
      percentile_cont(0.5) within group (order by c.latency_ms)
        filter (where c.created_at >= a.min_30m and c.latency_ms is not null) as latency_ms_30m,
      percentile_cont(0.5) within group (order by c.throughput)
        filter (where c.created_at >= a.min_30m and c.throughput is not null) as throughput_30m,
      percentile_cont(0.5) within group (order by c.latency_ms)
        filter (where c.latency_ms is not null) as latency_ms_3d,
      percentile_cont(0.5) within group (order by c.throughput)
        filter (where c.throughput is not null) as throughput_3d,
      count(*) filter (where c.created_at >= a.min_30m) as requests_30m,
      count(*) filter (where c.uptime_outcome <> 'exclude') as requests_3d,
      count(*) filter (where c.uptime_outcome = 'count_success') as successful_3d,
      count(*) filter (
        where c.uptime_outcome <> 'exclude'
          and c.created_at >= a.day0_start
          and c.created_at < a.day0_start + interval '1 day'
      ) as day0_requests,
      count(*) filter (
        where c.uptime_outcome = 'count_success'
          and c.created_at >= a.day0_start
          and c.created_at < a.day0_start + interval '1 day'
      ) as day0_successful,
      count(*) filter (
        where c.uptime_outcome <> 'exclude'
          and c.created_at >= a.day0_start - interval '1 day'
          and c.created_at < a.day0_start
      ) as day1_requests,
      count(*) filter (
        where c.uptime_outcome = 'count_success'
          and c.created_at >= a.day0_start - interval '1 day'
          and c.created_at < a.day0_start
      ) as day1_successful,
      count(*) filter (
        where c.uptime_outcome <> 'exclude'
          and c.created_at >= a.day0_start - interval '2 day'
          and c.created_at < a.day0_start - interval '1 day'
      ) as day2_requests,
      count(*) filter (
        where c.uptime_outcome = 'count_success'
          and c.created_at >= a.day0_start - interval '2 day'
          and c.created_at < a.day0_start - interval '1 day'
      ) as day2_successful
    from classified c
    join anchors a on true
    group by c.provider
  ),
  provider_filter as (
    select unnest(p_provider_ids) as provider
    where p_provider_ids is not null
  )
  select
    coalesce(pf.provider, ag.provider) as provider,
    ag.latency_ms_30m,
    ag.throughput_30m,
    ag.latency_ms_3d,
    ag.throughput_3d,
    coalesce(ag.requests_30m, 0)::bigint as requests_30m,
    coalesce(ag.requests_3d, 0)::bigint as requests_3d,
    coalesce(ag.successful_3d, 0)::bigint as successful_3d,
    coalesce(ag.day0_requests, 0)::bigint as day0_requests,
    coalesce(ag.day0_successful, 0)::bigint as day0_successful,
    coalesce(ag.day1_requests, 0)::bigint as day1_requests,
    coalesce(ag.day1_successful, 0)::bigint as day1_successful,
    coalesce(ag.day2_requests, 0)::bigint as day2_requests,
    coalesce(ag.day2_successful, 0)::bigint as day2_successful
  from aggregated ag
  full join provider_filter pf on pf.provider = ag.provider
  where p_provider_ids is null or pf.provider is not null
  order by coalesce(pf.provider, ag.provider);
$$;


--
-- Name: FUNCTION get_model_provider_runtime_stats(p_model_ids text[], p_provider_ids text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_model_provider_runtime_stats(p_model_ids text[], p_provider_ids text[]) IS 'Aggregated provider runtime stats for model pages (30m latency/throughput + 3d uptime windows) without returning raw gateway_requests rows.';


--
-- Name: get_model_time_of_day_metrics(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_model_time_of_day_metrics(p_model_id text, p_days integer DEFAULT 7) RETURNS TABLE(hour integer, median_throughput numeric, median_latency_ms numeric, median_generation_ms numeric, samples bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
	with windowed as (
		select
			date_part('hour', created_at at time zone 'UTC')::int as hour,
			throughput,
			latency_ms,
			generation_ms
		from gateway_requests
		where model_id = p_model_id
			and created_at >= timezone('UTC', now()) - (interval '1 day' * p_days)
	)
	select
		hour,
		percentile_cont(0.5) within group (order by throughput) as median_throughput,
		percentile_cont(0.5) within group (order by latency_ms) as median_latency_ms,
		percentile_cont(0.5) within group (order by generation_ms) as median_generation_ms,
		count(*) as samples
	from windowed
	group by hour
	order by hour;
$$;


--
-- Name: get_model_token_trajectory(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_model_token_trajectory(p_model_id text) RETURNS TABLE(release_date timestamp with time zone, deprecation_date timestamp with time zone, points jsonb, token_milestones jsonb, successor_milestones jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$with model_row as (
  select model_id, release_date, deprecation_date
  from private.v2_rpc_models_compat
  where model_id = p_model_id
  limit 1
),

-- Build the set of gateway_requests.model_id values to include
model_ids as (
  select p_model_id as model_id
  union
  select
    pm.provider_id || '/' || regexp_replace(pm.api_model_id, '^' || pm.provider_id || '/', '')
  from private.v2_rpc_routes_compat pm
  where pm.internal_model_id = p_model_id
),

anchors as (
  select
    mr.release_date,
    mr.deprecation_date,
    -- choose today's UTC day (not "greatest" vs release day; that could invert the range)
    date_trunc('day', now() at time zone 'utc') as today,
    date_trunc('day', mr.release_date) as start_day
  from model_row mr
),

daily_tokens as (
  select
    date_trunc('day', gr.created_at at time zone 'utc') as day,
    sum(
      coalesce(
        nullif((gr.usage ->> 'total_tokens')::numeric, 0),
        coalesce((gr.usage ->> 'input_tokens')::numeric, 0)
        + coalesce((gr.usage ->> 'output_tokens')::numeric, 0)
      )
    ) as tokens
  from private.v2_rpc_gateway_requests_compat gr
  cross join model_row mr
  where gr.model_id in (select model_id from model_ids)
    and mr.release_date is not null
    and gr.created_at >= mr.release_date
  group by 1
),

point_series as (
  select
    gs.day,
    coalesce(dt.tokens, 0) as tokens,
    sum(coalesce(dt.tokens, 0)) over (order by gs.day) as cumulative_tokens,
    floor(extract(epoch from (gs.day - (select release_date from model_row))) / 86400)::int as days_since_release
  from (
    select generate_series(
      (select start_day from anchors),
      (select today from anchors),
      interval '1 day'
    ) as day
  ) gs
  left join daily_tokens dt on dt.day = gs.day
),

points_json as (
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'date', to_char(day, 'YYYY-MM-DD"T"00:00:00.000Z'),
        'tokens', tokens,
        'cumulativeTokens', cumulative_tokens,
        'daysSinceRelease', days_since_release
      )
      order by day
    ),
    '[]'::jsonb
  ) as value
  from point_series
),

milestones as (
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'threshold', threshold,
        'reachedOn', reached_on,
        'daysSinceRelease', days_since_release
      )
      order by threshold
    ),
    '[]'::jsonb
  ) as value
  from (
    select
      threshold,
      (select to_char(ps.day, 'YYYY-MM-DD"T"00:00:00.000Z')
       from point_series ps
       where ps.cumulative_tokens >= threshold
       order by ps.day asc
       limit 1) as reached_on,
      (select ps.days_since_release
       from point_series ps
       where ps.cumulative_tokens >= threshold
       order by ps.day asc
       limit 1) as days_since_release
    from unnest(array[1000000, 10000000, 100000000, 1000000000]) as threshold
  ) m
),

successors as (
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'modelId', dm.model_id,
        'name', coalesce(dm.name, dm.model_id),
        'releaseDate', dm.release_date,
        'daysSinceRelease',
          case
            when mr.release_date is null or dm.release_date is null then null
            else floor(extract(epoch from (dm.release_date - mr.release_date)) / 86400)::int
          end
      )
    ),
    '[]'::jsonb
  ) as value
  from private.v2_rpc_models_compat dm
  cross join model_row mr
  where dm.previous_model_id = p_model_id
)

select
  (select release_date from model_row) as release_date,
  (select deprecation_date from model_row) as deprecation_date,
  (select value from points_json) as points,
  (select value from milestones) as token_milestones,
  (select value from successors) as successor_milestones
where (select release_date from model_row) is not null;$$;


--
-- Name: FUNCTION get_model_token_trajectory(p_model_id text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_model_token_trajectory(p_model_id text) IS 'Returns token trajectory (daily totals & cumulative), milestones, and successor milestones for a model.';


--
-- Name: get_model_usage_daily_breakdown(text[], text[], date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_model_usage_daily_breakdown(p_model_ids text[], p_provider_ids text[] DEFAULT NULL::text[], p_since date DEFAULT (CURRENT_DATE - 30), p_until date DEFAULT CURRENT_DATE) RETURNS TABLE(day_bucket date, model_id text, provider_id text, endpoint text, requests bigint, success_requests bigint, failed_requests bigint, neutral_requests bigint, rate_limited_requests bigint, total_tokens bigint, input_tokens bigint, output_tokens bigint, reasoning_tokens bigint, input_text_tokens bigint, output_text_tokens bigint, input_image_tokens bigint, output_image_tokens bigint, input_audio_tokens bigint, output_audio_tokens bigint, input_video_tokens bigint, output_video_tokens bigint, image_inputs bigint, image_outputs bigint, audio_inputs bigint, audio_outputs bigint, video_inputs bigint, video_outputs bigint, cached_read_tokens bigint, cached_write_tokens bigint, cached_read_text_tokens bigint, cached_write_text_tokens bigint, cached_write_text_tokens_5m bigint, cached_write_text_tokens_1h bigint, cached_read_image_tokens bigint, cached_write_image_tokens bigint, cached_read_audio_tokens bigint, cached_write_audio_tokens bigint, cached_read_video_tokens bigint, cached_write_video_tokens bigint, input_quad_tokens bigint, output_quad_tokens bigint, total_quad_tokens bigint, text_quad_tokens bigint, rerank_quad_tokens bigint, embedding_quad_tokens bigint, moderation_quad_tokens bigint, ocr_quad_tokens bigint, image_megapixels numeric, audio_seconds numeric, video_pixel_seconds numeric, input_characters bigint, output_characters bigint, total_characters bigint, total_cost_nanos bigint, avg_latency_ms numeric, avg_generation_ms numeric, avg_throughput numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with model_filter as (
    select distinct nullif(btrim(input.model_id), '') as model_id
    from unnest(coalesce(p_model_ids, array[]::text[])) as input(model_id)
    where nullif(btrim(input.model_id), '') is not null
  ),
  provider_filter as (
    select distinct nullif(btrim(input.provider_id), '') as provider_id
    from unnest(coalesce(p_provider_ids, array[]::text[])) as input(provider_id)
    where nullif(btrim(input.provider_id), '') is not null
  )
  select
    d.day_bucket,
    d.model_id,
    d.provider_id,
    d.endpoint,
    d.requests,
    d.success_requests,
    d.failed_requests,
    d.neutral_requests,
    d.rate_limited_requests,
    d.total_tokens,
    d.input_tokens,
    d.output_tokens,
    d.reasoning_tokens,
    d.input_text_tokens,
    d.output_text_tokens,
    d.input_image_tokens,
    d.output_image_tokens,
    d.input_audio_tokens,
    d.output_audio_tokens,
    d.input_video_tokens,
    d.output_video_tokens,
    d.image_inputs,
    d.image_outputs,
    d.audio_inputs,
    d.audio_outputs,
    d.video_inputs,
    d.video_outputs,
    d.cached_read_tokens,
    d.cached_write_tokens,
    d.cached_read_text_tokens,
    d.cached_write_text_tokens,
    d.cached_write_text_tokens_5m,
    d.cached_write_text_tokens_1h,
    d.cached_read_image_tokens,
    d.cached_write_image_tokens,
    d.cached_read_audio_tokens,
    d.cached_write_audio_tokens,
    d.cached_read_video_tokens,
    d.cached_write_video_tokens,
    d.input_quad_tokens,
    d.output_quad_tokens,
    d.total_quad_tokens,
    d.text_quad_tokens,
    d.rerank_quad_tokens,
    d.embedding_quad_tokens,
    d.moderation_quad_tokens,
    d.ocr_quad_tokens,
    d.image_megapixels,
    d.audio_seconds,
    d.video_pixel_seconds,
    d.input_characters,
    d.output_characters,
    d.total_characters,
    d.total_cost_nanos,
    case when d.latency_samples > 0 then round(d.latency_sum_ms::numeric / d.latency_samples::numeric, 2) else null end as avg_latency_ms,
    case when d.generation_samples > 0 then round(d.generation_sum_ms::numeric / d.generation_samples::numeric, 2) else null end as avg_generation_ms,
    case when d.throughput_samples > 0 then round(d.throughput_sum::numeric / d.throughput_samples::numeric, 2) else null end as avg_throughput
  from public.v2_rpc_gateway_model_usage_daily d
  where d.day_bucket >= p_since
    and d.day_bucket <= p_until
    and exists (
      select 1 from model_filter mf where mf.model_id = d.model_id
    )
    and (
      p_provider_ids is null
      or array_length(p_provider_ids, 1) is null
      or exists (
        select 1 from provider_filter pf where pf.provider_id = d.provider_id
      )
    )
  order by d.day_bucket asc, d.provider_id asc, d.endpoint asc;
$$;


