--
-- Name: get_monitor_history_page(text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_monitor_history_page(p_model text DEFAULT NULL::text, p_provider text DEFAULT NULL::text, p_change_kind text DEFAULT NULL::text, p_commit_offset integer DEFAULT 0, p_commit_limit integer DEFAULT 18) RETURNS TABLE(event_id text, committed_at timestamp with time zone, provider_kind text, model_id text, endpoint text, field text, old_value jsonb, new_value jsonb, percent_change double precision, action text, commit_sha text, entity_id text, entity_type text, org_id text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with filtered as (
    select e.*
    from public.monitor_history_events e
    where (
      p_model is null
      or btrim(p_model) = ''
      or e.model_id = p_model
    )
      and (
        p_provider is null
        or btrim(p_provider) = ''
        or e.provider_slug = p_provider
      )
      and (
        p_change_kind is null
        or btrim(p_change_kind) = ''
        or p_change_kind = 'all'
        or e.change_kind = p_change_kind
      )
  ),
  visible_commits as (
    select
      filtered.commit_sha,
      max(filtered.committed_at) as committed_at
    from filtered
    group by filtered.commit_sha
    order by max(filtered.committed_at) desc, filtered.commit_sha desc
    offset greatest(coalesce(p_commit_offset, 0), 0)
    limit greatest(coalesce(p_commit_limit, 18), 1)
  )
  select
    e.event_id,
    e.committed_at,
    e.provider_kind,
    e.model_id,
    e.endpoint,
    e.field,
    e.old_value,
    e.new_value,
    e.percent_change,
    e.action,
    e.commit_sha,
    e.entity_id,
    e.entity_type,
    e.org_id
  from filtered e
  join visible_commits vc
    on vc.commit_sha = e.commit_sha
  order by
    vc.committed_at desc,
    e.committed_at desc,
    lower(coalesce(e.org_id, '')) asc,
    lower(coalesce(e.model_id, '')) asc,
    case coalesce(e.action, '')
      when 'added' then 0
      when 'changed' then 1
      when 'removed' then 2
      else 3
    end asc,
    case coalesce(e.entity_type, '')
      when 'organisation' then 0
      when 'model' then 1
      when 'family' then 2
      when 'api-provider' then 3
      when 'benchmark' then 4
      when 'alias' then 5
      when 'subscription-plan' then 6
      when 'pricing' then 7
      else 8
    end asc,
    case when e.endpoint is null or btrim(e.endpoint) = '' then 0 else 1 end asc,
    e.event_id asc;
$$;


--
-- Name: FUNCTION get_monitor_history_page(p_model text, p_provider text, p_change_kind text, p_commit_offset integer, p_commit_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_monitor_history_page(p_model text, p_provider text, p_change_kind text, p_commit_offset integer, p_commit_limit integer) IS 'Returns one paginated slice of monitor history grouped by visible commits.';


--
-- Name: get_monitor_history_stats(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_monitor_history_stats(p_model text DEFAULT NULL::text, p_provider text DEFAULT NULL::text, p_change_kind text DEFAULT NULL::text) RETURNS TABLE(total_changes bigint, total_commits bigint, generated_at timestamp with time zone, last_sha text, source_base text, source_head text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with filtered as (
    select e.*
    from public.monitor_history_events e
    where (
      p_model is null
      or btrim(p_model) = ''
      or e.model_id = p_model
    )
      and (
        p_provider is null
        or btrim(p_provider) = ''
        or e.provider_slug = p_provider
      )
      and (
        p_change_kind is null
        or btrim(p_change_kind) = ''
        or p_change_kind = 'all'
        or e.change_kind = p_change_kind
      )
  ),
  counts as (
    select
      count(*)::bigint as total_changes,
      count(distinct filtered.commit_sha)::bigint as total_commits
    from filtered
  ),
  state as (
    select
      s.generated_at,
      s.last_sha,
      s.source_base,
      s.source_head
    from public.monitor_history_sync_state s
    where s.sync_key = 'catalog'
    limit 1
  )
  select
    counts.total_changes,
    counts.total_commits,
    state.generated_at,
    state.last_sha,
    state.source_base,
    state.source_head
  from counts
  left join state on true;
$$;


