-- Name: get_public_image_input_timeseries(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_image_input_timeseries(p_time_range text DEFAULT 'year'::text, p_top_n integer DEFAULT 20) RETURNS TABLE(bucket timestamp with time zone, model_id text, requests bigint, tokens numeric, colour text)
