    AS $$
  select model.model_slug, model.license, model.license_url
  from public.v2_models model
  where model.model_slug = lower(trim(p_model_slug))
    and model.hidden = false
    and model.status <> 'disabled';
$$;


--
-- Name: get_v2_model_overview(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_overview(p_model_slug text, p_region text DEFAULT NULL::text, p_service_tier text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with routed_model as (
    select page.payload
    from public.get_v2_public_models_page_rows(p_region, coalesce(p_service_tier, 'standard')) as page(payload)
    where page.payload->>'model_id' = lower(p_model_slug)
    limit 1
  ),
  catalogue_model as (
    select jsonb_build_object(
      'model_id', model.model_slug,
      'name', model.name,
      'description', model.description,
      'organisation_id', model.lab_slug,
      'organisation_name', lab.name,
      'primary_date', coalesce(model.released_at, model.announced_at),
      'primary_timestamp', extract(epoch from coalesce(model.released_at, model.announced_at)) * 1000,
      'primary_group_key', to_char(coalesce(model.released_at, model.announced_at), 'YYYY-MM'),
      'gateway_status', case
        when lower(coalesce(model.catalogue_status, model.status, '')) in ('draft', 'announced') then 'coming_soon'
        else 'not_active'
      end,
      'gateway_provider_count', 0,
      'gateway_active_provider_count', 0,
      'gateway_endpoints', array[]::text[],
      'gateway_input_modalities', coalesce(model.input_modalities, array[]::text[]),
      'gateway_output_modalities', coalesce(model.output_modalities, array[]::text[]),
      'gateway_features', array[]::text[],
      'gateway_tiers', array[]::text[],
      'gateway_provider_names', array[]::text[],
      'gateway_active_provider_names', array[]::text[],
      'gateway_execution_regions', array[]::text[],
      'gateway_provider_details', '[]'::jsonb,
      'gateway_api_model_ids', array[]::text[],
      'context_lengths', case
        when jsonb_typeof(model.metadata->'limits'->'context') = 'number'
          then jsonb_build_array((model.metadata->'limits'->>'context')::integer)
        else '[]'::jsonb
      end,
      'supported_parameters', array[]::text[],
      'lowest_input_price', null,
      'lowest_output_price', null,
      'lowest_standard_input_price', null,
      'lowest_standard_output_price', null,
      'lowest_from_price', null,
      'pricing_detail_rows', '[]'::jsonb,
      'gateway_monitor_rows', '[]'::jsonb,
      'popularity_tokens_week', null,
      'throughput_week', null,
      'latency_week', null
    ) as payload
    from public.v2_models model
    join public.v2_labs lab on lab.lab_slug = model.lab_slug
    where model.model_slug = lower(p_model_slug)
      and model.hidden = false
      and model.status <> 'disabled'
      and not exists (
        select 1
        from public.v2_model_provider_routes route
        join public.v2_providers provider on provider.provider_slug = route.provider_slug
        join public.v2_route_variants variant on variant.provider_model_id = route.provider_model_id
        where route.model_slug = model.model_slug
          and route.status in ('active', 'degraded')
          and route.routing_enabled = true
          and provider.status <> 'disabled'
          and provider.routing_enabled = true
          and variant.status in ('active', 'degraded')
          and variant.routing_enabled = true
      )
    limit 1
  )
  select case
    when not exists (select 1 from routed_model)
      and not exists (select 1 from catalogue_model)
      then '{}'::jsonb
    else coalesce(
      (select payload from routed_model),
      (select payload from catalogue_model)
    ) || jsonb_build_object(
    'routes', coalesce((
      select jsonb_agg(to_jsonb(route_row) order by route_row.provider_name, route_row.variant_key)
      from (
        select
          variant.variant_id,
          variant.provider_model_id,
          route.provider_slug,
          provider.name as provider_name,
          route.provider_model_slug,
          variant.variant_key,
          variant.service_tier_slug,
          variant.execution_region,
          variant.data_region,
          variant.status,
          variant.routing_enabled,
          route.status as route_status,
          provider.status as provider_status,
          provider.routing_enabled as provider_routing_enabled
        from public.v2_route_variants variant
        join public.v2_model_provider_routes route on route.provider_model_id = variant.provider_model_id
        join public.v2_providers provider on provider.provider_slug = route.provider_slug
        where route.model_slug = lower(p_model_slug)
          and variant.status <> 'disabled'
          and (p_service_tier is null or variant.service_tier_slug = lower(p_service_tier))
          and (p_region is null or lower(p_region) = lower(coalesce(variant.execution_region, '')) or lower(p_region) = lower(coalesce(variant.data_region, '')))
      ) route_row
    ), '[]'::jsonb),
    'service_tiers', coalesce((
      select jsonb_agg(distinct variant.service_tier_slug order by variant.service_tier_slug)
      from public.v2_route_variants variant
      join public.v2_model_provider_routes route on route.provider_model_id = variant.provider_model_id
      where route.model_slug = lower(p_model_slug) and variant.status <> 'disabled'
    ), '[]'::jsonb),
    'regions', coalesce((
      select jsonb_agg(distinct region order by region)
      from public.v2_route_variants variant
      join public.v2_model_provider_routes route on route.provider_model_id = variant.provider_model_id
      cross join lateral (values (variant.execution_region), (variant.data_region)) regions(region)
      where route.model_slug = lower(p_model_slug) and region is not null
    ), '[]'::jsonb)
    )
  end;
$$;


--
-- Name: FUNCTION get_v2_model_overview(p_model_slug text, p_region text, p_service_tier text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_v2_model_overview(p_model_slug text, p_region text, p_service_tier text) IS 'Returns stable catalogue facts for visible models, including models without active provider routes, plus any available route metadata.';


--
-- Name: get_v2_model_performance_colos(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_performance_colos(p_model_slug text) RETURNS TABLE(cloudflare_colo text, request_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
select colos.*
from public.v2_models model
cross join lateral public.get_v2_model_performance_colos_unfiltered(model.model_slug) colos
where model.model_slug = lower(trim(p_model_slug))
  and model.hidden = false
  and model.status <> 'disabled';
$$;


--
-- Name: get_v2_model_performance_colos_unfiltered(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_performance_colos_unfiltered(p_model_slug text) RETURNS TABLE(cloudflare_colo text, request_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select
    upper(trim(usage.cloudflare_colo)) as cloudflare_colo,
    sum(usage.requests)::bigint as request_count
  from public.v2_public_usage_hourly usage
  where usage.model_slug = lower(trim(p_model_slug))
    and usage.cloudflare_colo is not null
    and usage.bucket_start >= now() - interval '30 days'
  group by upper(trim(usage.cloudflare_colo))
  order by request_count desc, cloudflare_colo asc;
$$;


--
-- Name: get_v2_model_performance_metrics(text, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_performance_metrics(p_model_slug text, p_cloudflare_colo text DEFAULT NULL::text, p_percentile numeric DEFAULT 0.5, p_stream_mode text DEFAULT 'all'::text, p_context_bucket text DEFAULT 'all'::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
with visible_model as (
  select model.model_slug
  from public.v2_models model
  where model.model_slug = p_model_slug
    and model.hidden = false
    and model.status <> 'disabled'
), raw as (
  select public.get_v2_model_performance_metrics_unsuppressed(
    visible_model.model_slug,
    p_cloudflare_colo,
    p_percentile,
    p_stream_mode,
    p_context_bucket
  ) payload
  from visible_model
), suppressed as (
  select
    case
      when coalesce((payload #>> '{last_24h,total_requests}')::bigint, 0) >= 20
        then payload -> 'last_24h'
      else '{}'::jsonb
    end last_24h,
    coalesce((
      select jsonb_agg(entry order by entry ->> 'bucket')
      from jsonb_array_elements(coalesce(payload -> 'hourly_24h', '[]'::jsonb)) entry
      where coalesce((entry ->> 'requests')::bigint, 0) >= 20
    ), '[]'::jsonb) hourly_24h,
    coalesce((
      select jsonb_agg(entry order by entry ->> 'day', entry ->> 'provider')
      from jsonb_array_elements(coalesce(payload -> 'provider_daily_7d', '[]'::jsonb)) entry
      where coalesce((entry ->> 'requests')::bigint, 0) >= 20
    ), '[]'::jsonb) provider_daily_7d,
    payload
  from raw
)
select jsonb_set(
  jsonb_set(
    jsonb_set(payload, '{last_24h}', last_24h),
    '{hourly_24h}', hourly_24h
  ),
  '{provider_daily_7d}', provider_daily_7d
)
from suppressed;
$$;


--
-- Name: get_v2_model_performance_metrics_unsuppressed(text, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_performance_metrics_unsuppressed(p_model_slug text, p_cloudflare_colo text DEFAULT NULL::text, p_percentile numeric DEFAULT 0.5, p_stream_mode text DEFAULT 'all'::text, p_context_bucket text DEFAULT 'all'::text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
with params as (
  select
    lower(trim(p_model_slug)) model_slug,
    nullif(upper(trim(p_cloudflare_colo)), '') cloudflare_colo,
    greatest(0.01, least(0.99, coalesce(p_percentile, 0.5)))::double precision percentile,
    case when lower(p_stream_mode) in ('stream', 'non_stream') then lower(p_stream_mode) else 'all' end stream_mode,
    case when lower(p_context_bucket) in ('lte_4k', '4k_16k', '16k_64k', 'gt_64k') then lower(p_context_bucket) else 'all' end context_bucket,
    now() now_ts
),
scoped_facts as (
  select fact.request_event_id
  from public.v2_request_facts fact
  cross join params
  where coalesce(fact.routed_model_slug, fact.requested_model_slug) = params.model_slug
    and fact.occurred_at >= params.now_ts - interval '7 days'
),
usage_tokens as (
  select usage.request_event_id,
    sum(usage.quantity) filter (where usage.meter_key in ('input_tokens', 'input_text_tokens', 'prompt_tokens'))::numeric input_tokens
  from public.v2_request_usage usage
  join scoped_facts on scoped_facts.request_event_id = usage.request_event_id
  where usage.meter_key in ('input_tokens', 'input_text_tokens', 'prompt_tokens')
  group by usage.request_event_id
),
base as (
  select date_trunc('hour', fact.occurred_at) bucket_start,
    fact.occurred_at::date usage_day,
    route.provider_slug provider_id,
    fact.success, fact.stream, tokens.input_tokens,
    fact.gateway_ttft_ms, fact.provider_ttft_ms, fact.generation_ms provider_duration_ms,
    fact.gateway_total_ms gateway_e2e_ms, fact.phaseo_overhead_ms,
    fact.throughput effective_throughput_tps, fact.output_speed_tps,
    fact.tpot_ms, fact.itl_ms
  from public.v2_request_facts fact
  left join public.v2_model_provider_routes route on route.provider_model_id = fact.provider_model_id
  left join usage_tokens tokens on tokens.request_event_id = fact.request_event_id
  cross join params
  where coalesce(fact.routed_model_slug, fact.requested_model_slug) = params.model_slug
    and fact.occurred_at >= params.now_ts - interval '7 days'
    and (params.cloudflare_colo is null or upper(trim(fact.cloudflare_colo)) = params.cloudflare_colo)
    and (params.stream_mode = 'all' or fact.stream = (params.stream_mode = 'stream'))
    and (
      params.context_bucket = 'all'
      or (params.context_bucket = 'lte_4k' and tokens.input_tokens <= 4096)
      or (params.context_bucket = '4k_16k' and tokens.input_tokens > 4096 and tokens.input_tokens <= 16384)
      or (params.context_bucket = '16k_64k' and tokens.input_tokens > 16384 and tokens.input_tokens <= 65536)
      or (params.context_bucket = 'gt_64k' and tokens.input_tokens > 65536)
    )
),
hourly as (
  select bucket_start, count(*)::bigint requests,
    count(*) filter (where success)::bigint successful_requests,
    percentile_cont((select percentile from params)) within group (order by gateway_ttft_ms)
      filter (where success and gateway_ttft_ms is not null)::numeric gateway_ttft_ms,
    percentile_cont((select percentile from params)) within group (order by provider_ttft_ms)
      filter (where success and provider_ttft_ms is not null)::numeric provider_ttft_ms,
    percentile_cont((select percentile from params)) within group (order by provider_duration_ms)
      filter (where success and provider_duration_ms is not null)::numeric provider_duration_ms,
    percentile_cont((select percentile from params)) within group (order by gateway_e2e_ms)
      filter (where success and gateway_e2e_ms is not null)::numeric gateway_e2e_ms,
    percentile_cont((select percentile from params)) within group (order by phaseo_overhead_ms)
      filter (where success and phaseo_overhead_ms is not null)::numeric phaseo_overhead_ms,
    percentile_cont((select percentile from params)) within group (order by effective_throughput_tps)
      filter (where success and effective_throughput_tps is not null)::numeric effective_throughput_tps,
    percentile_cont((select percentile from params)) within group (order by output_speed_tps)
      filter (where success and output_speed_tps is not null)::numeric output_speed_tps,
    percentile_cont((select percentile from params)) within group (order by tpot_ms)
      filter (where success and tpot_ms is not null)::numeric tpot_ms,
    percentile_cont((select percentile from params)) within group (order by itl_ms)
      filter (where success and itl_ms is not null)::numeric itl_ms
  from base group by bucket_start
),
provider_daily as (
  select usage_day, provider_id, count(*)::bigint requests,
    percentile_cont((select percentile from params)) within group (order by gateway_ttft_ms)
      filter (where success and gateway_ttft_ms is not null)::numeric gateway_ttft_ms,
    percentile_cont((select percentile from params)) within group (order by provider_duration_ms)
      filter (where success and provider_duration_ms is not null)::numeric provider_duration_ms,
    percentile_cont((select percentile from params)) within group (order by effective_throughput_tps)
      filter (where success and effective_throughput_tps is not null)::numeric effective_throughput_tps,
    percentile_cont((select percentile from params)) within group (order by output_speed_tps)
      filter (where success and output_speed_tps is not null)::numeric output_speed_tps,
    percentile_cont((select percentile from params)) within group (order by phaseo_overhead_ms)
      filter (where success and phaseo_overhead_ms is not null)::numeric phaseo_overhead_ms,
    percentile_cont((select percentile from params)) within group (order by tpot_ms)
      filter (where success and tpot_ms is not null)::numeric tpot_ms,
    percentile_cont((select percentile from params)) within group (order by itl_ms)
      filter (where success and itl_ms is not null)::numeric itl_ms
  from base where provider_id is not null group by usage_day, provider_id
),
recent as (select * from base where bucket_start >= (select now_ts from params) - interval '24 hours'),
summary as (
  select count(*)::bigint requests, count(*) filter (where success)::bigint successful_requests,
    percentile_cont((select percentile from params)) within group (order by gateway_ttft_ms) filter (where success and gateway_ttft_ms is not null)::numeric gateway_ttft_ms,
    percentile_cont((select percentile from params)) within group (order by provider_duration_ms) filter (where success and provider_duration_ms is not null)::numeric provider_duration_ms,
    percentile_cont((select percentile from params)) within group (order by effective_throughput_tps) filter (where success and effective_throughput_tps is not null)::numeric effective_throughput_tps,
    percentile_cont((select percentile from params)) within group (order by output_speed_tps) filter (where success and output_speed_tps is not null)::numeric output_speed_tps,
    percentile_cont((select percentile from params)) within group (order by phaseo_overhead_ms) filter (where success and phaseo_overhead_ms is not null)::numeric phaseo_overhead_ms,
    percentile_cont((select percentile from params)) within group (order by tpot_ms) filter (where success and tpot_ms is not null)::numeric tpot_ms,
    percentile_cont((select percentile from params)) within group (order by itl_ms) filter (where success and itl_ms is not null)::numeric itl_ms
  from recent
)
select jsonb_build_object(
  'percentile', (select percentile * 100 from params),
  'stream_mode', (select stream_mode from params),
  'context_bucket', (select context_bucket from params),
  'cloudflare_colo', (select cloudflare_colo from params),
  'last_24h', jsonb_build_object(
    'total_requests', summary.requests, 'successful_requests', summary.successful_requests,
    'uptime_pct', case when summary.requests > 0 then summary.successful_requests * 100.0 / summary.requests else null end,
    'gateway_ttft_ms', summary.gateway_ttft_ms, 'avg_latency_ms', summary.gateway_ttft_ms,
    'provider_duration_ms', summary.provider_duration_ms, 'avg_generation_ms', summary.provider_duration_ms,
    'effective_throughput_tps', summary.effective_throughput_tps, 'avg_throughput', summary.effective_throughput_tps,
    'output_speed_tps', summary.output_speed_tps, 'phaseo_overhead_ms', summary.phaseo_overhead_ms,
    'tpot_ms', summary.tpot_ms, 'itl_ms', summary.itl_ms
  ),
  'prev_24h', null,
  'hourly_24h', coalesce((select jsonb_agg(jsonb_build_object(
    'bucket', bucket_start, 'requests', requests,
    'success_pct', case when requests > 0 then successful_requests * 100.0 / requests else null end,
    'gateway_ttft_ms', gateway_ttft_ms, 'avg_latency_ms', gateway_ttft_ms,
    'provider_ttft_ms', provider_ttft_ms,
    'provider_duration_ms', provider_duration_ms, 'avg_generation_ms', provider_duration_ms,
    'gateway_e2e_ms', gateway_e2e_ms, 'phaseo_overhead_ms', phaseo_overhead_ms,
    'effective_throughput_tps', effective_throughput_tps, 'avg_throughput', effective_throughput_tps,
    'output_speed_tps', output_speed_tps, 'tpot_ms', tpot_ms, 'itl_ms', itl_ms
  ) order by bucket_start) from hourly where bucket_start >= (select now_ts from params) - interval '24 hours'), '[]'::jsonb),
  'provider_uptime_24h', '[]'::jsonb,
  'provider_daily_7d', coalesce((select jsonb_agg(jsonb_build_object(
    'day', usage_day, 'provider', provider_id, 'provider_name', provider.name, 'requests', requests,
    'gateway_ttft_ms', gateway_ttft_ms, 'avg_latency_ms', gateway_ttft_ms,
    'provider_duration_ms', provider_duration_ms, 'avg_generation_ms', provider_duration_ms,
    'effective_throughput_tps', effective_throughput_tps, 'avg_throughput', effective_throughput_tps,
    'output_speed_tps', output_speed_tps, 'phaseo_overhead_ms', phaseo_overhead_ms,
    'tpot_ms', tpot_ms, 'itl_ms', itl_ms
  ) order by usage_day, provider_id)
  from provider_daily join public.v2_providers provider on provider.provider_slug = provider_id), '[]'::jsonb),
  'time_of_day_5d', '[]'::jsonb,
  'cumulative_tokens', null
) from summary;
$$;


--
-- Name: get_v2_model_performance_overview(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_performance_overview(p_model_slug text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with hourly as (
    select bucket_start, provider_model_id,
      sum(requests)::numeric as requests,
      sum(successful_requests)::numeric as successful_requests,
      sum(latency_sum_ms)::numeric as latency_sum_ms,
      sum(latency_count)::numeric as latency_count,
      sum(generation_sum_ms)::numeric as generation_sum_ms,
      sum(generation_count)::numeric as generation_count,
      sum(throughput_sum)::numeric as throughput_sum,
      sum(throughput_count)::numeric as throughput_count
    from public.v2_public_usage_hourly
    where model_slug = lower(trim(p_model_slug))
      and bucket_start >= now() - interval '5 days'
    group by bucket_start, provider_model_id
  ),
  last_day as (
    select sum(requests) as requests, sum(successful_requests) as successful_requests,
      sum(latency_sum_ms) as latency_sum_ms, sum(latency_count) as latency_count,
      sum(generation_sum_ms) as generation_sum_ms, sum(generation_count) as generation_count,
      sum(throughput_sum) as throughput_sum, sum(throughput_count) as throughput_count
    from hourly where bucket_start >= now() - interval '24 hours'
  ),
  previous_day as (
    select sum(requests) as requests, sum(successful_requests) as successful_requests,
      sum(latency_sum_ms) as latency_sum_ms, sum(latency_count) as latency_count,
      sum(generation_sum_ms) as generation_sum_ms, sum(generation_count) as generation_count,
      sum(throughput_sum) as throughput_sum, sum(throughput_count) as throughput_count
    from hourly where bucket_start >= now() - interval '48 hours' and bucket_start < now() - interval '24 hours'
  ),
  hourly_rows as (
    select bucket_start, sum(requests) as requests, sum(successful_requests) as successful_requests,
      sum(latency_sum_ms) as latency_sum_ms, sum(latency_count) as latency_count,
      sum(generation_sum_ms) as generation_sum_ms, sum(generation_count) as generation_count,
      sum(throughput_sum) as throughput_sum, sum(throughput_count) as throughput_count
    from hourly where bucket_start >= now() - interval '24 hours' group by bucket_start
  ),
  provider_rows as (
    select route.provider_slug, max(provider.name) as provider_name,
      sum(hourly.requests) as requests, sum(hourly.successful_requests) as successful_requests,
      sum(hourly.latency_sum_ms) as latency_sum_ms, sum(hourly.latency_count) as latency_count,
      sum(hourly.generation_sum_ms) as generation_sum_ms, sum(hourly.generation_count) as generation_count,
      sum(hourly.throughput_sum) as throughput_sum, sum(hourly.throughput_count) as throughput_count
    from hourly
    left join public.v2_model_provider_routes route on route.provider_model_id = hourly.provider_model_id
    left join public.v2_providers provider on provider.provider_slug = route.provider_slug
    where hourly.bucket_start >= now() - interval '24 hours'
    group by route.provider_slug
  ),
  success_buckets as (
    select jsonb_agg(jsonb_build_object('bucket', h.bucket_start, 'requests', h.requests,
      'success_pct', case when h.requests > 0 then h.successful_requests * 100.0 / h.requests else null end,
      'avg_latency_ms', case when h.latency_count > 0 then h.latency_sum_ms / h.latency_count else null end,
      'avg_generation_ms', case when h.generation_count > 0 then h.generation_sum_ms / h.generation_count else null end,
      'avg_throughput', case when h.throughput_count > 0 then h.throughput_sum / h.throughput_count else null end) order by h.bucket_start) as value
    from hourly_rows h
  ),
  provider_json as (
    select jsonb_agg(jsonb_build_object('provider', p.provider_slug, 'provider_name', p.provider_name,
      'requests', p.requests, 'uptime_pct', case when p.requests > 0 then p.successful_requests * 100.0 / p.requests else null end,
      'avg_latency_ms', case when p.latency_count > 0 then p.latency_sum_ms / p.latency_count else null end,
      'avg_generation_ms', case when p.generation_count > 0 then p.generation_sum_ms / p.generation_count else null end,
      'avg_throughput', case when p.throughput_count > 0 then p.throughput_sum / p.throughput_count else null end,
      'uptime_buckets', '[]'::jsonb) order by p.provider_name) as value
    from provider_rows p
  )
  select jsonb_build_object(
    'last_24h', jsonb_build_object('total_requests', coalesce(last.requests, 0), 'successful_requests', coalesce(last.successful_requests, 0),
      'avg_latency_ms', case when last.latency_count > 0 then last.latency_sum_ms / last.latency_count else null end,
      'avg_generation_ms', case when last.generation_count > 0 then last.generation_sum_ms / last.generation_count else null end,
      'avg_throughput', case when last.throughput_count > 0 then last.throughput_sum / last.throughput_count else null end,
      'uptime_pct', case when last.requests > 0 then last.successful_requests * 100.0 / last.requests else null end),
    'prev_24h', jsonb_build_object('total_requests', coalesce(previous.requests, 0), 'successful_requests', coalesce(previous.successful_requests, 0),
      'avg_latency_ms', case when previous.latency_count > 0 then previous.latency_sum_ms / previous.latency_count else null end,
      'avg_generation_ms', case when previous.generation_count > 0 then previous.generation_sum_ms / previous.generation_count else null end,
      'avg_throughput', case when previous.throughput_count > 0 then previous.throughput_sum / previous.throughput_count else null end,
      'uptime_pct', case when previous.requests > 0 then previous.successful_requests * 100.0 / previous.requests else null end),
    'hourly_24h', coalesce((select value from success_buckets), '[]'::jsonb),
    'provider_uptime_24h', coalesce((select value from provider_json), '[]'::jsonb),
    'time_of_day_5d', '[]'::jsonb, 'cumulative_tokens', null)
  from last_day last cross join previous_day previous;
$$;


--
-- Name: get_v2_model_performance_overview(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_performance_overview(p_model_slug text, p_cloudflare_colo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with hourly as (
    select
      bucket_start,
      provider_model_id,
      sum(requests)::numeric as requests,
      sum(successful_requests)::numeric as successful_requests,
      sum(latency_sum_ms)::numeric as latency_sum_ms,
      sum(latency_count)::numeric as latency_count,
      sum(generation_sum_ms)::numeric as generation_sum_ms,
      sum(generation_count)::numeric as generation_count,
      sum(throughput_sum)::numeric as throughput_sum,
      sum(throughput_count)::numeric as throughput_count
    from public.v2_public_usage_hourly
    where model_slug = lower(trim(p_model_slug))
      and bucket_start >= now() - interval '5 days'
      and (p_cloudflare_colo is null or cloudflare_colo = upper(trim(p_cloudflare_colo)))
    group by bucket_start, provider_model_id
  ),
  last_day as (
    select sum(requests) as requests, sum(successful_requests) as successful_requests,
      sum(latency_sum_ms) as latency_sum_ms, sum(latency_count) as latency_count,
      sum(generation_sum_ms) as generation_sum_ms, sum(generation_count) as generation_count,
      sum(throughput_sum) as throughput_sum, sum(throughput_count) as throughput_count
    from hourly where bucket_start >= now() - interval '24 hours'
  ),
  previous_day as (
    select sum(requests) as requests, sum(successful_requests) as successful_requests,
      sum(latency_sum_ms) as latency_sum_ms, sum(latency_count) as latency_count,
      sum(generation_sum_ms) as generation_sum_ms, sum(generation_count) as generation_count,
      sum(throughput_sum) as throughput_sum, sum(throughput_count) as throughput_count
    from hourly where bucket_start >= now() - interval '48 hours' and bucket_start < now() - interval '24 hours'
  ),
  hourly_rows as (
    select bucket_start, sum(requests) as requests, sum(successful_requests) as successful_requests,
      sum(latency_sum_ms) as latency_sum_ms, sum(latency_count) as latency_count,
      sum(generation_sum_ms) as generation_sum_ms, sum(generation_count) as generation_count,
      sum(throughput_sum) as throughput_sum, sum(throughput_count) as throughput_count
    from hourly where bucket_start >= now() - interval '24 hours' group by bucket_start
  ),
  provider_rows as (
    select route.provider_slug, max(provider.name) as provider_name,
      sum(hourly.requests) as requests, sum(hourly.successful_requests) as successful_requests,
      sum(hourly.latency_sum_ms) as latency_sum_ms, sum(hourly.latency_count) as latency_count,
      sum(hourly.generation_sum_ms) as generation_sum_ms, sum(hourly.generation_count) as generation_count,
      sum(hourly.throughput_sum) as throughput_sum, sum(hourly.throughput_count) as throughput_count
    from hourly
    left join public.v2_model_provider_routes route on route.provider_model_id = hourly.provider_model_id
    left join public.v2_providers provider on provider.provider_slug = route.provider_slug
    where hourly.bucket_start >= now() - interval '24 hours'
    group by route.provider_slug
  ),
  success_buckets as (
    select jsonb_agg(jsonb_build_object(
      'bucket', rows.bucket_start, 'requests', rows.requests,
      'success_pct', case when rows.requests > 0 then rows.successful_requests * 100.0 / rows.requests else null end,
      'avg_latency_ms', case when rows.latency_count > 0 then rows.latency_sum_ms / rows.latency_count else null end,
      'avg_generation_ms', case when rows.generation_count > 0 then rows.generation_sum_ms / rows.generation_count else null end,
      'avg_throughput', case when rows.throughput_count > 0 then rows.throughput_sum / rows.throughput_count else null end
    ) order by rows.bucket_start) as value from hourly_rows rows
  ),
  provider_json as (
    select jsonb_agg(jsonb_build_object(
      'provider', row.provider_slug, 'provider_name', row.provider_name, 'requests', row.requests,
      'uptime_pct', case when row.requests > 0 then row.successful_requests * 100.0 / row.requests else null end,
      'avg_latency_ms', case when row.latency_count > 0 then row.latency_sum_ms / row.latency_count else null end,
      'avg_generation_ms', case when row.generation_count > 0 then row.generation_sum_ms / row.generation_count else null end,
      'avg_throughput', case when row.throughput_count > 0 then row.throughput_sum / row.throughput_count else null end,
      'uptime_buckets', '[]'::jsonb
    ) order by row.provider_name) as value from provider_rows row
  )
  select jsonb_build_object(
    'last_24h', jsonb_build_object(
      'total_requests', coalesce(last.requests, 0), 'successful_requests', coalesce(last.successful_requests, 0),
      'avg_latency_ms', case when last.latency_count > 0 then last.latency_sum_ms / last.latency_count else null end,
      'avg_generation_ms', case when last.generation_count > 0 then last.generation_sum_ms / last.generation_count else null end,
      'avg_throughput', case when last.throughput_count > 0 then last.throughput_sum / last.throughput_count else null end,
      'uptime_pct', case when last.requests > 0 then last.successful_requests * 100.0 / last.requests else null end
    ),
    'prev_24h', jsonb_build_object(
      'total_requests', coalesce(previous.requests, 0), 'successful_requests', coalesce(previous.successful_requests, 0),
      'avg_latency_ms', case when previous.latency_count > 0 then previous.latency_sum_ms / previous.latency_count else null end,
      'avg_generation_ms', case when previous.generation_count > 0 then previous.generation_sum_ms / previous.generation_count else null end,
      'avg_throughput', case when previous.throughput_count > 0 then previous.throughput_sum / previous.throughput_count else null end,
      'uptime_pct', case when previous.requests > 0 then previous.successful_requests * 100.0 / previous.requests else null end
    ),
    'hourly_24h', coalesce((select value from success_buckets), '[]'::jsonb),
    'provider_uptime_24h', coalesce((select value from provider_json), '[]'::jsonb),
    'time_of_day_5d', '[]'::jsonb,
    'cumulative_tokens', null,
    'cloudflare_colo', nullif(upper(trim(p_cloudflare_colo)), '')
  )
  from last_day last cross join previous_day previous;
$$;


--
-- Name: get_v2_model_performance_overview(text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_performance_overview(p_model_slug text, p_cloudflare_colo text DEFAULT NULL::text, p_percentile numeric DEFAULT 0.5) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with params as (
    select lower(trim(p_model_slug)) as model_slug,
      nullif(upper(trim(p_cloudflare_colo)), '') as cloudflare_colo,
      greatest(0.01, least(0.99, coalesce(p_percentile, 0.5)))::double precision as percentile,
      now() as now_ts
  ),
  base as (
    select date_trunc('hour', fact.occurred_at) as bucket_start,
      fact.occurred_at::date as usage_day,
      route.provider_slug as provider_id,
      fact.success, fact.latency_ms, fact.generation_ms, fact.throughput
    from public.v2_request_facts fact
    left join public.v2_model_provider_routes route
      on route.provider_model_id = fact.provider_model_id
    cross join params
    where coalesce(fact.routed_model_slug, fact.requested_model_slug) = params.model_slug
      and fact.occurred_at >= params.now_ts - interval '7 days'
      and (params.cloudflare_colo is null or upper(trim(fact.cloudflare_colo)) = params.cloudflare_colo)
  ),
  hourly as (
    select bucket_start,
      count(*)::bigint as requests,
      count(*) filter (where success is true)::bigint as successful_requests,
      percentile_cont((select percentile from params)) within group (order by latency_ms) filter (where success is true and latency_ms is not null)::numeric as percentile_latency_ms,
      avg(generation_ms) filter (where success is true and generation_ms is not null)::numeric as avg_generation_ms,
      percentile_cont((select percentile from params)) within group (order by throughput) filter (where success is true and throughput is not null)::numeric as percentile_throughput
    from base
    group by bucket_start
  ),
  recent as (
    select * from base where bucket_start >= (select now_ts from params) - interval '24 hours'
  ),
  summary as (
    select count(*)::bigint as requests, count(*) filter (where success is true)::bigint as successful_requests,
      percentile_cont((select percentile from params)) within group (order by latency_ms) filter (where success is true and latency_ms is not null)::numeric as percentile_latency_ms,
      avg(generation_ms) filter (where success is true and generation_ms is not null)::numeric as avg_generation_ms,
      percentile_cont((select percentile from params)) within group (order by throughput) filter (where success is true and throughput is not null)::numeric as percentile_throughput
    from recent
  ),
  previous as (
    select count(*)::bigint as requests, count(*) filter (where success is true)::bigint as successful_requests,
      percentile_cont((select percentile from params)) within group (order by latency_ms) filter (where success is true and latency_ms is not null)::numeric as percentile_latency_ms,
      avg(generation_ms) filter (where success is true and generation_ms is not null)::numeric as avg_generation_ms,
      percentile_cont((select percentile from params)) within group (order by throughput) filter (where success is true and throughput is not null)::numeric as percentile_throughput
    from base
    where bucket_start >= (select now_ts from params) - interval '48 hours'
      and bucket_start < (select now_ts from params) - interval '24 hours'
  ),
  provider_rows as (
    select provider_id, count(*)::bigint as requests, count(*) filter (where success is true)::bigint as successful_requests,
      percentile_cont((select percentile from params)) within group (order by latency_ms) filter (where success is true and latency_ms is not null)::numeric as percentile_latency_ms,
      avg(generation_ms) filter (where success is true and generation_ms is not null)::numeric as avg_generation_ms,
      percentile_cont((select percentile from params)) within group (order by throughput) filter (where success is true and throughput is not null)::numeric as percentile_throughput
    from recent
    where provider_id is not null
    group by provider_id
  ),
  provider_daily as (
    select usage_day, provider_id, count(*)::bigint as requests,
      percentile_cont((select percentile from params)) within group (order by latency_ms) filter (where success is true and latency_ms is not null)::numeric as percentile_latency_ms,
      avg(generation_ms) filter (where success is true and generation_ms is not null)::numeric as avg_generation_ms,
      percentile_cont((select percentile from params)) within group (order by throughput) filter (where success is true and throughput is not null)::numeric as percentile_throughput
    from base
    where provider_id is not null
    group by usage_day, provider_id
  ),
  hourly_json as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'bucket', bucket_start, 'requests', requests,
      'success_pct', case when requests > 0 then successful_requests * 100.0 / requests else null end,
      'avg_latency_ms', percentile_latency_ms, 'avg_generation_ms', avg_generation_ms, 'avg_throughput', percentile_throughput
    ) order by bucket_start) filter (where bucket_start >= (select now_ts from params) - interval '24 hours'), '[]'::jsonb) as value
    from hourly
  ),
  provider_json as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'provider', p.provider_id, 'provider_name', v.name, 'requests', p.requests,
      'uptime_pct', case when p.requests > 0 then p.successful_requests * 100.0 / p.requests else null end,
      'avg_latency_ms', p.percentile_latency_ms, 'avg_generation_ms', p.avg_generation_ms, 'avg_throughput', p.percentile_throughput,
      'uptime_buckets', '[]'::jsonb
    ) order by p.requests desc, p.provider_id), '[]'::jsonb) as value
    from provider_rows p
    join public.v2_providers v on v.provider_slug = p.provider_id
  ),
  provider_daily_json as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'day', d.usage_day, 'provider', d.provider_id, 'provider_name', v.name,
      'requests', d.requests, 'avg_latency_ms', d.percentile_latency_ms, 'avg_generation_ms', d.avg_generation_ms,
      'avg_throughput', d.percentile_throughput
    ) order by d.usage_day, d.provider_id), '[]'::jsonb) as value
    from provider_daily d
    join public.v2_providers v on v.provider_slug = d.provider_id
  )
  select jsonb_build_object(
    'percentile', (select percentile from params) * 100,
    'last_24h', jsonb_build_object(
      'total_requests', coalesce(summary.requests, 0), 'successful_requests', coalesce(summary.successful_requests, 0),
      'avg_latency_ms', summary.percentile_latency_ms, 'avg_generation_ms', summary.avg_generation_ms,
      'avg_throughput', summary.percentile_throughput,
      'uptime_pct', case when summary.requests > 0 then summary.successful_requests * 100.0 / summary.requests else null end
    ),
    'prev_24h', jsonb_build_object(
      'total_requests', coalesce(previous.requests, 0), 'successful_requests', coalesce(previous.successful_requests, 0),
      'avg_latency_ms', previous.percentile_latency_ms, 'avg_generation_ms', previous.avg_generation_ms,
      'avg_throughput', previous.percentile_throughput,
      'uptime_pct', case when previous.requests > 0 then previous.successful_requests * 100.0 / previous.requests else null end
    ),
    'hourly_24h', (select value from hourly_json),
    'provider_uptime_24h', (select value from provider_json),
    'provider_daily_7d', (select value from provider_daily_json),
    'time_of_day_5d', '[]'::jsonb,
    'cumulative_tokens', null,
    'cloudflare_colo', (select cloudflare_colo from params)
  )
  from summary cross join previous;
$$;


--
-- Name: FUNCTION get_v2_model_performance_overview(p_model_slug text, p_cloudflare_colo text, p_percentile numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_v2_model_performance_overview(p_model_slug text, p_cloudflare_colo text, p_percentile numeric) IS 'Returns model performance percentiles; provider series include only real v2 catalogue providers.';


--
-- Name: get_v2_model_pricing(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_pricing(p_model_slug text, p_region text DEFAULT NULL::text, p_service_tier text DEFAULT NULL::text) RETURNS SETOF jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with eligible_variants as (
    select variant.variant_id, variant.provider_model_id, variant.service_tier_slug,
      variant.execution_region, variant.data_region
    from public.v2_route_variants variant
    where variant.status <> 'disabled'
      and (p_region is null or lower(p_region) = lower(coalesce(variant.execution_region, ''))
        or lower(p_region) = lower(coalesce(variant.data_region, '')))
      and (p_service_tier is null or variant.service_tier_slug = lower(p_service_tier))
  ),
  provider_models as (
    select
      route.provider_slug,
      provider.name as provider_name,
      provider.status as provider_status,
      provider.routing_enabled as provider_routing_enabled,
      route.provider_model_id,
      route.model_slug,
      route.provider_model_slug,
      route.status as route_status,
      route.routing_enabled as route_routing_enabled,
      route.provider_availability_status,
      route.phaseo_status,
      route.access_scope,
      route.input_modalities,
      route.output_modalities,
      route.context_length,
      route.max_output_tokens,
      variant.variant_id,
      variant.service_tier_slug,
      variant.execution_region,
      variant.data_region,
      capability.capability_id,
      capability.status as capability_status,
      capability.params,
      capability.max_input_tokens,
      capability.max_output_tokens as capability_max_output_tokens
    from public.v2_model_provider_routes route
    join public.v2_providers provider on provider.provider_slug = route.provider_slug
    join eligible_variants variant on variant.provider_model_id = route.provider_model_id
    left join public.v2_route_capabilities capability on capability.provider_model_id = route.provider_model_id
    where route.model_slug = lower(trim(p_model_slug))
      and route.status <> 'disabled'
      and provider.status <> 'disabled'
      and route.access_scope = 'public'
      and coalesce(capability.status, 'active') <> 'internal_testing'
  ),
  grouped as (
    select
      model.provider_slug,
      max(model.provider_name) as provider_name,
      max(model.provider_status) as provider_status,
      bool_or(model.provider_routing_enabled) as provider_routing_enabled,
      jsonb_agg(distinct jsonb_build_object(
        'id', model.provider_model_id,
        'api_provider_id', model.provider_slug,
        'provider_model_slug', model.provider_model_slug,
        'model_id', model.model_slug,
        'endpoint', coalesce(model.capability_id, 'unmapped'),
        'capability_status', model.capability_status,
        'routing_status', model.route_status,
        'is_active_gateway', model.route_status in ('active', 'degraded')
          and model.route_routing_enabled
          and model.provider_routing_enabled
          and model.phaseo_status = 'enabled'
          and model.provider_availability_status in ('available', 'preview', 'limited_access'),
        'provider_availability_status', model.provider_availability_status,
        'phaseo_status', model.phaseo_status,
        'access_scope', model.access_scope,
        'input_modalities', array_to_string(model.input_modalities, ','),
        'output_modalities', array_to_string(model.output_modalities, ','),
        'context_length', model.context_length,
        'max_input_tokens', model.max_input_tokens,
        'max_output_tokens', coalesce(model.capability_max_output_tokens, model.max_output_tokens),
        'params', model.params,
        'service_tier', model.service_tier_slug,
        'execution_region', model.execution_region,
        'data_region', model.data_region
      )) as provider_models,
      coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', sku.sku_id,
          'model_key', model.provider_slug || ':' || route.model_slug || ':' || sku.operation,
          'capability_id', sku.operation,
          'pricing_plan', sku.service_tier_slug,
          'meter', meter.meter_key,
          'unit', meter.unit,
          'unit_size', meter.unit_quantity,
          'price_per_unit', meter.price_nanos / 1000000000.0,
          'included_quantity', coalesce(nullif(meter.metadata->>'included_quantity', '')::numeric, nullif(sku.metadata->>'included_quantity', '')::numeric, 0),
          'currency', sku.currency,
          'priority', meter.meter_order,
          'effective_from', sku.effective_from,
          'effective_to', sku.effective_to,
          'note', sku.description,
          'match', coalesce(sku.metadata->'match', '[]'::jsonb),
          'billing_timestamp_basis', coalesce(
            sku.metadata->>'billing_timestamp_basis',
            meter.metadata->>'billing_timestamp_basis',
            'request_start'
          ),
          'time_windows', coalesce(
            sku.metadata->'time_windows',
            meter.metadata->'time_windows',
            '[]'::jsonb
          )
        ) order by meter.meter_order, meter.meter_key)
        from public.v2_pricing_skus sku
        join public.v2_pricing_sku_meters meter on meter.sku_id = sku.sku_id
        join public.v2_model_provider_routes route on route.provider_model_id = sku.provider_model_id
        where route.model_slug = lower(trim(p_model_slug))
          and route.access_scope = 'public'
          and sku.provider_model_id in (
            select provider_model_id
            from provider_models
            where provider_slug = model.provider_slug
          )
          and sku.status <> 'disabled'
          and sku.effective_from <= now()
          and (sku.effective_to is null or sku.effective_to > now())
          and (p_service_tier is null or sku.service_tier_slug = lower(p_service_tier))
      ), '[]'::jsonb) as pricing_rules
    from provider_models model
    group by model.provider_slug
  )
  select jsonb_build_object(
    'provider', jsonb_build_object(
      'api_provider_id', grouped.provider_slug,
      'api_provider_name', grouped.provider_name,
      'status', grouped.provider_status,
      'routing_status', case when grouped.provider_routing_enabled then 'active' else 'disabled' end
    ),
    'provider_models', grouped.provider_models,
    'pricing_rules', grouped.pricing_rules
  )
  from grouped
  order by grouped.provider_name;
$$;


--
-- Name: get_v2_model_provider_health(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_provider_health(p_model_slug text, p_window_days integer DEFAULT 3) RETURNS TABLE(provider_id text, provider_name text, requests bigint, success_requests bigint, failed_requests bigint, health_requests bigint, health_success_requests bigint, failed_attempts bigint, fallback_attempts bigint, uptime_pct numeric, request_success_pct numeric, failure_pct numeric, avg_latency_ms numeric, buckets jsonb, last_request_at date)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select health.provider_slug, max(provider.name), sum(health.request_count)::bigint,
    sum(health.successful_request_count)::bigint, sum(health.request_count - health.successful_request_count)::bigint,
    sum(health.attempt_count)::bigint, sum(health.successful_attempts)::bigint, sum(health.failed_attempts)::bigint,
    sum(health.fallback_attempts)::bigint,
    case when sum(health.attempt_count) > 0 then sum(health.successful_attempts) * 100.0 / sum(health.attempt_count) else null end,
    case when sum(health.request_count) > 0 then sum(health.successful_request_count) * 100.0 / sum(health.request_count) else null end,
    case when sum(health.attempt_count) > 0 then sum(health.failed_attempts) * 100.0 / sum(health.attempt_count) else null end,
    case when sum(health.latency_count) > 0 then sum(health.latency_sum_ms)::numeric / sum(health.latency_count) else null end,
    jsonb_agg(jsonb_build_object('day', health.usage_date, 'requests', health.request_count, 'attempts', health.attempt_count,
      'successful_attempts', health.successful_attempts, 'failed_attempts', health.failed_attempts,
      'fallback_attempts', health.fallback_attempts) order by health.usage_date), max(health.usage_date)
  from public.v2_public_provider_health_daily health
  left join public.v2_providers provider on provider.provider_slug = health.provider_slug
  where health.model_slug = lower(trim(p_model_slug))
    and health.usage_date >= current_date - greatest(1, least(coalesce(p_window_days, 3), 90))
  group by health.provider_slug
  order by sum(health.failed_attempts) desc, health.provider_slug;
$$;


--
-- Name: get_v2_model_provider_health_metrics(text, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_provider_health_metrics(p_model_slug text, p_window_days integer DEFAULT 3, p_percentile numeric DEFAULT 0.5) RETURNS TABLE(provider_id text, provider_name text, requests bigint, requests_30m bigint, success_requests bigint, failed_requests bigint, neutral_requests bigint, rate_limited_requests bigint, health_requests bigint, health_success_requests bigint, uptime_pct numeric, request_success_pct numeric, avg_latency_ms_30m numeric, avg_throughput_30m numeric, percentile_latency_ms_30m numeric, percentile_throughput_30m numeric, avg_latency_ms numeric, p50_latency_ms numeric, p95_latency_ms numeric, percentile_latency_ms numeric, avg_generation_ms numeric, avg_throughput numeric, percentile_throughput numeric, total_tokens bigint, input_tokens_1h bigint, output_tokens_1h bigint, cached_read_tokens_1h bigint, input_tokens bigint, output_tokens bigint, finish_reason_counts jsonb, error_code_counts jsonb, buckets jsonb, last_request_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
select health.*
from public.v2_models model
cross join lateral public.get_v2_model_provider_health_metrics_unfiltered(
  model.model_slug,
  p_window_days,
  p_percentile
) health
where model.model_slug = lower(trim(p_model_slug))
  and model.hidden = false
  and model.status <> 'disabled';
$$;


--
-- Name: get_v2_model_provider_health_metrics_unfiltered(text, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_provider_health_metrics_unfiltered(p_model_slug text, p_window_days integer DEFAULT 3, p_percentile numeric DEFAULT 0.5) RETURNS TABLE(provider_id text, provider_name text, requests bigint, requests_30m bigint, success_requests bigint, failed_requests bigint, neutral_requests bigint, rate_limited_requests bigint, health_requests bigint, health_success_requests bigint, uptime_pct numeric, request_success_pct numeric, avg_latency_ms_30m numeric, avg_throughput_30m numeric, percentile_latency_ms_30m numeric, percentile_throughput_30m numeric, avg_latency_ms numeric, p50_latency_ms numeric, p95_latency_ms numeric, percentile_latency_ms numeric, avg_generation_ms numeric, avg_throughput numeric, percentile_throughput numeric, total_tokens bigint, input_tokens_1h bigint, output_tokens_1h bigint, cached_read_tokens_1h bigint, input_tokens bigint, output_tokens bigint, finish_reason_counts jsonb, error_code_counts jsonb, buckets jsonb, last_request_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with params as (
    select
      lower(trim(p_model_slug)) as model_slug,
      greatest(0.01, least(0.99, coalesce(p_percentile, 0.5)))::double precision as percentile,
      greatest(1, least(coalesce(p_window_days, 3), 90))::integer as window_days,
      now() as now_ts
  ),
  base as (
    select
      coalesce(route.provider_slug, fact.provider_model_id, 'unknown') as provider_id,
      fact.occurred_at,
      fact.success,
      fact.status_code,
      lower(coalesce(fact.error_code, '')) as error_code,
      fact.latency_ms,
      fact.generation_ms,
      fact.throughput
    from public.v2_request_facts fact
    left join public.v2_model_provider_routes route
      on route.provider_model_id = fact.provider_model_id
    cross join params
    where coalesce(fact.routed_model_slug, fact.requested_model_slug) = params.model_slug
      and fact.occurred_at >= params.now_ts - make_interval(days => params.window_days)
      and fact.provider_model_id is not null
  ),
  classified as (
    select base.*,
      case
        when base.success is true then 'success'
        when base.status_code = 429
          or base.error_code like '%rate limit%'
          or base.error_code like '%rate_limit%'
          or base.error_code like '%ratelimit%'
          or base.error_code like '%too many requests%'
          or base.error_code like '%quota exceeded%'
        then 'neutral'
        when base.error_code like '%abort%'
          or base.error_code like '%cancel%'
          or base.error_code like '%client_closed%'
        then 'neutral'
        else 'failure'
      end as health_outcome,
      (base.status_code = 429
        or base.error_code like '%rate limit%'
        or base.error_code like '%rate_limit%'
        or base.error_code like '%ratelimit%'
        or base.error_code like '%too many requests%'
        or base.error_code like '%quota exceeded%') as is_rate_limited
    from base
  ),
  aggregates as (
    select
      c.provider_id,
      count(*)::bigint as requests,
      count(*) filter (where c.occurred_at >= (select now_ts from params) - interval '30 minutes')::bigint as requests_30m,
      count(*) filter (where c.success is true)::bigint as success_requests,
      count(*) filter (where c.health_outcome = 'failure')::bigint as failed_requests,
      count(*) filter (where c.health_outcome = 'neutral')::bigint as neutral_requests,
      count(*) filter (where c.is_rate_limited)::bigint as rate_limited_requests,
      count(*) filter (where c.health_outcome <> 'neutral')::bigint as health_requests,
      count(*) filter (where c.health_outcome = 'success')::bigint as health_success_requests,
      avg(c.latency_ms) filter (where c.success is true and c.latency_ms is not null and c.occurred_at >= (select now_ts from params) - interval '30 minutes')::numeric as avg_latency_ms_30m,
      avg(c.throughput) filter (where c.success is true and c.throughput is not null and c.occurred_at >= (select now_ts from params) - interval '30 minutes')::numeric as avg_throughput_30m,
      percentile_cont((select percentile from params)) within group (order by c.latency_ms) filter (where c.success is true and c.latency_ms is not null and c.occurred_at >= (select now_ts from params) - interval '30 minutes')::numeric as percentile_latency_ms_30m,
      percentile_cont((select percentile from params)) within group (order by c.throughput) filter (where c.success is true and c.throughput is not null and c.occurred_at >= (select now_ts from params) - interval '30 minutes')::numeric as percentile_throughput_30m,
      avg(c.latency_ms) filter (where c.success is true and c.latency_ms is not null)::numeric as avg_latency_ms,
      percentile_cont(0.5) within group (order by c.latency_ms) filter (where c.success is true and c.latency_ms is not null)::numeric as p50_latency_ms,
      percentile_cont(0.95) within group (order by c.latency_ms) filter (where c.success is true and c.latency_ms is not null)::numeric as p95_latency_ms,
      percentile_cont((select percentile from params)) within group (order by c.latency_ms) filter (where c.success is true and c.latency_ms is not null)::numeric as percentile_latency_ms,
      avg(c.generation_ms) filter (where c.success is true and c.generation_ms is not null)::numeric as avg_generation_ms,
      avg(c.throughput) filter (where c.success is true and c.throughput is not null)::numeric as avg_throughput,
      percentile_cont((select percentile from params)) within group (order by c.throughput) filter (where c.success is true and c.throughput is not null)::numeric as percentile_throughput,
      max(c.occurred_at) as last_request_at
    from classified c
    group by c.provider_id
  ),
  bucketed as (
    select c.provider_id,
      jsonb_agg(jsonb_build_object(
        'start', c.bucket_start,
        'end', c.bucket_start + interval '1 hour',
        'requests', c.requests,
        'success_requests', c.success_requests,
        'health_requests', c.health_requests,
        'health_success_requests', c.health_success_requests,
        'uptime_pct', case when c.health_requests > 0 then round(c.health_success_requests::numeric / c.health_requests::numeric * 100, 2) else null end,
        'request_success_pct', case when c.requests > 0 then round(c.success_requests::numeric / c.requests::numeric * 100, 2) else null end,
        'avg_latency_ms', c.percentile_latency_ms,
        'avg_throughput', c.percentile_throughput
      ) order by c.bucket_start) as buckets
    from (
      select provider_id, date_trunc('hour', occurred_at) as bucket_start,
        count(*)::bigint as requests,
        count(*) filter (where success is true)::bigint as success_requests,
        count(*) filter (where health_outcome <> 'neutral')::bigint as health_requests,
        count(*) filter (where health_outcome = 'success')::bigint as health_success_requests,
        percentile_cont((select percentile from params)) within group (order by latency_ms) filter (where success is true and latency_ms is not null)::numeric as percentile_latency_ms,
        percentile_cont((select percentile from params)) within group (order by throughput) filter (where success is true and throughput is not null)::numeric as percentile_throughput
      from classified
      group by provider_id, bucket_start
    ) c
    group by c.provider_id
  )
  select
    a.provider_id,
    coalesce(provider.name, a.provider_id) as provider_name,
    a.requests, a.requests_30m, a.success_requests, a.failed_requests, a.neutral_requests,
    a.rate_limited_requests, a.health_requests, a.health_success_requests,
    case when a.health_requests > 0 then round(a.health_success_requests::numeric / a.health_requests::numeric * 100, 2) else null end,
    case when a.requests > 0 then round(a.success_requests::numeric / a.requests::numeric * 100, 2) else null end,
    round(a.avg_latency_ms_30m, 2), round(a.avg_throughput_30m, 2), round(a.percentile_latency_ms_30m, 2), round(a.percentile_throughput_30m, 2),
    round(a.avg_latency_ms, 2), round(a.p50_latency_ms, 2), round(a.p95_latency_ms, 2), round(a.percentile_latency_ms, 2),
    round(a.avg_generation_ms, 2), round(a.avg_throughput, 2), round(a.percentile_throughput, 2),
    0::bigint, 0::bigint, 0::bigint, 0::bigint, 0::bigint, 0::bigint,
    '{}'::jsonb, '{}'::jsonb, coalesce(bucketed.buckets, '[]'::jsonb), a.last_request_at
  from aggregates a
  left join public.v2_providers provider on provider.provider_slug = a.provider_id
  left join bucketed on bucketed.provider_id = a.provider_id
  order by a.requests desc, a.provider_id;
$$;


--
-- Name: get_v2_model_provider_percentile_series(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_provider_percentile_series(p_model_slug text, p_cloudflare_colo text DEFAULT NULL::text) RETURNS TABLE(usage_day date, provider_id text, provider_name text, requests bigint, latency_p50 numeric, latency_p75 numeric, latency_p90 numeric, latency_p95 numeric, latency_p99 numeric, generation_p50 numeric, generation_p75 numeric, generation_p90 numeric, generation_p95 numeric, generation_p99 numeric, throughput_p50 numeric, throughput_p75 numeric, throughput_p90 numeric, throughput_p95 numeric, throughput_p99 numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select
    fact.occurred_at::date as usage_day,
    provider.provider_slug as provider_id,
    provider.name as provider_name,
    count(*)::bigint as requests,
    percentile_cont(0.50) within group (order by fact.latency_ms)
      filter (where fact.success is true and fact.latency_ms is not null)::numeric as latency_p50,
    percentile_cont(0.75) within group (order by fact.latency_ms)
      filter (where fact.success is true and fact.latency_ms is not null)::numeric as latency_p75,
    percentile_cont(0.90) within group (order by fact.latency_ms)
      filter (where fact.success is true and fact.latency_ms is not null)::numeric as latency_p90,
    percentile_cont(0.95) within group (order by fact.latency_ms)
      filter (where fact.success is true and fact.latency_ms is not null)::numeric as latency_p95,
    percentile_cont(0.99) within group (order by fact.latency_ms)
      filter (where fact.success is true and fact.latency_ms is not null)::numeric as latency_p99,
    percentile_cont(0.50) within group (order by fact.generation_ms)
      filter (where fact.success is true and fact.generation_ms is not null)::numeric as generation_p50,
    percentile_cont(0.75) within group (order by fact.generation_ms)
      filter (where fact.success is true and fact.generation_ms is not null)::numeric as generation_p75,
    percentile_cont(0.90) within group (order by fact.generation_ms)
      filter (where fact.success is true and fact.generation_ms is not null)::numeric as generation_p90,
    percentile_cont(0.95) within group (order by fact.generation_ms)
      filter (where fact.success is true and fact.generation_ms is not null)::numeric as generation_p95,
    percentile_cont(0.99) within group (order by fact.generation_ms)
      filter (where fact.success is true and fact.generation_ms is not null)::numeric as generation_p99,
    percentile_cont(0.50) within group (order by fact.throughput)
      filter (where fact.success is true and fact.throughput is not null)::numeric as throughput_p50,
    percentile_cont(0.75) within group (order by fact.throughput)
      filter (where fact.success is true and fact.throughput is not null)::numeric as throughput_p75,
    percentile_cont(0.90) within group (order by fact.throughput)
      filter (where fact.success is true and fact.throughput is not null)::numeric as throughput_p90,
    percentile_cont(0.95) within group (order by fact.throughput)
      filter (where fact.success is true and fact.throughput is not null)::numeric as throughput_p95,
    percentile_cont(0.99) within group (order by fact.throughput)
      filter (where fact.success is true and fact.throughput is not null)::numeric as throughput_p99
  from public.v2_request_facts fact
  join public.v2_model_provider_routes route
    on route.provider_model_id = fact.provider_model_id
  join public.v2_providers provider
    on provider.provider_slug = route.provider_slug
  where coalesce(fact.routed_model_slug, fact.requested_model_slug) = lower(trim(p_model_slug))
    and fact.occurred_at >= now() - interval '7 days'
    and (
      nullif(upper(trim(p_cloudflare_colo)), '') is null
      or upper(trim(fact.cloudflare_colo)) = upper(trim(p_cloudflare_colo))
    )
  group by fact.occurred_at::date, provider.provider_slug, provider.name
  order by usage_day, provider.provider_slug;
$$;


--
-- Name: FUNCTION get_v2_model_provider_percentile_series(p_model_slug text, p_cloudflare_colo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_v2_model_provider_percentile_series(p_model_slug text, p_cloudflare_colo text) IS 'Returns P50/P75/P90/P95/P99 provider performance series for single-provider model charts.';


--
-- Name: get_v2_model_provider_percentile_series_v2(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_provider_percentile_series_v2(p_model_slug text, p_cloudflare_colo text DEFAULT NULL::text, p_stream_mode text DEFAULT 'all'::text, p_context_bucket text DEFAULT 'all'::text) RETURNS TABLE(usage_day date, provider_id text, provider_name text, requests bigint, percentile integer, gateway_ttft_ms numeric, provider_duration_ms numeric, effective_throughput_tps numeric, output_speed_tps numeric, phaseo_overhead_ms numeric, tpot_ms numeric, itl_ms numeric, cached_input_pct numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
select series.*
from public.v2_models model
cross join lateral public.get_v2_model_provider_percentile_series_v2_unsuppressed(
  model.model_slug,
  p_cloudflare_colo,
  p_stream_mode,
  p_context_bucket
) series
where model.model_slug = lower(trim(p_model_slug))
  and model.hidden = false
  and model.status <> 'disabled'
  and series.requests >= 20;
$$;


--
-- Name: FUNCTION get_v2_model_provider_percentile_series_v2(p_model_slug text, p_cloudflare_colo text, p_stream_mode text, p_context_bucket text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_v2_model_provider_percentile_series_v2(p_model_slug text, p_cloudflare_colo text, p_stream_mode text, p_context_bucket text) IS 'Returns daily single-provider performance percentiles, including cached-input share only for cohorts with at least 20 cache telemetry observations.';


--
-- Name: get_v2_model_provider_percentile_series_v2_unsuppressed(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_provider_percentile_series_v2_unsuppressed(p_model_slug text, p_cloudflare_colo text DEFAULT NULL::text, p_stream_mode text DEFAULT 'all'::text, p_context_bucket text DEFAULT 'all'::text) RETURNS TABLE(usage_day date, provider_id text, provider_name text, requests bigint, percentile integer, gateway_ttft_ms numeric, provider_duration_ms numeric, effective_throughput_tps numeric, output_speed_tps numeric, phaseo_overhead_ms numeric, tpot_ms numeric, itl_ms numeric, cached_input_pct numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
with percentile_values(percentile) as (
  values (1), (5), (10), (25), (50), (75), (90), (95), (99)
),
scoped_facts as (
  select fact.request_event_id
  from public.v2_request_facts fact
  where coalesce(fact.routed_model_slug, fact.requested_model_slug) = lower(trim(p_model_slug))
    and fact.occurred_at >= now() - interval '7 days'
),
usage_tokens as (
  select
    usage.request_event_id,
    sum(usage.quantity) filter (
      where usage.meter_key in ('input_tokens', 'input_text_tokens', 'prompt_tokens')
    )::numeric input_tokens,
    sum(usage.quantity) filter (
      where usage.meter_key = 'cached_input_tokens'
    )::numeric cached_input_tokens,
    bool_or(usage.meter_key = 'cached_input_tokens') cache_telemetry_observed
  from public.v2_request_usage usage
  join scoped_facts on scoped_facts.request_event_id = usage.request_event_id
  where usage.meter_key in (
    'input_tokens',
    'input_text_tokens',
    'prompt_tokens',
    'cached_input_tokens'
  )
  group by usage.request_event_id
),
base as (
  select
    fact.occurred_at::date usage_day,
    provider.provider_slug provider_id,
    provider.name provider_name,
    fact.success,
    fact.stream,
    tokens.input_tokens,
    fact.gateway_ttft_ms,
    fact.generation_ms provider_duration_ms,
    fact.throughput effective_throughput_tps,
    fact.output_speed_tps,
    fact.phaseo_overhead_ms,
    fact.tpot_ms,
    fact.itl_ms,
    case
      when not coalesce(tokens.cache_telemetry_observed, false)
        or tokens.input_tokens is null
        or tokens.input_tokens <= 0
        then null
      else least(
        100,
        coalesce(tokens.cached_input_tokens, 0) * 100.0 /
          case
            when coalesce(
              (fact.safe_metadata ->> 'cached_input_tokens_are_subset_of_input')::boolean,
              true
            ) then tokens.input_tokens
            else tokens.input_tokens + coalesce(tokens.cached_input_tokens, 0)
          end
      )
    end cached_input_pct
  from public.v2_request_facts fact
  join public.v2_model_provider_routes route
    on route.provider_model_id = fact.provider_model_id
  join public.v2_providers provider
    on provider.provider_slug = route.provider_slug
  left join usage_tokens tokens
    on tokens.request_event_id = fact.request_event_id
  where coalesce(fact.routed_model_slug, fact.requested_model_slug) = lower(trim(p_model_slug))
    and fact.occurred_at >= now() - interval '7 days'
    and (
      nullif(upper(trim(p_cloudflare_colo)), '') is null
      or upper(trim(fact.cloudflare_colo)) = upper(trim(p_cloudflare_colo))
    )
    and (
      lower(p_stream_mode) not in ('stream', 'non_stream')
      or fact.stream = (lower(p_stream_mode) = 'stream')
    )
    and (
      lower(p_context_bucket) not in ('lte_4k', '4k_16k', '16k_64k', 'gt_64k')
      or (lower(p_context_bucket) = 'lte_4k' and tokens.input_tokens <= 4096)
      or (lower(p_context_bucket) = '4k_16k' and tokens.input_tokens > 4096 and tokens.input_tokens <= 16384)
      or (lower(p_context_bucket) = '16k_64k' and tokens.input_tokens > 16384 and tokens.input_tokens <= 65536)
      or (lower(p_context_bucket) = 'gt_64k' and tokens.input_tokens > 65536)
    )
)
select
  base.usage_day,
  base.provider_id,
  base.provider_name,
  count(*)::bigint requests,
  p.percentile,
  percentile_cont(p.percentile / 100.0) within group (order by base.gateway_ttft_ms)
    filter (where base.success and base.gateway_ttft_ms is not null)::numeric,
  percentile_cont(p.percentile / 100.0) within group (order by base.provider_duration_ms)
    filter (where base.success and base.provider_duration_ms is not null)::numeric,
  percentile_cont(p.percentile / 100.0) within group (order by base.effective_throughput_tps)
    filter (where base.success and base.effective_throughput_tps is not null)::numeric,
  percentile_cont(p.percentile / 100.0) within group (order by base.output_speed_tps)
    filter (where base.success and base.output_speed_tps is not null)::numeric,
  percentile_cont(p.percentile / 100.0) within group (order by base.phaseo_overhead_ms)
    filter (where base.success and base.phaseo_overhead_ms is not null)::numeric,
  percentile_cont(p.percentile / 100.0) within group (order by base.tpot_ms)
    filter (where base.success and base.tpot_ms is not null)::numeric,
  percentile_cont(p.percentile / 100.0) within group (order by base.itl_ms)
    filter (where base.success and base.itl_ms is not null)::numeric,
  case
    when count(base.cached_input_pct) >= 20 then
      percentile_cont(p.percentile / 100.0) within group (order by base.cached_input_pct)
        filter (where base.cached_input_pct is not null)::numeric
    else null
  end
from base
cross join percentile_values p
group by base.usage_day, base.provider_id, base.provider_name, p.percentile
order by base.usage_day, base.provider_id, p.percentile;
$$;


--
-- Name: get_v2_model_resolution(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_resolution(p_requested_slug text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with requested as (select lower(trim(p_requested_slug)) as slug),
  direct as (
    select model.model_slug
    from public.v2_models model, requested
    where model.model_slug = requested.slug
      and model.hidden = false and model.status <> 'disabled'
    limit 1
  ),
  alias as (
    select alias.model_slug
    from public.v2_model_aliases alias, requested
    where alias.alias_slug = requested.slug and alias.enabled = true
      and (alias.effective_from is null or alias.effective_from <= now())
      and (alias.effective_to is null or alias.effective_to > now())
    limit 1
  ),
  route as (
    select route.model_slug
    from public.v2_model_provider_routes route, requested
    where route.provider_model_id = requested.slug
       or route.provider_model_slug = requested.slug
    order by route.status = 'active' desc, route.provider_model_id
    limit 1
  )
  select jsonb_build_object(
    'requestedModelId', p_requested_slug,
    'canonicalModelId', coalesce((select model_slug from direct), (select model_slug from alias), (select model_slug from route)),
    'internalModelId', coalesce((select model_slug from direct), (select model_slug from alias), (select model_slug from route)),
    'source', case
      when exists (select 1 from direct) then 'direct'
      when exists (select 1 from alias) then 'alias'
      when exists (select 1 from route) then 'provider_mapping'
      else 'unresolved'
    end
  );
$$;


--
-- Name: get_v2_model_subscription_plans(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_subscription_plans(p_model_slug text) RETURNS TABLE(plan_uuid uuid, plan_id text, name text, lab_slug text, description text, link text, other_info jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, model_info jsonb, rate_limit jsonb, model_other_info jsonb, price numeric, currency text, frequency text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select plan.plan_uuid, plan.plan_id, plan.name, plan.lab_slug, plan.description, plan.link, plan.other_info,
    plan.created_at, plan.updated_at, relation.model_info, relation.rate_limit, relation.other_info,
    plan.price, plan.currency, plan.frequency
  from public.v2_subscription_plan_models relation
  join public.v2_subscription_plans plan on plan.plan_uuid = relation.plan_uuid
  where relation.model_slug = lower(trim(p_model_slug))
  order by plan.plan_id, plan.frequency;
$$;


--
-- Name: get_v2_model_usage_daily(text, text[], date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_usage_daily(p_model_slug text, p_provider_ids text[] DEFAULT NULL::text[], p_since date DEFAULT NULL::date, p_until date DEFAULT NULL::date) RETURNS TABLE(day_bucket date, model_id text, provider_id text, endpoint text, requests bigint, success_requests bigint, failed_requests bigint, neutral_requests bigint, rate_limited_requests bigint, total_tokens numeric, input_tokens numeric, output_tokens numeric, reasoning_tokens numeric, cached_read_tokens numeric, input_characters numeric, output_characters numeric, total_characters numeric, image_inputs numeric, image_outputs numeric, audio_inputs numeric, audio_outputs numeric, video_inputs numeric, video_outputs numeric, total_cost_nanos numeric, avg_latency_ms numeric, avg_generation_ms numeric, avg_throughput numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with base as (
    select
      usage.usage_date as day_bucket,
      usage.model_slug as model_id,
      coalesce(route.provider_slug, usage.provider_model_id, '') as provider_id,
      usage.requests,
      usage.successful_requests as success_requests,
      usage.failed_requests,
      greatest(usage.requests - usage.successful_requests - usage.failed_requests, 0) as neutral_requests,
      usage.rate_limited_requests,
      0::numeric as total_cost_nanos,
      case when usage.latency_count > 0 then usage.latency_sum_ms::numeric / usage.latency_count else null end as avg_latency_ms,
      case when usage.generation_count > 0 then usage.generation_sum_ms::numeric / usage.generation_count else null end as avg_generation_ms,
      case when usage.throughput_count > 0 then usage.throughput_sum::numeric / usage.throughput_count else null end as avg_throughput,
      usage.rollup_id
    from public.v2_public_usage_daily usage
    left join public.v2_model_provider_routes route on route.provider_model_id = usage.provider_model_id
    where usage.model_slug = lower(trim(p_model_slug))
      and (p_since is null or usage.usage_date >= p_since)
      and (p_until is null or usage.usage_date <= p_until)
      and (p_provider_ids is null or coalesce(route.provider_slug, usage.provider_model_id, '') = any(p_provider_ids))
  ),
  meters as (
    select rollup_id,
      sum(quantity) filter (where meter_key = 'input_tokens') as input_tokens,
      sum(quantity) filter (where meter_key = 'output_tokens') as output_tokens,
      sum(quantity) filter (where meter_key = 'reasoning_tokens') as reasoning_tokens,
      sum(quantity) filter (where meter_key = 'cached_input_tokens') as cached_read_tokens,
      sum(quantity) filter (where meter_key = 'input_characters') as input_characters,
      sum(quantity) filter (where meter_key = 'output_characters') as output_characters,
      sum(quantity) filter (where meter_key = 'image_inputs') as image_inputs,
      sum(quantity) filter (where meter_key = 'image_outputs') as image_outputs,
      sum(quantity) filter (where meter_key = 'audio_inputs') as audio_inputs,
      sum(quantity) filter (where meter_key = 'audio_outputs') as audio_outputs,
      sum(quantity) filter (where meter_key = 'video_inputs') as video_inputs,
      sum(quantity) filter (where meter_key = 'video_outputs') as video_outputs
    from public.v2_public_usage_daily_meters group by rollup_id
  )
  select b.day_bucket, b.model_id, b.provider_id, ''::text as endpoint,
    sum(b.requests)::bigint, sum(b.success_requests)::bigint, sum(b.failed_requests)::bigint,
    sum(b.neutral_requests)::bigint, sum(b.rate_limited_requests)::bigint,
    sum(coalesce(m.input_tokens, 0) + coalesce(m.output_tokens, 0) + coalesce(m.reasoning_tokens, 0)) as total_tokens,
    sum(coalesce(m.input_tokens, 0)), sum(coalesce(m.output_tokens, 0)), sum(coalesce(m.reasoning_tokens, 0)),
    sum(coalesce(m.cached_read_tokens, 0)), sum(coalesce(m.input_characters, 0)), sum(coalesce(m.output_characters, 0)),
    sum(coalesce(m.input_characters, 0) + coalesce(m.output_characters, 0)),
    sum(coalesce(m.image_inputs, 0)), sum(coalesce(m.image_outputs, 0)), sum(coalesce(m.audio_inputs, 0)), sum(coalesce(m.audio_outputs, 0)),
    sum(coalesce(m.video_inputs, 0)), sum(coalesce(m.video_outputs, 0)), sum(b.total_cost_nanos),
    case when sum(b.requests) > 0 then sum(b.avg_latency_ms * b.requests) / sum(b.requests) else null end,
    case when sum(b.requests) > 0 then sum(b.avg_generation_ms * b.requests) / sum(b.requests) else null end,
    case when sum(b.requests) > 0 then sum(b.avg_throughput * b.requests) / sum(b.requests) else null end
  from base b left join meters m on m.rollup_id = b.rollup_id
  group by b.day_bucket, b.model_id, b.provider_id
  order by b.day_bucket, b.provider_id;
$$;


--
-- Name: get_v2_model_variants(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_model_variants(p_model_slug text) RETURNS TABLE(model_id text, name text, variant_kind text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with requested as (
    select coalesce(model.base_model_slug, model.model_slug) as base_model_slug
    from public.v2_models model
    where model.model_slug = lower(trim(p_model_slug))
      and model.hidden = false
      and model.status <> 'disabled'
  )
  select
    model.model_slug as model_id,
    model.name,
    model.variant_kind
  from public.v2_models model
  cross join requested
  where (
      model.model_slug = requested.base_model_slug
      or model.base_model_slug = requested.base_model_slug
    )
    and model.hidden = false
    and model.status <> 'disabled'
  order by
    case when model.variant_kind = 'standard' then 0 else 1 end,
    model.name,
    model.model_slug;
$$;


--
-- Name: FUNCTION get_v2_model_variants(p_model_slug text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_v2_model_variants(p_model_slug text) IS 'Returns the visible base/free sibling identities for a canonical V2 model slug.';


--
-- Name: get_v2_provider_region_map(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_provider_region_map(p_provider_slugs text[] DEFAULT NULL::text[]) RETURNS TABLE(provider_slug text, regions text[])
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select
    region.provider_slug,
    array_agg(distinct region.region_code order by region.region_code)
  from public.v2_provider_regions region
  where region.status <> 'disabled'
    and region.routing_enabled = true
    and (p_provider_slugs is null or region.provider_slug = any(p_provider_slugs))
  group by region.provider_slug;
$$;


--
-- Name: get_v2_public_model_weekly_metrics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_public_model_weekly_metrics() RETURNS TABLE(model_slug text, popularity_tokens_week numeric, weekly_usage_metric text, weekly_usage_quantity numeric, weekly_usage_unit text, throughput_week numeric, latency_week numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with request_totals as (
    select
      rollup.model_slug,
      sum(rollup.requests)::numeric as requests
    from public.v2_public_usage_daily rollup
    where rollup.usage_date >= current_date - 6
      and rollup.usage_date <= current_date
    group by rollup.model_slug
  )
  select
    metric.model_slug,
    metric.popularity_tokens_week,
    case
      when metric.weekly_usage_metric = 'characters'
        and lower(coalesce(model.metadata->>'model_type', '')) <> 'audio'
        and array_to_string(model.output_modalities, ',') !~ 'audio'
        then 'requests'
      else metric.weekly_usage_metric
    end as weekly_usage_metric,
    case
      when metric.weekly_usage_metric = 'characters'
        and lower(coalesce(model.metadata->>'model_type', '')) <> 'audio'
        and array_to_string(model.output_modalities, ',') !~ 'audio'
        then coalesce(requests.requests, 0)
      else metric.weekly_usage_quantity
    end as weekly_usage_quantity,
    case
      when metric.weekly_usage_metric = 'characters'
        and lower(coalesce(model.metadata->>'model_type', '')) <> 'audio'
        and array_to_string(model.output_modalities, ',') !~ 'audio'
        then 'requests'
      else metric.weekly_usage_unit
    end as weekly_usage_unit,
    metric.throughput_week,
    metric.latency_week
  from public.get_v2_public_model_weekly_metrics_base() metric
  join public.v2_models model on model.model_slug = metric.model_slug
  left join request_totals requests on requests.model_slug = metric.model_slug
  order by weekly_usage_quantity desc, metric.model_slug;
$$;


--
-- Name: FUNCTION get_v2_public_model_weekly_metrics(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_v2_public_model_weekly_metrics() IS 'Returns model-appropriate seven-day primary usage plus token and sample-weighted performance metrics.';


--
-- Name: get_v2_public_model_weekly_metrics_base(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_public_model_weekly_metrics_base() RETURNS TABLE(model_slug text, popularity_tokens_week numeric, weekly_usage_metric text, weekly_usage_quantity numeric, weekly_usage_unit text, throughput_week numeric, latency_week numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with recent_rollups as materialized (
    select
      rollup.rollup_id,
      rollup.model_slug,
      rollup.requests,
      rollup.latency_sum_ms,
      rollup.latency_count,
      rollup.throughput_sum,
      rollup.throughput_count
    from public.v2_public_usage_daily rollup
    where rollup.usage_date >= current_date - 6
      and rollup.usage_date <= current_date
  ),
  meter_totals as (
    select
      rollup.model_slug,
      sum(meter.quantity) filter (
        where meter.meter_key in ('input_tokens', 'output_tokens')
          and meter.unit in ('token', 'tokens')
      ) as total_tokens,
      sum(meter.quantity) filter (
        where meter.meter_key in ('output_images', 'output_image')
          and meter.unit in ('image', 'images')
      ) as output_images,
      sum(meter.quantity) filter (
        where meter.meter_key in ('output_video_seconds', 'video_seconds')
          and meter.unit in ('second', 'seconds')
      ) as video_seconds,
      sum(meter.quantity) filter (
        where meter.meter_key in ('audio_seconds', 'input_audio_seconds', 'output_audio_seconds')
          and meter.unit in ('second', 'seconds')
      ) as audio_seconds,
      sum(meter.quantity) filter (
        where meter.meter_key in ('input_characters', 'output_characters', 'total_characters')
          and meter.unit in ('character', 'characters')
      ) as characters
    from public.v2_public_usage_daily_meters meter
    join recent_rollups rollup on rollup.rollup_id = meter.rollup_id
    group by rollup.model_slug
  ),
  model_totals as (
    select
      rollup.model_slug,
      sum(rollup.requests)::numeric as requests,
      sum(rollup.latency_sum_ms)::numeric as latency_sum_ms,
      sum(rollup.latency_count)::numeric as latency_count,
      sum(rollup.throughput_sum)::numeric as throughput_sum,
      sum(rollup.throughput_count)::numeric as throughput_count,
      coalesce(meter.total_tokens, 0)::numeric as total_tokens,
      coalesce(meter.output_images, 0)::numeric as output_images,
      coalesce(meter.video_seconds, 0)::numeric as video_seconds,
      coalesce(meter.audio_seconds, 0)::numeric as audio_seconds,
      coalesce(meter.characters, 0)::numeric as characters
    from recent_rollups rollup
    left join meter_totals meter on meter.model_slug = rollup.model_slug
    group by
      rollup.model_slug,
      meter.total_tokens,
      meter.output_images,
      meter.video_seconds,
      meter.audio_seconds,
      meter.characters
  ),
  classified as (
    select
      totals.*,
      lower(coalesce(model.metadata->>'model_type', '')) as model_type,
      array_to_string(model.input_modalities, ',') as input_modalities,
      array_to_string(model.output_modalities, ',') as output_modalities
    from model_totals totals
    join public.v2_models model on model.model_slug = totals.model_slug
  )
  select
    totals.model_slug,
    totals.total_tokens as popularity_tokens_week,
    case
      when (totals.model_type = 'video' or totals.output_modalities ~ 'video') and totals.video_seconds > 0 then 'video_seconds'
      when (totals.model_type = 'image' or totals.output_modalities ~ 'image') and totals.output_images > 0 then 'images'
      when (totals.input_modalities ~ 'audio' or totals.output_modalities ~ 'audio') and totals.audio_seconds > 0 then 'audio_seconds'
      when totals.model_type in ('embedding', 'rerank', 'moderation') then 'requests'
      when totals.total_tokens > 0 then 'tokens'
      when totals.characters > 0 then 'characters'
      else 'requests'
    end as weekly_usage_metric,
    case
      when (totals.model_type = 'video' or totals.output_modalities ~ 'video') and totals.video_seconds > 0 then totals.video_seconds
      when (totals.model_type = 'image' or totals.output_modalities ~ 'image') and totals.output_images > 0 then totals.output_images
      when (totals.input_modalities ~ 'audio' or totals.output_modalities ~ 'audio') and totals.audio_seconds > 0 then totals.audio_seconds
      when totals.model_type in ('embedding', 'rerank', 'moderation') then totals.requests
      when totals.total_tokens > 0 then totals.total_tokens
      when totals.characters > 0 then totals.characters
      else totals.requests
    end as weekly_usage_quantity,
    case
      when (totals.model_type = 'video' or totals.output_modalities ~ 'video') and totals.video_seconds > 0 then 'seconds'
      when (totals.model_type = 'image' or totals.output_modalities ~ 'image') and totals.output_images > 0 then 'images'
      when (totals.input_modalities ~ 'audio' or totals.output_modalities ~ 'audio') and totals.audio_seconds > 0 then 'seconds'
      when totals.model_type in ('embedding', 'rerank', 'moderation') then 'requests'
      when totals.total_tokens > 0 then 'tokens'
      when totals.characters > 0 then 'characters'
      else 'requests'
    end as weekly_usage_unit,
    round(
      totals.throughput_sum / nullif(totals.throughput_count, 0),
      2
    ) as throughput_week,
    round(
      totals.latency_sum_ms / nullif(totals.latency_count, 0),
      2
    ) as latency_week
  from classified totals
  order by weekly_usage_quantity desc, totals.model_slug;
$$;


--
-- Name: FUNCTION get_v2_public_model_weekly_metrics_base(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_v2_public_model_weekly_metrics_base() IS 'Returns seven-day primary usage, token totals, and sample-weighted performance from v2 public daily rollups.';


--
-- Name: get_v2_public_models_page_rows(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_public_models_page_rows(p_region text DEFAULT NULL::text, p_service_tier text DEFAULT 'standard'::text) RETURNS SETOF jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with candidate_routes as (
    select
      route.provider_model_id,
      route.model_slug,
      route.provider_slug,
      route.provider_model_slug,
      route.input_modalities,
      route.output_modalities,
      route.context_length,
      route.max_output_tokens,
      route.status as route_status,
      route.routing_enabled as route_routing_enabled,
      route.provider_availability_status,
      model.name,
      model.description,
      model.status as model_status,
      model.hidden,
      model.announced_at,
      model.released_at,
      model.input_modalities as model_input_modalities,
      model.output_modalities as model_output_modalities,
      model.lab_slug,
      lab.name as lab_name,
      provider.name as provider_name,
      provider.status as provider_status,
      provider.routing_enabled as provider_routing_enabled,
      variant.service_tier_slug,
      variant.execution_region,
      variant.data_region,
      variant.status as variant_status,
      variant.routing_enabled as variant_routing_enabled,
      region.region_code
    from public.v2_model_provider_routes route
    join public.v2_models model on model.model_slug = route.model_slug
    join public.v2_labs lab on lab.lab_slug = model.lab_slug
    join public.v2_providers provider on provider.provider_slug = route.provider_slug
    join public.v2_route_variants variant on variant.provider_model_id = route.provider_model_id
    left join public.v2_provider_regions region
      on region.provider_slug = route.provider_slug
     and region.status <> 'disabled'
     and region.routing_enabled = true
    where model.hidden = false
      and model.status <> 'disabled'
      and provider.status <> 'disabled'
      and route.status in ('active', 'degraded')
      and variant.status in ('active', 'degraded')
      and provider.routing_enabled = true
      and (p_service_tier is null or variant.service_tier_slug = lower(p_service_tier))
      and (
        p_region is null
        or lower(p_region) = lower(coalesce(variant.execution_region, ''))
        or lower(p_region) = lower(coalesce(variant.data_region, ''))
        or lower(p_region) = lower(coalesce(region.region_code, ''))
        or lower(p_region) = any(route.regions)
      )
  ),
  eligible_routes as (
    select *
    from candidate_routes
    where route_routing_enabled = true
      and provider_routing_enabled = true
      and variant_routing_enabled = true
  ),
  preview_routes as (
    select *
    from candidate_routes
    where route_routing_enabled = false
      and variant_routing_enabled = false
      and provider_availability_status = 'coming_soon'
  ),
  display_routes as (
    select * from eligible_routes
    union all
    select * from preview_routes
  ),
  capability_rows as (
    select
      capability.provider_model_id,
      array_agg(distinct capability.capability_id order by capability.capability_id)
        filter (where capability.status <> 'disabled') as capabilities,
      array_agg(distinct parameter.key order by parameter.key)
        filter (where parameter.key is not null) as supported_parameters
    from public.v2_route_capabilities capability
    left join lateral jsonb_object_keys(
      case when jsonb_typeof(capability.params) = 'object' then capability.params else '{}'::jsonb end
    ) parameter(key) on true
    where capability.status <> 'disabled'
    group by capability.provider_model_id
  ),
  route_modalities as (
    select
      route.model_slug,
      array_agg(distinct input_modality order by input_modality) filter (where input_modality is not null and input_modality <> '') as input_modalities,
      array_agg(distinct output_modality order by output_modality) filter (where output_modality is not null and output_modality <> '') as output_modalities
    from eligible_routes route
    left join lateral unnest(route.input_modalities) input(input_modality) on true
    left join lateral unnest(route.output_modalities) output(output_modality) on true
    group by route.model_slug
  ),
  pricing_rows as (
    select
      route.model_slug,
      min(meter.price_nanos / 1000000000.0) filter (where meter.direction = 'input') as lowest_input_price,
      min(meter.price_nanos / 1000000000.0) filter (where meter.direction = 'output') as lowest_output_price,
      jsonb_agg(
        jsonb_build_object(
          'label', meter.display_label,
          'meter_key', meter.meter_key,
          'unit', meter.unit,
          'unit_quantity', meter.unit_quantity,
          'price', meter.price_nanos / 1000000000.0,
          'display_unit', meter.display_unit,
          'service_tier', sku.service_tier_slug
        )
        order by meter.meter_order, meter.meter_key
      ) as pricing_detail_rows
    from public.v2_pricing_skus sku
    join public.v2_pricing_sku_meters meter on meter.sku_id = sku.sku_id
    join public.v2_model_provider_routes route on route.provider_model_id = sku.provider_model_id
    where sku.status <> 'disabled'
      and (p_service_tier is null or sku.service_tier_slug = lower(p_service_tier))
      and sku.effective_from <= now()
      and (sku.effective_to is null or sku.effective_to > now())
    group by route.model_slug
  ),
  grouped as (
    select
      route.model_slug,
      max(route.name) as name,
      max(route.description) as description,
      max(route.model_status) as model_status,
      bool_or(route.hidden) as hidden,
      max(route.announced_at) as announced_at,
      max(route.released_at) as released_at,
      max(route.lab_slug) as lab_slug,
      max(route.lab_name) as lab_name,
      count(distinct route.provider_model_id)::integer as provider_count,
      count(distinct route.provider_model_id) filter (
        where route.route_status = 'active'
          and route.route_routing_enabled
          and route.provider_status not in ('disabled', 'deprecated')
          and route.provider_routing_enabled
          and route.variant_routing_enabled
      )::integer as active_provider_count,
      count(distinct route.provider_model_id) filter (
        where route.provider_availability_status = 'coming_soon'
          and not route.route_routing_enabled
          and not route.variant_routing_enabled
      )::integer as coming_soon_provider_count,
      array_agg(distinct route.provider_slug order by route.provider_slug) as provider_ids,
      array_agg(distinct route.provider_name order by route.provider_name) as provider_names,
      array_agg(distinct route.provider_name order by route.provider_name) filter (
        where route.route_status = 'active'
          and route.route_routing_enabled
          and route.provider_routing_enabled
          and route.variant_routing_enabled
      ) as active_provider_names,
      array_agg(distinct route.provider_model_slug order by route.provider_model_slug) as provider_model_slugs,
      array_agg(distinct route.service_tier_slug order by route.service_tier_slug) as service_tiers,
      array_agg(distinct nullif(lower(coalesce(route.execution_region, route.data_region, route.region_code)), '') order by nullif(lower(coalesce(route.execution_region, route.data_region, route.region_code)), '')) filter (where nullif(lower(coalesce(route.execution_region, route.data_region, route.region_code)), '') is not null) as regions,
      array_agg(distinct route.context_length order by route.context_length) filter (where route.context_length is not null) as context_lengths,
      jsonb_agg(distinct jsonb_build_object(
        'id', route.provider_slug,
        'name', route.provider_name,
        'provider_model_slug', route.provider_model_slug,
        'service_tier', route.service_tier_slug,
        'execution_region', route.execution_region,
        'data_region', route.data_region,
        'is_active', route.route_status = 'active' and route.route_routing_enabled and route.provider_routing_enabled and route.variant_routing_enabled,
        'status', case
          when route.provider_availability_status = 'coming_soon' then 'coming_soon'
          when route.route_status = 'active' and route.route_routing_enabled and route.provider_routing_enabled and route.variant_routing_enabled then 'active'
          else 'inactive'
        end
      )) as provider_details
    from display_routes route
    group by route.model_slug
  )
  select jsonb_build_object(
    'model_id', grouped.model_slug,
    'name', grouped.name,
    'description', grouped.description,
    'organisation_id', grouped.lab_slug,
    'organisation_name', grouped.lab_name,
    'primary_date', coalesce(grouped.released_at, grouped.announced_at),
    'primary_timestamp', extract(epoch from coalesce(grouped.released_at, grouped.announced_at)) * 1000,
    'primary_group_key', to_char(coalesce(grouped.released_at, grouped.announced_at), 'YYYY-MM'),
    'gateway_status', case
      when grouped.active_provider_count > 0 then 'active'
      when grouped.coming_soon_provider_count > 0 then 'coming_soon'
      when lower(coalesce(grouped.model_status, '')) = 'draft' then 'coming_soon'
      else 'not_active'
    end,
    'gateway_provider_count', grouped.provider_count,
    'gateway_active_provider_count', grouped.active_provider_count,
    'gateway_endpoints', coalesce(capability_summary.capabilities, array[]::text[]),
    'gateway_input_modalities', coalesce(modalities.input_modalities, array[]::text[]),
    'gateway_output_modalities', coalesce(modalities.output_modalities, array[]::text[]),
    'gateway_features', coalesce(capability_summary.features, array[]::text[]),
    'gateway_tiers', coalesce(grouped.service_tiers, array[]::text[]),
    'gateway_provider_names', coalesce(grouped.provider_names, array[]::text[]),
    'gateway_active_provider_names', coalesce(grouped.active_provider_names, array[]::text[]),
    'gateway_execution_regions', coalesce(grouped.regions, array[]::text[]),
    'gateway_provider_details', coalesce(grouped.provider_details, '[]'::jsonb),
    'gateway_api_model_ids', coalesce(grouped.provider_model_slugs, array[]::text[]),
    'context_lengths', coalesce(grouped.context_lengths, array[]::integer[]),
    'supported_parameters', coalesce(capability_summary.supported_parameters, array[]::text[]),
    'lowest_input_price', pricing.lowest_input_price,
    'lowest_output_price', pricing.lowest_output_price,
    'lowest_standard_input_price', pricing.lowest_input_price,
    'lowest_standard_output_price', pricing.lowest_output_price,
    'lowest_standard_input_price_label', 'Input',
    'lowest_standard_input_price_unit', 'billing unit',
    'lowest_standard_output_price_label', 'Output',
    'lowest_standard_output_price_unit', 'billing unit',
    'lowest_from_price', least(pricing.lowest_input_price, pricing.lowest_output_price),
    'lowest_from_price_unit', 'billing unit',
    'pricing_detail_rows', coalesce(pricing.pricing_detail_rows, '[]'::jsonb),
    'gateway_monitor_rows', '[]'::jsonb,
    'popularity_tokens_week', null,
    'throughput_week', null,
    'latency_week', null
  )
  from grouped
  left join route_modalities modalities on modalities.model_slug = grouped.model_slug
  left join pricing_rows pricing on pricing.model_slug = grouped.model_slug
  left join lateral (
    select
      array_agg(distinct capability_id order by capability_id) as capabilities,
      array_agg(distinct case
        when capability_id ilike '%tool%' then 'tools'
        when capability_id ilike '%structured%' then 'structured_outputs'
        when capability_id ilike '%reason%' or capability_id ilike '%thinking%' then 'reasoning'
        when capability_id ilike '%search%' then 'web_search'
        else null
      end order by case
        when capability_id ilike '%tool%' then 'tools'
        when capability_id ilike '%structured%' then 'structured_outputs'
        when capability_id ilike '%reason%' or capability_id ilike '%thinking%' then 'reasoning'
        when capability_id ilike '%search%' then 'web_search'
        else null
      end) filter (where capability_id is not null) as features,
      array_agg(distinct parameter order by parameter) filter (where parameter is not null) as supported_parameters
    from eligible_routes eligible
    join public.v2_route_capabilities capability on capability.provider_model_id = eligible.provider_model_id
    left join lateral jsonb_object_keys(
      case when jsonb_typeof(capability.params) = 'object' then capability.params else '{}'::jsonb end
    ) parameter on true
    where eligible.model_slug = grouped.model_slug
      and capability.status <> 'disabled'
  ) capability_summary on true
  order by grouped.released_at desc nulls last, grouped.lab_name, grouped.name;
$$;


--
-- Name: FUNCTION get_v2_public_models_page_rows(p_region text, p_service_tier text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_v2_public_models_page_rows(p_region text, p_service_tier text) IS 'Returns active gateway model rows plus explicitly coming-soon provider mappings without exposing preview routes as active capabilities.';


--
-- Name: get_v2_routing_candidates(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_routing_candidates(p_model_slug text, p_capability_id text DEFAULT NULL::text, p_region text DEFAULT NULL::text, p_service_tier text DEFAULT 'standard'::text) RETURNS TABLE(provider_model_id text, provider_slug text, provider_name text, model_slug text, provider_model_slug text, variant_id uuid, service_tier_slug text, execution_region text, data_region text, route_status text, provider_status text, capability_status text, routing_enabled boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select distinct on (candidate.provider_model_id, candidate.variant_id)
    candidate.provider_model_id,
    candidate.provider_slug,
    candidate.provider_name,
    candidate.model_slug,
    candidate.provider_model_slug,
    candidate.variant_id,
    candidate.service_tier_slug,
    candidate.execution_region,
    candidate.data_region,
    candidate.route_status,
    candidate.provider_status,
    candidate.capability_status,
    candidate.routing_enabled
  from public.get_v2_routing_candidates_raw(p_model_slug, p_capability_id, p_region, p_service_tier) candidate
  where candidate.provider_status not in ('disabled', 'deprecated', 'external')
  order by candidate.provider_model_id, candidate.variant_id, candidate.routing_enabled desc, candidate.capability_status;
$$;


--
-- Name: get_v2_routing_candidates_raw(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_v2_routing_candidates_raw(p_model_slug text, p_capability_id text DEFAULT NULL::text, p_region text DEFAULT NULL::text, p_service_tier text DEFAULT 'standard'::text) RETURNS TABLE(provider_model_id text, provider_slug text, provider_name text, model_slug text, provider_model_slug text, variant_id uuid, service_tier_slug text, execution_region text, data_region text, route_status text, provider_status text, capability_status text, routing_enabled boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select
    route.provider_model_id,
    route.provider_slug,
    provider.name,
    route.model_slug,
    route.provider_model_slug,
    variant.variant_id,
    variant.service_tier_slug,
    variant.execution_region,
    variant.data_region,
    route.status,
    provider.status,
    coalesce(capability.status, 'active'),
    route.routing_enabled and provider.routing_enabled and variant.routing_enabled
  from public.v2_model_provider_routes route
  join public.v2_providers provider on provider.provider_slug = route.provider_slug
  join public.v2_route_variants variant on variant.provider_model_id = route.provider_model_id
  left join public.v2_route_capabilities capability
    on capability.provider_model_id = route.provider_model_id
   and (p_capability_id is null or capability.capability_id = p_capability_id)
  where route.model_slug = lower(p_model_slug)
    and route.status in ('active', 'degraded')
    and provider.status not in ('disabled', 'deprecated')
    and variant.status in ('active', 'degraded')
    and (p_capability_id is null or (capability.capability_id = p_capability_id and capability.status = 'active'))
    and (p_service_tier is null or variant.service_tier_slug = lower(p_service_tier))
    and (
      p_region is null
      or lower(p_region) = lower(coalesce(variant.execution_region, ''))
      or lower(p_region) = lower(coalesce(variant.data_region, ''))
    )
  order by (route.routing_enabled and provider.routing_enabled and variant.routing_enabled) desc,
    case route.status when 'active' then 0 else 1 end,
    provider.name,
    route.provider_model_id;
$$;


--
-- Name: FUNCTION get_v2_routing_candidates_raw(p_model_slug text, p_capability_id text, p_region text, p_service_tier text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_v2_routing_candidates_raw(p_model_slug text, p_capability_id text, p_region text, p_service_tier text) IS 'Internal routing candidate query with provider/model, region, tier, capability, and status gates evaluated in SQL.';


--
-- Name: get_workspace_key_usage(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_workspace_key_usage(p_workspace_id uuid, p_day_start timestamp with time zone) RETURNS TABLE(key_id uuid, daily_request_count bigint, daily_cost_nanos bigint, last_used_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    gr.key_id,
    count(*) filter (where gr.created_at >= p_day_start)::bigint as daily_request_count,
    coalesce(sum(gr.cost_nanos) filter (where gr.created_at >= p_day_start), 0)::bigint as daily_cost_nanos,
    max(gr.created_at) as last_used_at
  from private.v2_rpc_gateway_requests_compat gr
  where gr.workspace_id = p_workspace_id
    and gr.key_id is not null
    and gr.success is true
    and public.is_workspace_member(p_workspace_id)
  group by gr.key_id;
$$;


--
-- Name: get_workspace_model_last_used(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_workspace_model_last_used(p_team_id uuid, p_since timestamp with time zone) RETURNS TABLE(model_id text, last_used_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    gr.model_id::text as model_id,
    max(gr.created_at) as last_used_at
  from private.v2_rpc_gateway_requests_compat gr
  where gr.team_id = p_team_id
    and gr.created_at >= p_since
    and gr.model_id is not null
    and gr.model_id <> ''
    and public.is_workspace_member(p_team_id)
  group by gr.model_id
  order by last_used_at desc;
$$;


--
-- Name: get_workspace_tier_info(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_workspace_tier_info(p_workspace_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_exists boolean := false;
  v_current_month_nanos bigint := 0;
  v_prev_month_nanos bigint := 0;
  v_current_month_spend numeric(12, 2);
  v_prev_month_spend numeric(12, 2);
  v_current_month_start_ts timestamptz := date_trunc('month', (now() at time zone 'utc'));
  v_prev_month_start_ts timestamptz := date_trunc('month', (now() at time zone 'utc')) - interval '1 month';
  v_next_month_start_ts timestamptz := date_trunc('month', (now() at time zone 'utc')) + interval '1 month';
begin
  select exists(
    select 1 from public.workspaces w where w.id = p_workspace_id
  )
  into v_exists;

  if not v_exists then
    raise exception 'Workspace not found: %', p_workspace_id;
  end if;

  select coalesce(sum(gr.cost_nanos), 0)::bigint
  into v_current_month_nanos
  from private.v2_rpc_gateway_requests_compat gr
  where gr.workspace_id = p_workspace_id
    and gr.success is true
    and gr.created_at >= v_current_month_start_ts
    and gr.created_at < v_next_month_start_ts;

  select coalesce(sum(gr.cost_nanos), 0)::bigint
  into v_prev_month_nanos
  from private.v2_rpc_gateway_requests_compat gr
  where gr.workspace_id = p_workspace_id
    and gr.success is true
    and gr.created_at >= v_prev_month_start_ts
    and gr.created_at < v_current_month_start_ts;

  v_current_month_spend := round((v_current_month_nanos::numeric / 1000000000.0)::numeric, 2);
  v_prev_month_spend := round((v_prev_month_nanos::numeric / 1000000000.0)::numeric, 2);

  return jsonb_build_object(
    'tier', 'basic',
    'tier_display', 'Standard',
    'markup_percentage', 5.00,
    'threshold_usd', 0,
    'current_month_spend_usd', v_current_month_spend,
    'previous_month_spend_usd', v_prev_month_spend,
    'progress_to_enterprise_pct', 100,
    'is_eligible_for_enterprise', false
  );
end;
$$;


--
-- Name: increment_workspace_byok_monthly_request_count(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_workspace_byok_monthly_request_count(p_team_id uuid, p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(month_start timestamp with time zone, request_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_month_start timestamptz;
begin
  if p_team_id is null then
    raise exception 'p_team_id is required';
  end if;

  v_month_start := (date_trunc('month', p_now at time zone 'UTC') at time zone 'UTC');

  insert into public.team_byok_monthly_usage as usage (
    team_id,
    month_start,
    request_count,
    created_at,
    updated_at
  )
  values (
    p_team_id,
    v_month_start,
    1,
    now(),
    now()
  )
  on conflict (team_id, month_start)
  do update
    set request_count = usage.request_count + 1,
        updated_at = now();

  return query
  select u.month_start, u.request_count
  from public.team_byok_monthly_usage u
  where u.team_id = p_team_id
    and u.month_start = v_month_start;
end;
$$;


--
-- Name: FUNCTION increment_workspace_byok_monthly_request_count(p_team_id uuid, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.increment_workspace_byok_monthly_request_count(p_team_id uuid, p_now timestamp with time zone) IS 'Atomically increments BYOK request count for team/month (UTC month boundary) and returns updated count.';


--
-- Name: ingest_v2_gateway_request(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingest_v2_gateway_request(p_event jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request_event_id uuid;
  v_workspace_id uuid;
  v_request_id text;
  v_requested_input text;
  v_requested_model_slug text;
  v_routed_model_slug text;
  v_provider text;
  v_provider_api_model_id text;
  v_provider_model_id text;
  v_attempts jsonb := coalesce(p_event->'attempts', '[]'::jsonb);
  v_usage jsonb := coalesce(p_event->'usage_meters', '[]'::jsonb);
  v_pricing jsonb := coalesce(p_event->'pricing_lines', '[]'::jsonb);
  v_safe_metadata jsonb := coalesce(p_event->'safe_metadata', '{}'::jsonb);
  v_occurred_at timestamptz := coalesce(nullif(p_event->>'occurred_at', '')::timestamptz, now());
begin
  if jsonb_typeof(p_event) <> 'object' then
    raise exception using errcode = '22023', message = 'gateway_event_must_be_object';
  end if;

  v_workspace_id := nullif(p_event->>'workspace_id', '')::uuid;
  v_request_id := nullif(trim(p_event->>'request_id'), '');
  v_requested_input := nullif(trim(p_event->>'requested_model_input'), '');
  v_provider := nullif(trim(p_event->>'provider'), '');
  v_provider_api_model_id := nullif(trim(p_event->>'provider_api_model_id'), '');

  if v_workspace_id is null or v_request_id is null or v_requested_input is null then
    raise exception using errcode = '22023', message = 'gateway_event_missing_identity';
  end if;
  if length(v_request_id) > 256 or length(v_requested_input) > 512 then
    raise exception using errcode = '22023', message = 'gateway_event_identity_too_long';
  end if;
  if jsonb_typeof(v_attempts) <> 'array' then
    raise exception using errcode = '22023', message = 'gateway_event_attempts_invalid';
  end if;
  if jsonb_array_length(v_attempts) > 128 then
    raise exception using errcode = '22023', message = 'gateway_event_attempts_invalid';
  end if;
  if jsonb_typeof(v_usage) <> 'array' then
    raise exception using errcode = '22023', message = 'gateway_event_usage_invalid';
  end if;
  if jsonb_array_length(v_usage) > 256 then
    raise exception using errcode = '22023', message = 'gateway_event_usage_invalid';
  end if;
  if jsonb_typeof(v_pricing) <> 'array' then
    raise exception using errcode = '22023', message = 'gateway_event_pricing_invalid';
  end if;
  if jsonb_array_length(v_pricing) > 256 then
    raise exception using errcode = '22023', message = 'gateway_event_pricing_invalid';
  end if;
  if jsonb_typeof(v_safe_metadata) <> 'object' or pg_column_size(v_safe_metadata) > 16384 then
    raise exception using errcode = '22023', message = 'gateway_event_safe_metadata_invalid';
  end if;

  -- Serialize retries/concurrent finalizers for the same logical request.
  perform pg_advisory_xact_lock(hashtextextended(v_workspace_id::text || ':' || v_request_id, 0));

  select model.model_slug into v_requested_model_slug
  from public.v2_models model
  where model.model_slug = lower(v_requested_input)
  limit 1;
  if v_requested_model_slug is null then
    select alias.model_slug into v_requested_model_slug
    from public.v2_model_aliases alias
    where alias.alias_slug = lower(v_requested_input) and alias.enabled = true
    limit 1;
  end if;

  select model.model_slug into v_routed_model_slug
  from public.v2_models model
  where model.model_slug = lower(coalesce(nullif(trim(p_event->>'routed_model_slug'), ''), v_requested_model_slug, v_requested_input))
  limit 1;
  v_routed_model_slug := coalesce(v_routed_model_slug, v_requested_model_slug);

  if nullif(trim(p_event->>'provider_model_id'), '') is not null then
    select route.provider_model_id into v_provider_model_id
    from public.v2_model_provider_routes route
    where route.provider_model_id = trim(p_event->>'provider_model_id')
    limit 1;
  end if;
  if v_provider_model_id is null and v_provider is not null then
    select route.provider_model_id into v_provider_model_id
    from public.v2_model_provider_routes route
    where route.provider_slug = v_provider
      and (v_routed_model_slug is null or route.model_slug = v_routed_model_slug)
    order by
      case
        when v_provider_api_model_id is not null and route.provider_model_slug = v_provider_api_model_id then 0
        when v_provider_api_model_id is not null and route.provider_model_id = v_provider || ':' || v_provider_api_model_id then 1
        else 2
      end,
      case when route.routing_enabled then 0 else 1 end,
      route.provider_model_id
    limit 1;
  end if;

  insert into public.v2_request_facts (
    workspace_id, request_id, occurred_at, app_id, key_id, endpoint,
    requested_model_input, requested_model_slug, routed_model_slug, provider_model_id,
    status_code, success, error_code, stop_reason, tool_call_count, tool_call_succeeded,
    structured_output_attempted, structured_output_succeeded, stream, byok,
    latency_ms, time_to_first_token_ms, generation_ms, internal_dispatch_ms,
    gateway_total_ms, upstream_attempt_count, throughput, user_agent,
    session_id, end_user_id, auth_method, native_response_id, cost_nanos, currency,
    cloudflare_colo, safe_metadata
  ) values (
    v_workspace_id, v_request_id, v_occurred_at,
    nullif(p_event->>'app_id', '')::uuid, nullif(p_event->>'key_id', '')::uuid,
    coalesce(nullif(trim(p_event->>'endpoint'), ''), 'unknown'),
    v_requested_input, v_requested_model_slug, v_routed_model_slug, v_provider_model_id,
    nullif(p_event->>'status_code', '')::integer, coalesce((p_event->>'success')::boolean, false),
    nullif(p_event->>'error_code', ''), nullif(p_event->>'stop_reason', ''),
    greatest(0, coalesce((p_event->>'tool_call_count')::integer, 0)),
    case when coalesce((p_event->>'tool_call_count')::integer, 0) > 0 then (p_event->>'tool_call_succeeded')::boolean else null end,
    coalesce((p_event->>'structured_output_attempted')::boolean, false),
    coalesce((p_event->>'structured_output_succeeded')::boolean, false),
    coalesce((p_event->>'stream')::boolean, false), coalesce((p_event->>'byok')::boolean, false),
    nullif(p_event->>'latency_ms', '')::integer,
    nullif(p_event->>'latency_ms', '')::integer,
    nullif(p_event->>'generation_ms', '')::integer,
    nullif(p_event->>'internal_dispatch_ms', '')::numeric,
    nullif(p_event->>'gateway_total_ms', '')::numeric,
    least(32767, jsonb_array_length(v_attempts))::smallint,
    nullif(p_event->>'throughput', '')::numeric,
    left(nullif(p_event->>'user_agent', ''), 1024),
    left(nullif(p_event->>'session_id', ''), 256),
    left(nullif(p_event->>'end_user_id', ''), 256),
    nullif(p_event->>'auth_method', ''),
    left(nullif(p_event->>'native_response_id', ''), 512),
    nullif(p_event->>'cost_nanos', '')::bigint,
    left(nullif(p_event->>'currency', ''), 8),
    nullif(upper(trim(p_event->>'cloudflare_colo')), ''),
    v_safe_metadata
  )
  on conflict (workspace_id, request_id) do update set
    occurred_at = excluded.occurred_at,
    app_id = excluded.app_id,
    key_id = excluded.key_id,
    endpoint = excluded.endpoint,
    requested_model_input = excluded.requested_model_input,
    requested_model_slug = excluded.requested_model_slug,
    routed_model_slug = excluded.routed_model_slug,
    provider_model_id = excluded.provider_model_id,
    status_code = excluded.status_code,
    success = excluded.success,
    error_code = excluded.error_code,
    stop_reason = excluded.stop_reason,
    tool_call_count = excluded.tool_call_count,
    tool_call_succeeded = excluded.tool_call_succeeded,
    structured_output_attempted = excluded.structured_output_attempted,
    structured_output_succeeded = excluded.structured_output_succeeded,
    stream = excluded.stream,
    byok = excluded.byok,
    latency_ms = excluded.latency_ms,
    time_to_first_token_ms = excluded.time_to_first_token_ms,
    generation_ms = excluded.generation_ms,
    internal_dispatch_ms = excluded.internal_dispatch_ms,
    gateway_total_ms = excluded.gateway_total_ms,
    upstream_attempt_count = excluded.upstream_attempt_count,
    throughput = excluded.throughput,
    user_agent = excluded.user_agent,
    session_id = excluded.session_id,
    end_user_id = excluded.end_user_id,
    auth_method = excluded.auth_method,
    native_response_id = excluded.native_response_id,
    cost_nanos = excluded.cost_nanos,
    currency = excluded.currency,
    cloudflare_colo = excluded.cloudflare_colo,
    safe_metadata = excluded.safe_metadata
  returning request_event_id into v_request_event_id;

  delete from public.v2_request_attempts attempt
  where attempt.request_event_id = v_request_event_id;

  insert into public.v2_request_attempts (
    request_event_id, attempt_number, provider_model_id, status_code, success,
    error_code, failure_class, upstream_response_id, latency_ms, cloudflare_colo, safe_metadata
  )
  select
    v_request_event_id,
    greatest(1, coalesce((item.value->>'attempt_number')::integer, item.ordinality::integer)),
    route.provider_model_id,
    nullif(item.value->>'status_code', '')::integer,
    coalesce((item.value->>'success')::boolean, false),
    nullif(item.value->>'error_code', ''),
    nullif(item.value->>'failure_class', ''),
    left(nullif(item.value->>'upstream_response_id', ''), 512),
    nullif(item.value->>'latency_ms', '')::integer,
    nullif(upper(trim(p_event->>'cloudflare_colo')), ''),
    jsonb_strip_nulls(jsonb_build_object(
      'provider', nullif(item.value->>'provider', ''),
      'credential_phase', nullif(item.value->>'credential_phase', ''),
      'key_source', nullif(item.value->>'key_source', ''),
      'response_kind', nullif(item.value->>'response_kind', ''),
      'retryable', nullif(item.value->>'retryable', '')::boolean,
      'was_probe', coalesce((item.value->>'was_probe')::boolean, false)
    ))
  from jsonb_array_elements(v_attempts) with ordinality as item(value, ordinality)
  left join lateral (
    select candidate.provider_model_id
    from public.v2_model_provider_routes candidate
    where candidate.provider_slug = nullif(item.value->>'provider', '')
      and (v_routed_model_slug is null or candidate.model_slug = v_routed_model_slug)
    order by
      case when nullif(item.value->>'provider_api_model_id', '') is not null
        and candidate.provider_model_slug = item.value->>'provider_api_model_id' then 0 else 1 end,
      candidate.provider_model_id
    limit 1
  ) route on true;

  delete from public.v2_request_usage usage
  where usage.request_event_id = v_request_event_id;

  insert into public.v2_request_usage (
    request_event_id, sku_meter_id, meter_key, modality, unit, quantity, source, billable, sequence
  )
  select
    v_request_event_id, meter.sku_meter_id,
    lower(item.value->>'meter_key'), lower(item.value->>'modality'), lower(item.value->>'unit'),
    greatest(0, (item.value->>'quantity')::numeric),
    coalesce(nullif(item.value->>'source', ''), 'gateway'),
    coalesce((item.value->>'billable')::boolean, true),
    greatest(0, coalesce((item.value->>'sequence')::integer, item.ordinality::integer - 1))
  from jsonb_array_elements(v_usage) with ordinality as item(value, ordinality)
  left join lateral (
    select sku_meter.sku_meter_id
    from public.v2_pricing_sku_meters sku_meter
    join public.v2_pricing_skus sku on sku.sku_id = sku_meter.sku_id
    where sku.provider_model_id = v_provider_model_id
      and sku_meter.meter_key = lower(item.value->>'meter_key')
      and sku.status = 'active'
      and sku.effective_from <= v_occurred_at
      and (sku.effective_to is null or sku.effective_to > v_occurred_at)
    order by sku.version desc, sku.effective_from desc
    limit 1
  ) meter on true
  where coalesce((item.value->>'quantity')::numeric, 0) > 0;

  delete from public.v2_request_pricing_lines pricing
  where pricing.request_event_id = v_request_event_id;

  insert into public.v2_request_pricing_lines (
    request_event_id, sku_id, sku_meter_id, meter_key, quantity, unit,
    unit_price_nanos, charged_nanos
  )
  select
    v_request_event_id, meter.sku_id, meter.sku_meter_id,
    lower(item.value->>'meter_key'),
    greatest(0, (item.value->>'quantity')::numeric),
    lower(coalesce(nullif(item.value->>'unit', ''), 'unit')),
    greatest(0, coalesce((item.value->>'unit_price_nanos')::numeric, 0)),
    greatest(0, coalesce((item.value->>'charged_nanos')::bigint, 0))
  from jsonb_array_elements(v_pricing) as item(value)
  left join lateral (
    select sku.sku_id, sku_meter.sku_meter_id
    from public.v2_pricing_skus sku
    left join public.v2_pricing_sku_meters sku_meter
      on sku_meter.sku_id = sku.sku_id
      and sku_meter.meter_key = lower(item.value->>'meter_key')
    where sku.provider_model_id = v_provider_model_id
      and sku.status = 'active'
      and sku.effective_from <= v_occurred_at
      and (sku.effective_to is null or sku.effective_to > v_occurred_at)
    order by sku.version desc, sku.effective_from desc
    limit 1
  ) meter on true;

  insert into public.v2_analytics_outbox (
    request_event_id, workspace_id, occurred_at, status, attempt_count,
    available_at, last_error, updated_at
  ) values (
    v_request_event_id, v_workspace_id, v_occurred_at, 'pending', 0,
    now(), null, now()
  )
  on conflict (request_event_id) do update set
    workspace_id = excluded.workspace_id,
    occurred_at = excluded.occurred_at,
    status = 'pending',
    attempt_count = 0,
    available_at = now(),
    last_error = null,
    updated_at = now();

  return v_request_event_id;
end;
$$;


--
-- Name: FUNCTION ingest_v2_gateway_request(p_event jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ingest_v2_gateway_request(p_event jsonb) IS 'Service-only, idempotent and atomic ingestion of content-free gateway request facts, attempts, usage, pricing, and analytics outbox state.';


--
-- Name: ingest_v2_gateway_request_with_routing(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingest_v2_gateway_request_with_routing(p_event jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request_event_id uuid;
  v_attempts jsonb := coalesce(p_event->'attempts', '[]'::jsonb);
  v_routing_decisions jsonb := coalesce(p_event->'routing_decisions', '[]'::jsonb);
begin
  if jsonb_typeof(v_routing_decisions) <> 'array'
     or jsonb_array_length(v_routing_decisions) > 128 then
    raise exception using errcode = '22023', message = 'gateway_event_routing_decisions_invalid';
  end if;

  v_request_event_id := public.ingest_v2_gateway_request(p_event - 'routing_decisions');

  -- The base ingestion function predates exact route IDs on attempt events.
  -- Repair those rows atomically before exposing the completed request.
  update public.v2_request_attempts attempt
  set provider_model_id = route.provider_model_id
  from jsonb_array_elements(v_attempts) with ordinality as item(value, ordinality)
  cross join lateral (
    select candidate.provider_model_id
    from public.v2_model_provider_routes candidate
    where candidate.provider_model_id = nullif(item.value->>'provider_model_id', '')
       or (
         candidate.provider_slug = nullif(item.value->>'provider', '')
         and candidate.provider_model_id =
           nullif(item.value->>'provider', '') || ':' || nullif(item.value->>'provider_api_model_id', '')
       )
       or (
         candidate.provider_slug = nullif(item.value->>'provider', '')
         and candidate.provider_model_slug = nullif(item.value->>'provider_api_model_id', '')
       )
    order by
      case when candidate.provider_model_id = nullif(item.value->>'provider_model_id', '') then 0 else 1 end,
      candidate.provider_model_id
    limit 1
  ) route
  where attempt.request_event_id = v_request_event_id
    and attempt.attempt_number = greatest(
      1,
      coalesce((item.value->>'attempt_number')::integer, item.ordinality::integer)
    );

  delete from public.v2_request_routing_decisions decision
  where decision.request_event_id = v_request_event_id;

  insert into public.v2_request_routing_decisions (
    request_event_id, decision_order, provider_model_id, provider_slug,
    provider_api_model_id, decision, rank, score, selected, attempted,
    breaker, breaker_until, provider_status, provider_routing_status,
    model_routing_status, capability_status, exclusion_stage, exclusion_reason,
    score_factors
  )
  select
    v_request_event_id,
    greatest(1, coalesce((item.value->>'decision_order')::integer, item.ordinality::integer)),
    route.provider_model_id,
    left(nullif(trim(item.value->>'provider'), ''), 256),
    left(nullif(trim(item.value->>'provider_api_model_id'), ''), 512),
    coalesce(nullif(item.value->>'decision', ''), 'ranked'),
    nullif(item.value->>'rank', '')::integer,
    nullif(item.value->>'score', '')::numeric,
    coalesce((item.value->>'selected')::boolean, false),
    coalesce((item.value->>'attempted')::boolean, false),
    left(nullif(item.value->>'breaker', ''), 64),
    case
      when nullif(item.value->>'breaker_until_ms', '') is null then null
      else to_timestamp((item.value->>'breaker_until_ms')::double precision / 1000.0)
    end,
    left(nullif(item.value->>'provider_status', ''), 64),
    left(nullif(item.value->>'provider_routing_status', ''), 64),
    left(nullif(item.value->>'model_routing_status', ''), 64),
    left(nullif(item.value->>'capability_status', ''), 64),
    left(nullif(item.value->>'exclusion_stage', ''), 128),
    left(nullif(item.value->>'exclusion_reason', ''), 256),
    coalesce(item.value->'score_factors', '{}'::jsonb)
  from jsonb_array_elements(v_routing_decisions) with ordinality as item(value, ordinality)
  left join lateral (
    select candidate.provider_model_id
    from public.v2_model_provider_routes candidate
    where candidate.provider_model_id = nullif(item.value->>'provider_model_id', '')
       or (
         candidate.provider_slug = nullif(item.value->>'provider', '')
         and candidate.provider_model_id =
           nullif(item.value->>'provider', '') || ':' || nullif(item.value->>'provider_api_model_id', '')
       )
       or (
         candidate.provider_slug = nullif(item.value->>'provider', '')
         and candidate.provider_model_slug = nullif(item.value->>'provider_api_model_id', '')
       )
    order by
      case when candidate.provider_model_id = nullif(item.value->>'provider_model_id', '') then 0 else 1 end,
      candidate.provider_model_id
    limit 1
  ) route on true
  where nullif(trim(item.value->>'provider'), '') is not null;

  return v_request_event_id;
end;
$$;


--
-- Name: FUNCTION ingest_v2_gateway_request_with_routing(p_event jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ingest_v2_gateway_request_with_routing(p_event jsonb) IS 'Atomically ingests request telemetry while preserving exact provider/model route identities.';


