--

CREATE FUNCTION public.is_active_invite_for_workspace(p_invite_id uuid, p_team_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.team_invites ti
    where ti.id = p_invite_id
      and ti.team_id = p_team_id
      and (ti.expires_at is null or ti.expires_at > now())
      and (ti.max_uses is null or coalesce(ti.uses_count, 0) < ti.max_uses)
  );
$$;


