--
-- Name: refresh_public_model_task_daily(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_public_model_task_daily(p_since date DEFAULT (CURRENT_DATE - 1)) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('refresh_public_model_task_daily')
  );

  delete from public.public_model_task_daily
  where usage_date >= coalesce(p_since, current_date - 1);

  insert into public.public_model_task_daily (
    usage_date, taxonomy_slug, primary_category, model_slug, provider_slug,
    workspace_count, request_count, input_tokens, output_tokens, updated_at
  )
  select
    daily.usage_date,
    classifier.slug,
    daily.primary_category,
    daily.model_slug,
    daily.provider_slug,
    count(*) as workspace_count,
    sum(daily.request_count) as request_count,
    sum(daily.input_tokens) as input_tokens,
    sum(daily.output_tokens) as output_tokens,
    now()
  from public.request_classification_daily daily
  join public.workspace_classifiers classifier on classifier.id = daily.classifier_id
  where daily.usage_date >= coalesce(p_since, current_date - 1)
    and classifier.kind = 'phaseo_task'
  group by daily.usage_date, classifier.slug, daily.primary_category,
    daily.model_slug, daily.provider_slug
  on conflict (usage_date, taxonomy_slug, primary_category, model_slug, provider_slug)
  do update set
    workspace_count = excluded.workspace_count,
    request_count = excluded.request_count,
    input_tokens = excluded.input_tokens,
    output_tokens = excluded.output_tokens,
    updated_at = excluded.updated_at;
end;
$$;


--
-- Name: refresh_public_model_user_usage_daily(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_public_model_user_usage_daily(p_since timestamp with time zone DEFAULT (now() - '90 days'::interval), p_until timestamp with time zone DEFAULT now()) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_since_date date := date_trunc('day', p_since at time zone 'utc')::date;
  v_until_date date := date_trunc('day', p_until at time zone 'utc')::date;
begin
  delete from public.public_model_user_usage_daily d
  where d.day_bucket >= v_since_date
    and d.day_bucket <= v_until_date;

  insert into public.public_model_user_usage_daily (
    day_bucket,
    model_id,
    provider_id,
    actor_hash,
    requests,
    tokens,
    refreshed_at
  )
  with normalized as (
    select
      date_trunc('day', gr.created_at at time zone 'utc')::date as day_bucket,
      public.public_leaderboard_model_id(
        gr.canonical_model_id,
        gr.model_id,
        gr.requested_model_id,
        gr.routed_model_id,
        authoritative.api_model_id,
        gr.provider,
        authoritative.pricing_plan,
        authoritative.is_free_variant
      ) as model_id,
      coalesce(nullif(gr.provider, ''), 'unknown') as provider_id,
      coalesce(
        nullif(to_jsonb(gr)->>'oauth_user_id', ''),
        nullif(to_jsonb(gr)->>'end_user_id', ''),
        nullif(to_jsonb(gr)->>'workspace_id', ''),
        nullif(to_jsonb(gr)->>'team_id', ''),
        nullif(to_jsonb(gr)->>'key_id', '')
      ) as actor_key,
      public.gateway_usage_nonnegative_bigint(
        coalesce(public.gateway_usage_total_tokens(gr.usage), gr.usage_total_tokens, 0)
      ) as total_tokens
    from private.v2_rpc_gateway_requests_compat gr
    left join public.v2_request_facts fact
      on fact.request_event_id = gr.id
    left join public.gateway_requests authoritative
      on authoritative.id = fact.gateway_request_id
     and authoritative.created_at = fact.gateway_request_created_at
    where gr.created_at >= p_since
      and gr.created_at < p_until
      and gr.success is true
  )
  select
    n.day_bucket,
    n.model_id,
    n.provider_id,
    md5('public-model-user:' || n.actor_key) as actor_hash,
    count(*)::bigint as requests,
    sum(n.total_tokens)::bigint as tokens,
    now() as refreshed_at
  from normalized n
  where n.actor_key is not null
    and n.model_id is not null
    and n.model_id <> ''
    and lower(n.model_id) not in ('unknown', 'other')
  group by n.day_bucket, n.model_id, n.provider_id, md5('public-model-user:' || n.actor_key);
end;
$$;


--
-- Name: refresh_request_classification_rollup(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_request_classification_rollup(p_contribution_id uuid, p_classifier_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_contribution public.data_contributions%rowtype;
  v_category text;
begin
  select * into v_contribution
  from public.data_contributions
  where id = p_contribution_id;
  if not found then return; end if;

  select primary_category into v_category
  from public.request_classifications
  where contribution_id = p_contribution_id
    and classifier_id = p_classifier_id;
  if not found then return; end if;

  if not exists (
    select 1 from public.workspace_classifiers where id = p_classifier_id
  ) then
    return;
  end if;

  insert into public.request_classification_daily (
    usage_date, workspace_id, classifier_id, primary_category, model_slug,
    provider_slug, request_count, input_tokens, output_tokens, updated_at
  )
  select
    contribution.occurred_at::date,
    contribution.workspace_id,
    classification.classifier_id,
    classification.primary_category,
    contribution.model_slug,
    coalesce(contribution.provider_slug, ''),
    count(*),
    coalesce(sum(contribution.input_tokens), 0),
    coalesce(sum(contribution.output_tokens), 0),
    now()
  from public.request_classifications classification
  join public.data_contributions contribution on contribution.id = classification.contribution_id
  where contribution.workspace_id = v_contribution.workspace_id
    and contribution.occurred_at::date = v_contribution.occurred_at::date
    and classification.classifier_id = p_classifier_id
    and classification.primary_category = v_category
    and contribution.model_slug = v_contribution.model_slug
    and coalesce(contribution.provider_slug, '') = coalesce(v_contribution.provider_slug, '')
  group by contribution.occurred_at::date, contribution.workspace_id,
    classification.classifier_id, classification.primary_category,
    contribution.model_slug, coalesce(contribution.provider_slug, '')
  on conflict (usage_date, workspace_id, classifier_id, primary_category, model_slug, provider_slug)
  do update set
    request_count = excluded.request_count,
    input_tokens = excluded.input_tokens,
    output_tokens = excluded.output_tokens,
    updated_at = excluded.updated_at;
end;
$$;


--
-- Name: refresh_v2_analytics_range(timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_v2_analytics_range(p_since timestamp with time zone, p_until timestamp with time zone DEFAULT now(), p_workspace_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  result jsonb;
begin
  insert into public.v2_analytics_outbox (
    request_event_id, workspace_id, occurred_at, status,
    attempt_count, available_at, last_error, updated_at
  )
  select
    fact.request_event_id, fact.workspace_id, fact.occurred_at, 'pending',
    0, now(), null, now()
  from public.v2_request_facts fact
  where fact.occurred_at >= coalesce(p_since, '-infinity'::timestamptz)
    and fact.occurred_at < coalesce(p_until, 'infinity'::timestamptz)
    and (p_workspace_id is null or fact.workspace_id = p_workspace_id)
  on conflict (request_event_id) do update set
    status = 'pending',
    attempt_count = 0,
    available_at = now(),
    last_error = null,
    updated_at = now();

  loop
    result := public.process_v2_analytics_outbox(2000);
    exit when coalesce((result->>'selected')::integer, 0) = 0;
  end loop;
end;
$$;


--
-- Name: FUNCTION refresh_v2_analytics_range(p_since timestamp with time zone, p_until timestamp with time zone, p_workspace_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.refresh_v2_analytics_range(p_since timestamp with time zone, p_until timestamp with time zone, p_workspace_id uuid) IS 'Queues and recomputes V2 analytics grains for a bounded time/workspace range.';


--
-- Name: refresh_v2_pricing_variant_links(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_v2_pricing_variant_links() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with updated as (
    update public.v2_pricing_skus sku
    set route_variant_id = variant.variant_id,
        updated_at = now()
    from public.v2_route_variants variant
    where variant.provider_model_id = sku.provider_model_id
      and variant.service_tier_slug = coalesce(sku.service_tier_slug, 'standard')
      and variant.variant_key = 'global:' || coalesce(sku.service_tier_slug, 'standard')
      and sku.route_variant_id is distinct from variant.variant_id
    returning 1
  )
  select count(*)::integer from updated;
$$;


--
-- Name: refresh_v2_provider_health_for_attempt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_v2_provider_health_for_attempt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  request_row record;
  provider_slug_value text;
begin
  select fact.occurred_at, coalesce(fact.routed_model_slug, fact.requested_model_slug) as model_slug
    into request_row
  from public.v2_request_facts fact
  where fact.request_event_id = new.request_event_id;
  if request_row.model_slug is null or new.provider_model_id is null then return new; end if;

  select route.provider_slug into provider_slug_value
  from public.v2_model_provider_routes route
  where route.provider_model_id = new.provider_model_id;
  if provider_slug_value is null then return new; end if;

  delete from public.v2_public_provider_health_daily
  where usage_date = request_row.occurred_at::date
    and model_slug = request_row.model_slug
    and provider_model_id = new.provider_model_id;

  insert into public.v2_public_provider_health_daily (
    usage_date, model_slug, provider_model_id, provider_slug, request_count,
    successful_request_count, attempt_count, successful_attempts, failed_attempts,
    fallback_attempts, latency_sum_ms, latency_count
  )
  select request_row.occurred_at::date, request_row.model_slug, new.provider_model_id, provider_slug_value,
    count(distinct fact.request_event_id), count(distinct fact.request_event_id) filter (where attempt.success),
    count(*), count(*) filter (where attempt.success), count(*) filter (where not attempt.success),
    count(*) filter (where attempt.attempt_number > 1),
    coalesce(sum(attempt.latency_ms) filter (where attempt.latency_ms is not null), 0), count(attempt.latency_ms)
  from public.v2_request_attempts attempt
  join public.v2_request_facts fact on fact.request_event_id = attempt.request_event_id
  where fact.occurred_at::date = request_row.occurred_at::date
    and coalesce(fact.routed_model_slug, fact.requested_model_slug) = request_row.model_slug
    and attempt.provider_model_id = new.provider_model_id;
  return new;
end;
$$;


--
-- Name: reject_workspace_join_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_workspace_join_request(p_request_id uuid) RETURNS TABLE(id uuid, team_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_req public.team_join_requests%rowtype;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'Unauthorized';
  end if;

  select *
    into v_req
  from public.team_join_requests
  where team_join_requests.id = p_request_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'Join request not found';
  end if;

  if v_req.status <> 'pending'::public.join_request_status then
    raise exception using errcode = '23514', message = 'Request already decided';
  end if;

  if not public.is_team_admin(v_req.team_id) then
    raise exception using errcode = '42501', message = 'Only owners or admins may reject join requests.';
  end if;

  return query
  update public.team_join_requests r
     set status = 'denied'::public.join_request_status,
         decided_by = v_user_id,
         decided_at = now()
   where r.id = v_req.id
     and r.status = 'pending'::public.join_request_status
  returning r.id, r.team_id;

  if not found then
    raise exception using errcode = '23514', message = 'Request already decided';
  end if;
end;
$$;


--
-- Name: release_gateway_async_webhook_delivery_claim(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_gateway_async_webhook_delivery_claim(p_workspace_id uuid, p_kind text, p_internal_id text, p_delivery_key text, p_claim_token text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with changed as (
    update public.gateway_async_webhook_deliveries
    set status = 'pending', claim_token = null, claimed_at = null, updated_at = now()
    where workspace_id = p_workspace_id and kind = p_kind
      and internal_id = p_internal_id and delivery_key = p_delivery_key
      and status = 'claimed' and claim_token = p_claim_token
    returning 1
  ) select exists(select 1 from changed);
$$;


--
-- Name: rename_workspace_publisher_handle(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rename_workspace_publisher_handle(target_workspace_id uuid, actor_user_id uuid, requested_handle text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $_$
declare
  workspace_row public.workspaces%rowtype;
  normalized_handle text := lower(trim(requested_handle));
begin
  if normalized_handle !~ '^[a-z0-9][a-z0-9_-]{2,39}$' then
    raise exception 'invalid_publisher_handle';
  end if;

  select * into workspace_row
  from public.workspaces
  where id = target_workspace_id
  for update;
  if not found then raise exception 'workspace_not_found'; end if;

  if workspace_row.owner_user_id <> actor_user_id and not exists (
    select 1 from public.workspace_members member
    where member.workspace_id = target_workspace_id
      and member.user_id = actor_user_id
      and member.role in ('owner', 'admin')
  ) then
    raise exception 'publisher_handle_forbidden';
  end if;

  if normalized_handle = workspace_row.publisher_handle then
    return normalized_handle;
  end if;

  if exists (
    select 1 from public.workspaces workspace
    where lower(workspace.publisher_handle) = normalized_handle
      and workspace.id <> target_workspace_id
  ) or exists (
    select 1 from public.workspace_publisher_handle_aliases alias
    where alias.handle = normalized_handle
      and alias.workspace_id <> target_workspace_id
  ) then
    raise exception 'publisher_handle_reserved' using errcode = '23505';
  end if;

  insert into public.workspace_publisher_handle_aliases (handle, workspace_id)
  values (workspace_row.publisher_handle, target_workspace_id)
  on conflict (handle) do nothing;

  delete from public.workspace_publisher_handle_aliases
  where workspace_id = target_workspace_id and handle = normalized_handle;

  update public.workspaces
  set publisher_handle = normalized_handle
  where id = target_workspace_id;

  return normalized_handle;
end
$_$;


--
-- Name: reorder_v2_byok_key(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reorder_v2_byok_key(p_workspace_id uuid, p_key_id uuid, p_direction text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  current_key public.byok_keys%rowtype;
  adjacent_key public.byok_keys%rowtype;
begin
  if p_direction not in ('up', 'down') then
    raise exception using errcode = '22023', message = 'invalid_direction';
  end if;
  if not public.is_workspace_admin(p_workspace_id) then
    raise exception using errcode = '42501', message = 'forbidden';
  end if;

  select * into current_key
  from public.byok_keys
  where id = p_key_id and workspace_id = p_workspace_id
  for update;
  if not found then return false; end if;

  if p_direction = 'up' then
    select * into adjacent_key
    from public.byok_keys
    where workspace_id = current_key.workspace_id
      and provider_id = current_key.provider_id
      and routing_mode = current_key.routing_mode
      and (sort_order, created_at, id) < (current_key.sort_order, current_key.created_at, current_key.id)
    order by sort_order desc, created_at desc, id desc
    limit 1
    for update;
  else
    select * into adjacent_key
    from public.byok_keys
    where workspace_id = current_key.workspace_id
      and provider_id = current_key.provider_id
      and routing_mode = current_key.routing_mode
      and (sort_order, created_at, id) > (current_key.sort_order, current_key.created_at, current_key.id)
    order by sort_order, created_at, id
    limit 1
    for update;
  end if;
  if not found then return true; end if;

  update public.byok_keys
  set sort_order = case
    when id = current_key.id then adjacent_key.sort_order
    else current_key.sort_order
  end
  where id in (current_key.id, adjacent_key.id);
  return true;
end;
$$;


--
-- Name: replace_gateway_dynamic_route_keys(uuid, uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_gateway_dynamic_route_keys(p_route_id uuid, p_key_ids uuid[], p_attached_by uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1
    from unnest(coalesce(p_key_ids, '{}'::uuid[])) requested(key_id)
    left join public.keys gateway_key on gateway_key.id = requested.key_id
    left join public.gateway_dynamic_routes route on route.id = p_route_id
    where gateway_key.id is null
      or route.id is null
      or gateway_key.workspace_id <> route.workspace_id
  ) then
    raise exception 'dynamic_route_key_workspace_mismatch';
  end if;

  delete from public.gateway_dynamic_route_keys
  where route_id = p_route_id
    or key_id = any(coalesce(p_key_ids, '{}'::uuid[]));

  insert into public.gateway_dynamic_route_keys (route_id, key_id, attached_by)
  select p_route_id, requested.key_id, p_attached_by
  from unnest(coalesce(p_key_ids, '{}'::uuid[])) requested(key_id);
end;
$$;


--
-- Name: replace_subscription_plan_bundle(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_subscription_plan_bundle(p_plan jsonb, p_models jsonb DEFAULT '[]'::jsonb, p_features jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_plan_uuid uuid;
  v_models jsonb := coalesce(p_models, '[]'::jsonb);
  v_features jsonb := coalesce(p_features, '[]'::jsonb);
begin
  if p_plan is null then raise exception 'p_plan is required'; end if;
  if jsonb_typeof(v_models) <> 'array' then raise exception 'p_models must be a JSON array'; end if;
  if jsonb_typeof(v_features) <> 'array' then raise exception 'p_features must be a JSON array'; end if;

  v_plan_uuid := nullif(p_plan->>'plan_uuid', '')::uuid;
  if v_plan_uuid is null then raise exception 'p_plan.plan_uuid is required'; end if;

  insert into public.v2_subscription_plans (
    plan_uuid, plan_id, name, lab_slug, description, frequency,
    price, currency, link, other_info, created_at, updated_at
  ) values (
    v_plan_uuid,
    p_plan->>'plan_id',
    p_plan->>'name',
    p_plan->>'organisation_id',
    p_plan->>'description',
    p_plan->>'frequency',
    nullif(p_plan->>'price', '')::numeric,
    p_plan->>'currency',
    p_plan->>'link',
    coalesce(p_plan->'other_info', '{}'::jsonb),
    coalesce(nullif(p_plan->>'created_at', '')::timestamptz, now()),
    now()
  )
  on conflict (plan_uuid) do update set
    plan_id = excluded.plan_id,
    name = excluded.name,
    lab_slug = excluded.lab_slug,
    description = excluded.description,
    frequency = excluded.frequency,
    price = excluded.price,
    currency = excluded.currency,
    link = excluded.link,
    other_info = excluded.other_info,
    updated_at = now();

  delete from public.v2_subscription_plan_models where plan_uuid = v_plan_uuid;
  insert into public.v2_subscription_plan_models (
    plan_uuid, model_slug, model_info, rate_limit, other_info
  )
  select
    v_plan_uuid,
    model.model_id,
    coalesce(model.model_info, '{}'::jsonb),
    coalesce(model.rate_limit, '{}'::jsonb),
    coalesce(model.other_info, '{}'::jsonb)
  from jsonb_to_recordset(v_models) as model(
    plan_uuid uuid, model_id text, model_info jsonb, rate_limit jsonb, other_info jsonb
  );

  delete from public.v2_subscription_plan_features where plan_uuid = v_plan_uuid;
  insert into public.v2_subscription_plan_features (
    plan_uuid, feature_name, feature_value, feature_description, other_info
  )
  select
    v_plan_uuid,
    feature.feature_name,
    case
      when feature.feature_value is null then null
      when jsonb_typeof(feature.feature_value) = 'string' then feature.feature_value #>> '{}'
      else feature.feature_value::text
    end,
    feature.feature_description,
    coalesce(feature.other_info, '{}'::jsonb)
  from jsonb_to_recordset(v_features) as feature(
    plan_uuid uuid, feature_name text, feature_value jsonb,
    feature_description text, other_info jsonb
  );
end;
$$;


--
-- Name: FUNCTION replace_subscription_plan_bundle(p_plan jsonb, p_models jsonb, p_features jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.replace_subscription_plan_bundle(p_plan jsonb, p_models jsonb, p_features jsonb) IS 'Atomically replaces a subscription plan bundle in canonical V2 tables.';


--
-- Name: resolve_public_model_id(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_public_model_id(p_model_id text, p_provider text DEFAULT NULL::text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
with direct_match as (
  select dm.model_id as canonical_model_id
  from private.v2_rpc_models_compat dm
  where dm.model_id = p_model_id
  limit 1
),
alias_match as (
  select a.api_model_id as canonical_model_id
  from (select alias_slug, model_slug as api_model_id, enabled as is_enabled, effective_from, effective_to, metadata, created_at, updated_at from public.v2_model_aliases) a
  where a.alias_slug = p_model_id
    and coalesce(a.is_enabled, true)
  limit 1
),
provider_match as (
  select coalesce(nullif(pm.model_id, ''), pm.api_model_id) as canonical_model_id,
         pm.is_active_gateway,
         pm.updated_at
  from private.v2_rpc_routes_compat pm
  where (p_provider is null or pm.provider_id = p_provider)
    and (
      pm.model_id = p_model_id
      or pm.api_model_id = p_model_id
      or pm.provider_api_model_id = p_model_id
      or pm.provider_model_slug = p_model_id
    )
  order by pm.is_active_gateway desc, pm.updated_at desc nulls last
  limit 1
)
select canonical_model_id
from (
  select 0 as ord, canonical_model_id from direct_match
  union all
  select 1 as ord, canonical_model_id from alias_match
  union all
  select 2 as ord, canonical_model_id from provider_match
) candidates
where canonical_model_id is not null
  and btrim(canonical_model_id) <> ''
order by ord
limit 1;
$$;


--
-- Name: FUNCTION resolve_public_model_id(p_model_id text, p_provider text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resolve_public_model_id(p_model_id text, p_provider text) IS 'Resolves canonical public model ids from canonical ids, aliases, and provider-facing model identifiers only.';


--
-- Name: revoke_oauth_on_workspace_member_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_oauth_on_workspace_member_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.oauth_authorizations
  set revoked_at = coalesce(revoked_at, now())
  where user_id = old.user_id
    and workspace_id = old.workspace_id
    and revoked_at is null;

  update public.oauth_refresh_tokens
  set revoked_at = coalesce(revoked_at, now())
  where user_id = old.user_id
    and workspace_id = old.workspace_id
    and revoked_at is null;

  return old;
end;
$$;


--
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rls_auto_enable() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


--
-- Name: rotate_oauth_refresh_token(text, text, timestamp with time zone, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rotate_oauth_refresh_token(p_current_token_hash text, p_next_token_hash text, p_next_expires_at timestamp with time zone, p_scopes text[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  token_identity public.oauth_refresh_tokens%rowtype;
  current_token public.oauth_refresh_tokens%rowtype;
  token_family uuid;
  granted_scopes text[];
begin
  -- Read identity without a row lock. Taking the token lock here would invert
  -- the member-delete trigger's membership -> authorization -> token order.
  select * into token_identity
  from public.oauth_refresh_tokens
  where token_hash = p_current_token_hash;

  if not found then
    return 'invalid';
  end if;

  perform 1
  from public.workspace_members member
  where member.user_id = token_identity.user_id
    and member.workspace_id = token_identity.workspace_id
  for key share;

  if not found then
    return 'invalid';
  end if;

  select authorization_row.scopes into granted_scopes
  from public.oauth_authorizations authorization_row
  where authorization_row.user_id = token_identity.user_id
    and authorization_row.workspace_id = token_identity.workspace_id
    and authorization_row.client_id = token_identity.client_id
    and authorization_row.revoked_at is null
  for update;

  if not found then
    return 'invalid';
  end if;

  -- Re-read and validate after acquiring locks because another rotation may
  -- have changed this token between the initial identity read and this lock.
  select * into current_token
  from public.oauth_refresh_tokens
  where token_hash = p_current_token_hash
  for update;

  if not found
    or current_token.user_id <> token_identity.user_id
    or current_token.workspace_id <> token_identity.workspace_id
    or current_token.client_id <> token_identity.client_id then
    return 'invalid';
  end if;

  token_family := coalesce(current_token.family_id, current_token.id);

  if current_token.revoked_at is not null then
    update public.oauth_refresh_tokens
    set revoked_at = coalesce(revoked_at, now())
    where family_id = token_family;
    return 'reused';
  end if;

  if current_token.expires_at is not null and current_token.expires_at <= now() then
    update public.oauth_refresh_tokens set revoked_at = now() where id = current_token.id;
    return 'invalid';
  end if;

  update public.oauth_refresh_tokens
  set revoked_at = now(), last_used_at = now()
  where id = current_token.id;

  insert into public.oauth_refresh_tokens (
    token_hash, user_id, workspace_id, client_id, scopes, expires_at,
    rotated_from, family_id
  ) values (
    p_next_token_hash, current_token.user_id, current_token.workspace_id,
    current_token.client_id, granted_scopes, p_next_expires_at,
    current_token.id, token_family
  );

  return 'rotated';
end;
$$;


--
-- Name: workspace_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_settings (
    workspace_id uuid NOT NULL,
    routing_mode text DEFAULT 'balanced'::text NOT NULL,
    created_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    updated_at timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    byok_fallback_enabled boolean DEFAULT true NOT NULL,
    beta_channel_enabled boolean DEFAULT false NOT NULL,
    privacy_enable_paid_may_train boolean DEFAULT true NOT NULL,
    privacy_enable_free_may_train boolean DEFAULT true NOT NULL,
    privacy_enable_free_may_publish_prompts boolean DEFAULT true NOT NULL,
    privacy_enable_input_output_logging boolean DEFAULT true NOT NULL,
    privacy_zdr_only boolean DEFAULT false NOT NULL,
    provider_restriction_mode text DEFAULT 'none'::text NOT NULL,
    provider_restriction_provider_ids text[] DEFAULT '{}'::text[] NOT NULL,
    provider_restriction_enforce_allowed boolean DEFAULT false NOT NULL,
    sso_enabled boolean DEFAULT false NOT NULL,
    sso_enforced boolean DEFAULT false NOT NULL,
    sso_mode text DEFAULT 'none'::text NOT NULL,
    sso_provider_identifier text,
    sso_domains text[] DEFAULT '{}'::text[] NOT NULL,
    alpha_channel_enabled boolean DEFAULT false NOT NULL,
    gateway_plugins jsonb DEFAULT '[]'::jsonb NOT NULL,
    io_logging_enabled boolean DEFAULT false NOT NULL,
    io_logging_retention_days integer DEFAULT 90 NOT NULL,
    io_logging_include_provider_payloads boolean DEFAULT true NOT NULL,
    io_logging_updated_at timestamp with time zone,
    data_contribution_enabled boolean DEFAULT false NOT NULL,
    data_contribution_policy_version text,
    data_contribution_consented_at timestamp with time zone,
    data_contribution_consented_by uuid,
    data_contribution_sample_rate_bps integer DEFAULT 10000 NOT NULL,
    data_contribution_classifier_sample_rate_bps integer DEFAULT 1000 NOT NULL,
    data_contribution_discount_bps integer DEFAULT 100 NOT NULL,
    response_healing_enabled boolean DEFAULT false NOT NULL,
    response_healing_locked boolean DEFAULT false NOT NULL,
    response_healing_mode text DEFAULT 'safe'::text NOT NULL,
    cache_aware_routing_enabled boolean DEFAULT true NOT NULL,
    low_balance_email_enabled boolean DEFAULT false NOT NULL,
    low_balance_email_threshold_nanos bigint DEFAULT 0 NOT NULL,
    low_balance_email_last_sent_at timestamp with time zone,
    low_balance_email_last_sent_balance_nanos bigint,
    auto_top_up_failure_email_enabled boolean DEFAULT true NOT NULL,
    payment_method_expiring_email_enabled boolean DEFAULT true NOT NULL,
    model_restriction_mode text DEFAULT 'none'::text NOT NULL,
    model_restriction_model_ids text[] DEFAULT '{}'::text[] NOT NULL,
    io_logging_billing_status text DEFAULT 'active'::text NOT NULL,
    io_logging_grace_until timestamp with time zone,
    io_logging_last_billed_at timestamp with time zone,
    io_logging_last_billing_warning_at timestamp with time zone,
    io_logging_last_billing_warning_kind text,
    io_logging_price_per_million_units_nanos bigint DEFAULT 0 NOT NULL,
    CONSTRAINT workspace_settings_alpha_requires_beta_channel_check CHECK (((alpha_channel_enabled = false) OR (beta_channel_enabled = true))),
    CONSTRAINT workspace_settings_data_contribution_classifier_sample_rate_che CHECK (((data_contribution_classifier_sample_rate_bps >= 0) AND (data_contribution_classifier_sample_rate_bps <= 10000))),
    CONSTRAINT workspace_settings_data_contribution_consent_check CHECK (((NOT data_contribution_enabled) OR ((data_contribution_policy_version IS NOT NULL) AND (data_contribution_consented_at IS NOT NULL)))),
    CONSTRAINT workspace_settings_data_contribution_discount_check CHECK (((data_contribution_discount_bps >= 0) AND (data_contribution_discount_bps <= 10000))),
    CONSTRAINT workspace_settings_data_contribution_sample_rate_check CHECK (((data_contribution_sample_rate_bps >= 0) AND (data_contribution_sample_rate_bps <= 10000))),
    CONSTRAINT workspace_settings_io_logging_billing_status_check CHECK ((io_logging_billing_status = ANY (ARRAY['active'::text, 'grace'::text, 'suspended'::text]))),
    CONSTRAINT workspace_settings_io_logging_price_per_million_units_check CHECK ((io_logging_price_per_million_units_nanos >= 0)),
    CONSTRAINT workspace_settings_io_logging_retention_days_check CHECK (((io_logging_retention_days >= 90) AND (io_logging_retention_days <= 365))),
    CONSTRAINT workspace_settings_low_balance_threshold_nonnegative CHECK ((low_balance_email_threshold_nanos >= 0)),
    CONSTRAINT workspace_settings_model_restriction_mode_valid CHECK ((model_restriction_mode = ANY (ARRAY['none'::text, 'allowlist'::text, 'blocklist'::text]))),
    CONSTRAINT workspace_settings_provider_restriction_mode_check CHECK ((provider_restriction_mode = ANY (ARRAY['none'::text, 'allowlist'::text, 'blocklist'::text]))),
    CONSTRAINT workspace_settings_response_healing_mode_check CHECK ((response_healing_mode = ANY (ARRAY['safe'::text, 'strict'::text]))),
    CONSTRAINT workspace_settings_sso_mode_check CHECK ((sso_mode = ANY (ARRAY['none'::text, 'saml'::text, 'custom_oidc'::text])))
);


