-- Name: oauth_authorizations oauth_authorizations_select_authorized; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY oauth_authorizations_select_authorized ON public.oauth_authorizations FOR SELECT TO authenticated USING (((user_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
   FROM public.oauth_app_metadata metadata
  WHERE ((metadata.client_id = oauth_authorizations.client_id) AND public.is_workspace_member(metadata.workspace_id))))));


